def _attempt_export_required_control_paths(
    contract: T09ProviderContract,
) -> tuple[str, ...]:
    """Map the historical control snapshot list onto the selected contract root."""

    root = _contract_control_root_name(contract)
    return tuple(
        f"{root}/{relative.removeprefix('pilot-v7/')}"
        for relative in ATTEMPT_EXPORT_REQUIRED_CONTROL_PATHS
    )


class T09HostError(RuntimeError):
    """The authorized host would violate its exact T09 contract."""


class CleanupExportEvidenceError(T09HostError):
    """Cleanup export phase evidence is missing, contradictory, or unsafe."""


@contextlib.contextmanager
def hard_deadline(seconds: float, *, message: str) -> Iterator[None]:
    """Bound one synchronous evidence operation without creating a watchdog."""

    if not 0 < seconds <= MAX_CONDITION_WALL_SECONDS:
        raise T09HostError(message)
    previous_handler = signal.getsignal(signal.SIGALRM)

    def expired(_signum: int, _frame: object) -> None:
        raise T09HostError(message)

    signal.signal(signal.SIGALRM, expired)
    signal.setitimer(signal.ITIMER_REAL, seconds)
    try:
        yield
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, previous_handler)


def utc_now() -> str:
    return datetime.now(UTC).isoformat().replace("+00:00", "Z")


def file_sha256(path: Path) -> str:
    _recover_atomic_publication(path)
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while chunk := handle.read(1_048_576):
            digest.update(chunk)
    return digest.hexdigest()


def _open_parent_directory_no_follow(path: Path) -> tuple[int, str]:
    """Open every parent component without traversing a symlink."""

    if not path.is_absolute() or path.name in {"", ".", ".."}:
        raise T09HostError("archive staging paths must be absolute file paths")
    flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_CLOEXEC", 0)
    descriptor = os.open("/", flags)
    try:
        for component in path.parts[1:-1]:
            if component in {"", ".", ".."}:
                raise T09HostError("archive staging path contains an unsafe component")
            next_descriptor = os.open(
                component,
                flags | getattr(os, "O_NOFOLLOW", 0),
                dir_fd=descriptor,
            )
            os.close(descriptor)
            descriptor = next_descriptor
        return descriptor, path.name
    except BaseException:
        os.close(descriptor)
        raise


def _sha256_descriptor(descriptor: int) -> str:
    os.lseek(descriptor, 0, os.SEEK_SET)
    digest = hashlib.sha256()
    while chunk := os.read(descriptor, 1_048_576):
        digest.update(chunk)
    os.lseek(descriptor, 0, os.SEEK_SET)
    return digest.hexdigest()


def _copy_descriptor_exact(source: int, destination: int) -> int:
    copied = 0
    os.lseek(source, 0, os.SEEK_SET)
    while chunk := os.read(source, 1_048_576):
        offset = 0
        while offset < len(chunk):
            written = os.write(destination, chunk[offset:])
            if written <= 0:
                raise T09HostError("archive staging copy made no progress")
            offset += written
            copied += written
    return copied


def stage_verified_archive(
    source_path: Path,
    canonical_target_path: Path,
    expected_size: int,
    expected_sha256: str,
) -> dict[str, object]:
    """Stage one private archive by content, never by its operator pathname."""

    if (
        type(expected_size) is not int
        or expected_size <= 0
        or re.fullmatch(r"[a-f0-9]{64}", expected_sha256) is None
    ):
        raise T09HostError("archive staging expectation is invalid")
    source_parent, source_name = _open_parent_directory_no_follow(source_path)
    source_descriptor = -1
    target_parent = -1
    target_descriptor = -1
    target_name = ""
    target_created = False
    try:
        source_descriptor = os.open(
            source_name,
            os.O_RDONLY
            | getattr(os, "O_NONBLOCK", 0)
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_CLOEXEC", 0),
            dir_fd=source_parent,
        )
        source_before = os.fstat(source_descriptor)
        if not stat.S_ISREG(source_before.st_mode):
            raise T09HostError("archive staging source is not a regular file")
        if source_before.st_size != expected_size:
            raise T09HostError("archive staging source size drifted")
        if _sha256_descriptor(source_descriptor) != expected_sha256:
            raise T09HostError("archive staging source hash drifted")

        target_parent, target_name = _open_parent_directory_no_follow(canonical_target_path)
        target_descriptor = os.open(
            target_name,
            os.O_RDWR
            | os.O_CREAT
            | os.O_EXCL
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_CLOEXEC", 0),
            0o600,
            dir_fd=target_parent,
        )
        target_created = True
        os.fchmod(target_descriptor, 0o600)
        copied = _copy_descriptor_exact(source_descriptor, target_descriptor)
        os.fsync(target_descriptor)
        os.fsync(target_parent)
        target_metadata = os.fstat(target_descriptor)
        target_sha256 = _sha256_descriptor(target_descriptor)
        source_after = os.fstat(source_descriptor)
        source_identity_before = (
            source_before.st_dev,
            source_before.st_ino,
            source_before.st_size,
            source_before.st_mtime_ns,
            source_before.st_ctime_ns,
            source_before.st_mode,
        )
        source_identity_after = (
            source_after.st_dev,
            source_after.st_ino,
            source_after.st_size,
            source_after.st_mtime_ns,
            source_after.st_ctime_ns,
            source_after.st_mode,
        )
        if (
            copied != expected_size
            or not stat.S_ISREG(target_metadata.st_mode)
            or target_metadata.st_size != expected_size
            or stat.S_IMODE(target_metadata.st_mode) != 0o600
            or target_sha256 != expected_sha256
            or source_identity_after != source_identity_before
        ):
            raise T09HostError("archive staging target revalidation failed")
        return {
            "schema_version": "0.1.0",
            "archive_role": "historical-v4-real-evidence-regression",
            "source_provenance_category": "private-operator-run-owned-input",
            "source_absolute_path_retained": False,
            "source_no_follow_regular_file": True,
            "source_unchanged": True,
            "bytes": expected_size,
            "sha256": expected_sha256,
            "canonical_staged_destination": canonical_target_path.as_posix(),
            "exclusive_creation": True,
            "target_mode": "0600",
            "target_fsync": True,
            "parent_directory_fsync": True,
            "target_rehash_verified": True,
        }
    except BaseException:
        if target_created and target_parent >= 0 and target_name:
            with contextlib.suppress(OSError):
                os.unlink(target_name, dir_fd=target_parent)
                os.fsync(target_parent)
        raise
    finally:
        for descriptor in (target_descriptor, target_parent, source_descriptor, source_parent):
            if descriptor >= 0:
                with contextlib.suppress(OSError):
                    os.close(descriptor)


def git_file_sha256(repository: Path, commit: str, relative: str) -> str:
    retained = subprocess.run(
        ["git", "-C", str(repository), "show", f"{commit}:{relative}"],
        env=safe_environment(),
        stdin=subprocess.DEVNULL,
        capture_output=True,
        check=True,
        timeout=30,
    ).stdout
    return hashlib.sha256(retained).hexdigest()


def canonical_sha256(value: object) -> str:
    encoded = json.dumps(
        value,
        allow_nan=False,
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    ).encode()
    return hashlib.sha256(encoded).hexdigest()


def load_object(path: Path, *, label: str) -> dict[str, Any]:
    _recover_atomic_publication(path)
    value: object = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict) or not all(isinstance(key, str) for key in value):
        raise T09HostError(f"{label} must be a string-keyed JSON object")
    return cast(dict[str, Any], value)


def _provider_contract_from_document(
    document: dict[str, Any], *, label: str
) -> T09ProviderContract:
    """Resolve only the exact version named by one immutable control document."""

    plan_id = document.get("plan_id")
    if not isinstance(plan_id, str):
        raise T09HostError(f"{label} has no provider plan identity")
    try:
        return provider_contract_for_plan_id(plan_id)
    except T09ProviderContractError as exc:
        raise T09HostError(f"{label} names an unsupported provider contract") from exc


def _provider_contract_from_receipt(path: Path, *, label: str) -> T09ProviderContract:
    """Resolve only the exact version named by a retained provider receipt."""

    return _provider_contract_from_document(
        load_object(path.resolve(strict=True), label=label),
        label=label,
    )


def _argument_provider_contract(args: argparse.Namespace) -> T09ProviderContract:
    """Resolve the CLI's required exact provider-contract selector."""

    version = getattr(args, "provider_contract", None)
    if not isinstance(version, str):
        raise T09HostError("an explicit provider-contract selector is required")
    try:
        return provider_contract(version)
    except T09ProviderContractError as exc:
        raise T09HostError("provider-contract selector is unsupported") from exc


def _require_provider_contract(
    document: dict[str, Any],
    *,
    expected: T09ProviderContract,
    label: str,
) -> None:
    """Reject a control document minted for any other provider version."""

    if (
        _provider_contract_from_document(document, label=label) is not expected
        or document.get("host_run_id") != expected.host_run_id
    ):
        raise T09HostError(f"{label} belongs to another provider contract")


def _require_contract_run_id(
    contract: T09ProviderContract,
    run_id: str,
    *,
    label: str,
) -> None:
    """Reject a cross-version condition identity at a typed receipt boundary."""

    try:
        contract.validate_run_id(run_id)
    except T09ProviderContractError as exc:
        raise T09HostError(f"{label} run belongs to another campaign") from exc


def _require_supported_provider_runner(
    contract: T09ProviderContract,
    *,
    label: str,
) -> None:
    """Prevent this runner from relabeling evidence from an unsupported package."""

    if contract.version not in {"V11", "V12", "V13", "V14"}:
        raise T09HostError(f"{label} requires its frozen provider runner")


def _exact_keys(value: dict[str, Any], expected: set[str], *, label: str) -> None:
    if set(value) != expected:
        raise T09HostError(f"{label} fields drifted")


def _private_network_values(text: str) -> list[str]:
    hits: list[str] = []
    for match in _IPV4_TEXT.finditer(text):
        candidate = match.group(0)
        try:
            address = (
                ipaddress.ip_interface(candidate).ip
                if "/" in candidate
                else ipaddress.ip_address(candidate)
            )
        except ValueError:
            continue
        if not address.is_global:
            hits.append(candidate)
    return hits


def _stream_text_pattern_hits(path: Path) -> set[str]:
    labels: set[str] = set()
    overlap = b""
    with path.open("rb") as handle:
        while chunk := handle.read(MAX_PRIVACY_SCAN_CHUNK_BYTES):
            combined = overlap + chunk
            text = combined.decode("utf-8", errors="ignore")
            if _JUPYTER_URL.search(text):
                labels.add("jupyter-url")
            if _CREDENTIAL_TEXT.search(text):
                labels.add("credential-pattern")
            if _private_network_values(text):
                labels.add("private-network")
            overlap = combined[-4_096:]
    return labels


def _sensitive_json_paths(value: object, *, prefix: str = "$") -> list[str]:
    hits: list[str] = []
    if isinstance(value, dict):
        for raw_key, item in value.items():
            key = str(raw_key)
            path = f"{prefix}.{key}"
            if key.lower() in _SENSITIVE_JSON_KEYS and not (
                isinstance(item, dict)
                and item == {"reason": "structural-sensitive-field", "redacted": True}
            ):
                hits.append(path)
            hits.extend(_sensitive_json_paths(item, prefix=path))
    elif isinstance(value, list):
        for index, item in enumerate(value):
            hits.extend(_sensitive_json_paths(item, prefix=f"{prefix}[{index}]"))
    return hits


def privacy_violations(
    root: Path,
    *,
    excluded_relative_paths: frozenset[str] = frozenset(),
    excluded_relative_prefixes: frozenset[str] = frozenset(),
) -> list[str]:
    """Reject retained text/JSON that still contains explicitly prohibited values."""

    violations: list[str] = []
    for path in sorted(root.rglob("*")):
        relative = path.relative_to(root).as_posix()
        if relative in excluded_relative_paths or any(
            relative == prefix or relative.startswith(prefix + "/")
            for prefix in excluded_relative_prefixes
        ):
            continue
        if _JUPYTER_URL.search(relative):
            violations.append(f"{relative}:jupyter-url-path")
        if _CREDENTIAL_TEXT.search(relative):
            violations.append(f"{relative}:credential-pattern-path")
        if _private_network_values(relative):
            violations.append(f"{relative}:private-network-path")
        if (
            not path.is_file()
            or path.is_symlink()
            or path.name.endswith(".tar.gz")
            or path.stat().st_size > MAX_PILOT_DISK_BYTES
        ):
            continue
        for label in _stream_text_pattern_hits(path):
            violations.append(f"{relative}:{label}")
        if path.suffix == ".json" and path.stat().st_size <= MAX_PRIVACY_JSON_BYTES:
            try:
                value: object = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, UnicodeError, json.JSONDecodeError):
                continue
            if _sensitive_json_paths(value):
                violations.append(f"{relative}:sensitive-json-field")
        elif path.suffix == ".jsonl":
            with path.open("rb") as handle:
                for raw_line in handle:
                    if len(raw_line) > MAX_PRIVACY_LINE_BYTES:
                        continue
                    try:
                        value = json.loads(raw_line)
                    except (UnicodeError, json.JSONDecodeError):
                        continue
                    if _sensitive_json_paths(value):
                        violations.append(f"{relative}:sensitive-json-field")
                        break
    return sorted(set(violations))


def _atomic_publication_temporary(path: Path) -> Path:
    return path.parent / f".{path.name}.giclab-publication.tmp"


def _fsync_directory(path: Path) -> None:
    descriptor = os.open(
        path,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_CLOEXEC", 0),
    )
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def _recover_atomic_publication(path: Path) -> None:
    """Close the only hardlink crash window of an already-fsynced publication."""

    temporary = _atomic_publication_temporary(path)
    if not os.path.lexists(temporary) or not os.path.lexists(path):
        return
    temporary_metadata = temporary.lstat()
    published_metadata = path.lstat()
    if (
        stat.S_ISREG(temporary_metadata.st_mode)
        and stat.S_ISREG(published_metadata.st_mode)
        and temporary_metadata.st_dev == published_metadata.st_dev
        and temporary_metadata.st_ino == published_metadata.st_ino
        and temporary_metadata.st_nlink == 2
        and published_metadata.st_nlink == 2
    ):
        temporary.unlink()
        _fsync_directory(path.parent)


def recover_atomic_publications(root: Path) -> None:
    """Recover every completed supervisor publication after an abrupt exit."""

    if not root.exists() or root.is_symlink() or not root.is_dir():
        return
    for temporary in sorted(root.rglob(".*.giclab-publication.tmp")):
        name = temporary.name
        prefix = "."
        suffix = ".giclab-publication.tmp"
        if not name.startswith(prefix) or not name.endswith(suffix):
            continue
        target_name = name[len(prefix) : -len(suffix)]
        if target_name:
            _recover_atomic_publication(temporary.parent / target_name)


def _prepare_atomic_publication_temporary(path: Path) -> Path:
    temporary = _atomic_publication_temporary(path)
    _recover_atomic_publication(path)
    if os.path.lexists(temporary):
        if os.path.lexists(path):
            raise FileExistsError(path)
        metadata = temporary.lstat()
        if (
            not stat.S_ISREG(metadata.st_mode)
            or metadata.st_uid != os.getuid()
            or metadata.st_nlink != 1
            or stat.S_IMODE(metadata.st_mode) != 0o600
        ):
            raise T09HostError("incomplete atomic publication has unsafe metadata")
        temporary.unlink()
        _fsync_directory(path.parent)
    return temporary


def write_exclusive(path: Path, value: object) -> None:
    """Atomically publish one immutable JSON object with O_EXCL semantics."""

    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    encoded = (json.dumps(value, allow_nan=False, indent=2, sort_keys=True) + "\n").encode()
    temporary = _prepare_atomic_publication_temporary(path)
    descriptor = -1
    try:
        descriptor = os.open(
            temporary,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
            0o600,
        )
        offset = 0
        while offset < len(encoded):
            written = os.write(descriptor, encoded[offset:])
            if written <= 0:
                raise T09HostError("evidence write made no progress")
            offset += written
        os.fsync(descriptor)
        os.close(descriptor)
        descriptor = -1
        os.link(temporary, path, follow_symlinks=False)
    finally:
        if descriptor >= 0:
            os.close(descriptor)
        temporary.unlink(missing_ok=True)
        _fsync_directory(path.parent)


def write_bytes_exclusive(path: Path, value: bytes) -> None:
    """Atomically publish immutable binary evidence with O_EXCL semantics."""

    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    temporary = _prepare_atomic_publication_temporary(path)
    descriptor = -1
    try:
        descriptor = os.open(
            temporary,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
            0o600,
        )
        offset = 0
        while offset < len(value):
            written = os.write(descriptor, value[offset:])
            if written <= 0:
                raise T09HostError("binary evidence write made no progress")
            offset += written
        os.fsync(descriptor)
        os.close(descriptor)
        descriptor = -1
        os.link(temporary, path, follow_symlinks=False)
    finally:
        if descriptor >= 0:
            os.close(descriptor)
        temporary.unlink(missing_ok=True)
        _fsync_directory(path.parent)


def write_exclusive_or_validate(path: Path, value: object, *, label: str) -> None:
    """Publish one immutable JSON document or validate an identical prior publication."""

    if path.is_file() and not path.is_symlink():
        if load_object(path, label=label) != value:
            raise T09HostError(f"{label} drifted during crash recovery")
        return
    if os.path.lexists(path):
        raise T09HostError(f"{label} has an unsafe existing identity")
    write_exclusive(path, value)


def write_atomic(path: Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    encoded = (json.dumps(value, allow_nan=False, indent=2, sort_keys=True) + "\n").encode()
    temporary = path.with_suffix(f".{os.getpid()}.tmp")
    descriptor = os.open(
        temporary,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    try:
        offset = 0
        while offset < len(encoded):
            written = os.write(descriptor, encoded[offset:])
            if written <= 0:
                raise T09HostError("atomic evidence write made no progress")
            offset += written
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
    os.replace(temporary, path)
    parent_descriptor = os.open(
        path.parent,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_CLOEXEC", 0),
    )
    try:
        os.fsync(parent_descriptor)
    finally:
        os.close(parent_descriptor)


def safe_environment() -> dict[str, str]:
    """Return the explicit nonsecret host subprocess environment."""

    environment: dict[str, str] = {}
    for name in (
        "DOCKER_CONFIG",
        "DOCKER_CONTEXT",
        "DOCKER_HOST",
        "DOCKER_TLS_VERIFY",
        "LANG",
        "LC_ALL",
        "PATH",
        "SSL_CERT_DIR",
        "SSL_CERT_FILE",
        "TMPDIR",
        "XDG_RUNTIME_DIR",
    ):
        value = os.environ.get(name)
        if value is not None:
            environment[name] = value
    environment.update(
        {
            "GIT_CONFIG_NOSYSTEM": "1",
            "GIT_TERMINAL_PROMPT": "0",
            "PYTHONNOUSERSITE": "1",
        }
    )
    return environment


def enforce_host_core_limit() -> tuple[int, int]:
    """Disable cores in the trusted supervisor and every local child it spawns."""

    try:
        resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
        observed = resource.getrlimit(resource.RLIMIT_CORE)
    except (OSError, ValueError) as exc:
        raise T09HostError("host supervisor could not disable core dumps") from exc
    if observed != (0, 0):
        raise T09HostError("host supervisor core limit verification failed")
    return observed


def output(argv: list[str], *, timeout: int = 30) -> str:
    result = subprocess.run(
        argv,
        env=safe_environment(),
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        check=False,
        timeout=timeout,
    )
    if result.returncode != 0:
        raise T09HostError(f"command failed ({result.returncode}): {argv[0]}")
    return result.stdout.decode("utf-8", errors="strict").strip()


def run_logged(
    argv: list[str],
    *,
    evidence_root: Path,
    label: str,
    timeout: int,
    cleanup_journal: EarlyCleanupJournal | None = None,
    contract: T09ProviderContract,
) -> None:
    evidence_root.mkdir(parents=True, exist_ok=True, mode=0o700)
    with (
        (evidence_root / f"{label}.stdout").open("xb") as stdout,
        (evidence_root / f"{label}.stderr").open("xb") as stderr,
    ):
        docker_run = _docker_run_prefix(argv)
        if docker_run is None:
            result = subprocess.run(
                argv,
                env=safe_environment(),
                stdin=subprocess.DEVNULL,
                stdout=stdout,
                stderr=stderr,
                check=False,
                timeout=timeout,
            )
        else:
            if cleanup_journal is None:
                raise T09HostError("owned Docker execution lacks durable cleanup authority")
            prefix, _ = docker_run
            result = run_owned_docker(
                argv,
                prefix=prefix,
                label=label,
                evidence_root=evidence_root,
                stdout=stdout,
                stderr=stderr,
                timeout=timeout,
                cleanup_journal=cleanup_journal,
                contract=contract,
            )
    if result.returncode != 0:
        raise T09HostError(f"command failed ({result.returncode}): {label}")


def _docker_run_prefix(argv: list[str]) -> tuple[list[str], int] | None:
    """Locate an exact Docker ``run`` transport without string heuristics."""

    try:
        docker_index = argv.index("docker")
    except ValueError:
        return None
    run_index = docker_index + 1
    if run_index >= len(argv) or argv[run_index] != "run":
        return None
    prefix = argv[:run_index]
    if prefix not in (["docker"], ["sudo", "-n", "docker"]):
        raise T09HostError("Docker run transport prefix is not allowlisted")
    return list(prefix), run_index


def _owned_docker_name(
    label: str,
    *,
    contract: T09ProviderContract,
) -> str:
    normalized = re.sub(r"[^a-z0-9]+", "-", label.lower()).strip("-")
    if not normalized or len(normalized) > 80:
        raise T09HostError("owned Docker execution label is invalid")
    return f"{contract.container_prefix}utility-{normalized}"


def _owned_docker_role(label: str) -> str:
    normalized = re.sub(r"[^a-z0-9]+", "-", label.lower()).strip("-")
    if not normalized or len(normalized) > 80:
        raise T09HostError("owned Docker execution label is invalid")
    return f"utility-{normalized}"


def _docker_cidfile_owner_uid(prefix: list[str]) -> int:
    """Return the only valid cidfile owner for the selected Docker transport."""

    if prefix == ["docker"]:
        return os.getuid()
    if prefix == ["sudo", "-n", "docker"]:
        return 0
    raise T09HostError("Docker cidfile transport prefix is not allowlisted")


def _project_owned_docker_argv(
    argv: list[str],
    *,
    prefix: list[str],
    label: str,
    owned_role: str,
    contract: T09ProviderContract,
) -> tuple[list[str], str]:
    """Name and label every Docker run so cleanup can always find it."""

    if argv[: len(prefix) + 1] != [*prefix, "run"]:
        raise T09HostError("owned Docker execution is not an exact run invocation")
    suffix = list(argv[len(prefix) + 1 :])
    name = _owned_docker_name(label, contract=contract)
    existing_labels = [
        suffix[index + 1] for index, token in enumerate(suffix[:-1]) if token == "--label"
    ]
    owned_label_keys = {
        value.split("=", 1)[0]
        for value in existing_labels
        if value.startswith("giclab.t09.") and "=" in value
    }
    if (
        any(
            value.startswith("giclab.t09.plan=") and value != f"giclab.t09.plan={contract.plan_id}"
            for value in existing_labels
        )
        or any(
            value.startswith("giclab.t09.host_run=")
            and value != f"giclab.t09.host_run={contract.host_run_id}"
            for value in existing_labels
        )
        or sum(value.startswith("giclab.t09.plan=") for value in existing_labels) > 1
        or sum(value.startswith("giclab.t09.host_run=") for value in existing_labels) > 1
        or sum(value.startswith("giclab.t09.role=") for value in existing_labels) > 1
    ):
        raise T09HostError("owned Docker execution labels drifted")
    required_labels = [
        value
        for key, value in (
            ("giclab.t09.plan", f"giclab.t09.plan={contract.plan_id}"),
            ("giclab.t09.host_run", f"giclab.t09.host_run={contract.host_run_id}"),
            ("giclab.t09.role", f"giclab.t09.role={owned_role}"),
        )
        if key not in owned_label_keys
    ]
    if any(
        value.startswith("giclab.t09.role=") and value != f"giclab.t09.role={owned_role}"
        for value in existing_labels
    ):
        raise T09HostError("owned Docker execution role label drifted")
    injected_labels = [token for value in required_labels for token in ("--label", value)]
    if "--log-driver" in suffix and (
        suffix.count("--log-driver") != 1
        or suffix.index("--log-driver") + 1 >= len(suffix)
        or suffix[suffix.index("--log-driver") + 1] != "none"
    ):
        raise T09HostError("owned Docker execution log-retention policy drifted")
    log_policy = [] if "--log-driver" in suffix else ["--log-driver", "none"]
    if "--name" in suffix:
        if suffix.count("--name") != 1 or suffix[suffix.index("--name") + 1] != name:
            raise T09HostError("owned Docker execution name drifted")
        projected = [*prefix, "run", *injected_labels, *log_policy, *suffix]
    else:
        projected = [
            *prefix,
            "run",
            "--name",
            name,
            *injected_labels,
            *log_policy,
            *suffix,
        ]
    return projected, name


def run_owned_docker(
    argv: list[str],
    *,
    prefix: list[str],
    label: str,
    evidence_root: Path,
    stdout: IO[bytes] | int,
    stderr: IO[bytes] | int,
    timeout: int,
    cleanup_journal: EarlyCleanupJournal,
    environment: dict[str, str] | None = None,
    preexec_fn: Callable[[], None] | None = None,
    owned_role: str | None = None,
    contract: T09ProviderContract,
) -> subprocess.CompletedProcess[bytes]:
    """Run one named Docker container with immediate durable ID ownership."""

    role = _owned_docker_role(label) if owned_role is None else owned_role
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{0,95}", role):
        raise T09HostError("owned Docker role is malformed")
    projected, name = _project_owned_docker_argv(
        argv,
        prefix=prefix,
        label=label,
        owned_role=role,
        contract=contract,
    )
    if _container_id_by_exact_name(prefix, name) is not None:
        # Never let a failed ``docker run`` make its cleanup path delete a
        # pre-existing same-name object, even when it carries copied labels.
        raise T09HostError("owned Docker execution name is already occupied")
    cidfile = evidence_root / f"{label}.container-id"
    if os.path.lexists(cidfile):
        raise T09HostError("owned Docker container-ID file already exists")
    run_index = len(prefix)
    if projected[run_index] != "run":
        raise T09HostError("owned Docker run projection lost its transport boundary")
    projected = [
        *projected[: run_index + 1],
        "--cidfile",
        str(cidfile),
        *projected[run_index + 1 :],
    ]
    write_exclusive(
        evidence_root / f"{label}.container-command.json",
        {
            "schema_version": "0.1.0",
            "container_name": name,
            "argv": projected,
            "argv_sha256": canonical_sha256(projected),
            "owned_by_plan": contract.plan_id,
            "owned_by_host_run": contract.host_run_id,
            "owned_role": role,
        },
    )
    result: subprocess.CompletedProcess[bytes] | None = None
    process: subprocess.Popen[bytes] | None = None
    primary_error: BaseException | None = None
    container_id: str | None = None
    owned_identity: OwnedContainerIdentity | None = None

    def register_published_identity() -> None:
        nonlocal container_id, owned_identity
        observed = _read_owned_docker_cidfile(cidfile, prefix=prefix)
        if observed is None:
            return
        if container_id is not None and container_id != observed:
            raise T09HostError("owned Docker container-ID changed after publication")
        container_id = observed
        if owned_identity is None:
            candidate = OwnedContainerIdentity(
                container_id=observed,
                name=name,
                labels={
                    "giclab.t09.plan": contract.plan_id,
                    "giclab.t09.host_run": contract.host_run_id,
                    "giclab.t09.role": role,
                },
            )
            try:
                register_owned_container_cleanup(
                    cleanup_journal,
                    candidate,
                    role=role,
                )
            except EarlyCleanupStateError as exc:
                raise T09HostError("durable utility-container registration failed") from exc
            owned_identity = candidate

    try:
        process = subprocess.Popen(
            projected,
            env=environment or safe_environment(),
            stdin=subprocess.DEVNULL,
            stdout=stdout,
            stderr=stderr,
            preexec_fn=preexec_fn,
        )
        deadline = time.monotonic() + timeout
        captured_stdout: bytes | None = None
        captured_stderr: bytes | None = None
        while True:
            register_published_identity()
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                process.kill()
                captured_stdout, captured_stderr = process.communicate()
                raise subprocess.TimeoutExpired(
                    projected,
                    timeout,
                    output=captured_stdout,
                    stderr=captured_stderr,
                )
            try:
                captured_stdout, captured_stderr = process.communicate(timeout=min(0.05, remaining))
                break
            except subprocess.TimeoutExpired:
                continue
        register_published_identity()
        result = cast(
            subprocess.CompletedProcess[bytes],
            subprocess.CompletedProcess(
                projected,
                process.returncode,
                captured_stdout,
                captured_stderr,
            ),
        )
    except BaseException as exc:
        primary_error = exc
    finally:
        removal_returned_success = False
        removal_error_type: str | None = None
        registration_error_type: str | None = None
        residue: list[str] = []
        initially_absent = False
        try:
            if process is not None and process.poll() is None:
                process.kill()
                process.communicate()
        except (OSError, subprocess.SubprocessError) as exc:
            removal_error_type = type(exc).__name__
        try:
            register_published_identity()
        except (OSError, T09HostError) as exc:
            registration_error_type = type(exc).__name__
            if primary_error is None:
                primary_error = T09HostError("durable utility-container registration failed")
        try:
            if container_id is not None:
                retained = inspect_owned_container(
                    prefix,
                    name,
                    expected_container_id=container_id,
                    expected_role=role,
                )
                initially_absent = retained is None
                removal_returned_success = initially_absent or remove_container(
                    prefix,
                    name,
                    expected_container_id=container_id,
                    expected_role=role,
                )
            else:
                # No daemon-published ID means there is no authority to remove by
                # name.  Only an exact absence proof is an acceptable outcome.
                removal_returned_success = _container_id_by_exact_name(prefix, name) is None
            residue = [] if removal_returned_success else [name]
            if owned_identity is not None:
                cleanup_result, cleanup_detail = verified_owned_container_cleanup_result(
                    initially_absent=initially_absent,
                    removal_verified=removal_returned_success,
                    removed_detail="utility-container-removed",
                    absent_detail="utility-container-already-absent",
                )
                record_owned_container_cleanup_result(
                    cleanup_journal,
                    owned_identity,
                    result=cleanup_result,
                    detail_code=cleanup_detail,
                )
        except (OSError, subprocess.SubprocessError, T09HostError, EarlyCleanupStateError) as exc:
            removal_error_type = type(exc).__name__
            residue = [name]
        write_exclusive(
            evidence_root / f"{label}.container-cleanup.json",
            {
                "schema_version": "0.1.0",
                "container_name": name,
                "container_id": container_id,
                "owned_role": role,
                "remove_returned_success": removal_returned_success,
                "container_absent_after_run": not residue,
                "residue": residue,
                "cleanup_error_type": removal_error_type,
                "cleanup_authority_registered": owned_identity is not None,
                "cleanup_authority_error_type": registration_error_type,
            },
        )
        if residue:
            cleanup_error = T09HostError("owned Docker execution residue remains after cleanup")
            if primary_error is not None:
                raise cleanup_error from primary_error
            raise cleanup_error
    if primary_error is not None:
        raise primary_error
    assert result is not None
    return result


def _read_owned_docker_cidfile(cidfile: Path, *, prefix: list[str]) -> str | None:
    """Read one daemon-published exact ID without following mutable aliases."""

    nofollow = getattr(os, "O_NOFOLLOW", None)
    nonblock = getattr(os, "O_NONBLOCK", None)
    if nofollow is None or nonblock is None:
        raise T09HostError("owned Docker container-ID no-follow nonblocking open is unavailable")
    flags = os.O_RDONLY | nofollow | nonblock | getattr(os, "O_CLOEXEC", 0)
    try:
        descriptor = os.open(cidfile, flags)
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise T09HostError("owned Docker container-ID file is unsafe") from exc
    try:
        metadata = os.fstat(descriptor)
        if (
            not stat.S_ISREG(metadata.st_mode)
            or metadata.st_uid != _docker_cidfile_owner_uid(prefix)
            or metadata.st_nlink != 1
            or stat.S_IMODE(metadata.st_mode) & 0o022
        ):
            raise T09HostError("owned Docker container-ID file is unsafe")
        if metadata.st_size == 0:
            return None
        if metadata.st_size not in (64, 65):
            raise T09HostError("owned Docker container-ID file is malformed")
        payload = bytearray()
        while len(payload) <= 65:
            chunk = os.read(descriptor, 66 - len(payload))
            if not chunk:
                break
            payload.extend(chunk)
        encoded = bytes(payload)
    except OSError as exc:
        raise T09HostError("owned Docker container-ID file is unsafe") from exc
    finally:
        os.close(descriptor)
    if encoded.endswith(b"\n"):
        encoded = encoded[:-1]
    if re.fullmatch(rb"[a-f0-9]{64}", encoded) is None:
        raise T09HostError("owned Docker container-ID file is malformed")
    return encoded.decode("ascii")


def docker_prefix() -> list[str]:
    for candidate in (["docker"], ["sudo", "-n", "docker"]):
        result = subprocess.run(
            [*candidate, "info"],
            env=safe_environment(),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
            timeout=30,
        )
        if result.returncode == 0:
            return list(candidate)
    raise T09HostError("Docker is unavailable")


def image_id_if_present(prefix: list[str], reference: str) -> str | None:
    result = subprocess.run(
        [*prefix, "image", "inspect", "--format", "{{.Id}}", reference],
        env=safe_environment(),
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        check=False,
        timeout=30,
    )
    if result.returncode != 0:
        return None
    observed = result.stdout.decode("utf-8", errors="strict").strip()
    if re.fullmatch(r"sha256:[a-f0-9]{64}", observed) is None:
        raise T09HostError("Docker returned a malformed image identity")
    return observed


def _image_config_labels(prefix: list[str], reference: str) -> dict[str, str]:
    raw = output([*prefix, "image", "inspect", "--format", "{{json .Config.Labels}}", reference])
    try:
        value: object = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise T09HostError("Docker returned malformed image labels") from exc
    if not isinstance(value, dict) or not all(
        isinstance(key, str) and isinstance(item, str) for key, item in value.items()
    ):
        raise T09HostError("Docker returned an unsafe image-label projection")
    return cast(dict[str, str], value)


def _fallback_image_labels(package_commit: str, *, contract: T09ProviderContract) -> dict[str, str]:
    if re.fullmatch(r"[a-f0-9]{40}", package_commit) is None:
        raise T09HostError("fallback image package commit is malformed")
    return {
        "giclab.t09.plan": contract.plan_id,
        "giclab.t09.host_run": contract.host_run_id,
        "giclab.t09.role": "fallback-runtime-image",
        "giclab.t09.package_commit": package_commit,
    }


def held_descriptor_docker_path(prefix: list[str], descriptor: int) -> str:
    """Keep an already-validated archive descriptor visible across sudo Docker."""

    if descriptor < 0:
        raise T09HostError("held archive descriptor is invalid")
    if prefix == ["docker"]:
        return f"/proc/self/fd/{descriptor}"
    if prefix == ["sudo", "-n", "docker"]:
        # sudo closes inherited descriptors. Its root child can still open the
        # live parent Python process descriptor without re-resolving the private
        # operator-facing source path.
        return f"/proc/{os.getpid()}/fd/{descriptor}"
    raise T09HostError("Docker prefix cannot consume a held archive descriptor")


def _safe_extract_git_archive(archive: Path, destination: Path) -> None:
    destination.mkdir(mode=0o700)
    with tarfile.open(archive, "r:") as handle:
        members = handle.getmembers()
        for member in members:
            pure = PurePosixPath(member.name)
            if (
                pure.is_absolute()
                or not pure.parts
                or any(part in {"", ".", ".."} for part in pure.parts)
                or not (member.isfile() or member.isdir())
            ):
                raise T09HostError("historical source archive contains an unsafe member")
        handle.extractall(destination, members=members)


def _build_context_manifest(
    context: Path,
    *,
    contract: T09ProviderContract,
) -> dict[str, object]:
    files: list[dict[str, object]] = []
    total = 0
    for path in sorted(context.rglob("*")):
        relative = path.relative_to(context)
        lowered_parts = {part.lower() for part in relative.parts}
        if ".git" in lowered_parts or any(
            token in path.name.lower()
            for token in (".env", "credential", "api_key", "jupyter", ".token", "secret")
        ):
            raise T09HostError("replacement build context contains forbidden metadata")
        if path.is_symlink():
            raise T09HostError("replacement build context contains a symlink")
        metadata = path.stat(follow_symlinks=False)
        if path.is_dir():
            continue
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
            raise T09HostError("replacement build context contains a special or linked file")
        size = metadata.st_size
        total += size
        files.append(
            {
                "path": relative.as_posix(),
                "bytes": size,
                "mode": f"{stat.S_IMODE(metadata.st_mode):04o}",
                "mtime_epoch": int(metadata.st_mtime),
                "sha256": file_sha256(path),
            }
        )
    if not files or total > MAX_PILOT_DISK_BYTES:
        raise T09HostError("replacement build context is empty or exceeds the disk cap")
    return {
        "schema_version": "0.2.0",
        "qualification_id": contract.active_image_qualification_id,
        "source_date_epoch": SOURCE_DATE_EPOCH,
        "files": files,
        "file_count": len(files),
        "total_bytes": total,
        "manifest_payload_sha256": canonical_sha256(files),
    }


def _exclude_pinned_nonruntime_env_example(
    upstream: Path,
    *,
    materialization: Path,
    contract: T09ProviderContract,
) -> dict[str, object]:
    """Remove only the exact pinned names-only example before fail-closed scanning."""

    path = upstream / ".env.example"
    metadata = path.stat(follow_symlinks=False)
    content = path.read_bytes()
    if (
        path.is_symlink()
        or not stat.S_ISREG(metadata.st_mode)
        or metadata.st_nlink != 1
        or metadata.st_size != PINNED_ENV_EXAMPLE_BYTES
        or content != PINNED_ENV_EXAMPLE_CONTENT
        or hashlib.sha256(content).hexdigest() != PINNED_ENV_EXAMPLE_SHA256
    ):
        raise T09HostError("pinned SiRA environment example identity or content drifted")
    receipt: dict[str, object] = {
        "schema_version": "0.1.0",
        "qualification_id": contract.active_image_qualification_id,
        "source_commit": SIRA_COMMIT,
        "source_tree": SIRA_TREE,
        "path": ".env.example",
        "bytes": metadata.st_size,
        "sha256": PINNED_ENV_EXAMPLE_SHA256,
        "classification": "pinned-names-only-nonruntime-example-excluded",
        "contained_credential_value": False,
        "runtime_input": False,
        "scientific_input": False,
        "build_context_inclusion": False,
    }
    receipt_path = materialization / "build-context-exclusions.json"
    write_exclusive(receipt_path, receipt)
    path.unlink()
    directory_fd = os.open(upstream, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
    if path.exists():
        raise T09HostError("excluded environment example still exists")
    return receipt


def _capture_optional_command(
    argv: list[str],
    *,
    evidence_root: Path,
    label: str,
) -> dict[str, object]:
    result = subprocess.run(
        argv,
        env=safe_environment(),
        stdin=subprocess.DEVNULL,
        capture_output=True,
        check=False,
        timeout=60,
    )
    receipt = {
        "argv": argv,
        "returncode": result.returncode,
        "stdout": result.stdout.decode("utf-8", errors="replace").strip(),
        "stderr": result.stderr.decode("utf-8", errors="replace").strip(),
    }
    write_exclusive(evidence_root / f"{label}.json", receipt)
    return receipt


def _copy_retained_prefix(source: Path, destination: Path, *, label: str) -> dict[str, object]:
    before = _retained_tree_manifest(source, label=label)
    shutil.copytree(source, destination, copy_function=shutil.copy2)
    after = _retained_tree_manifest(destination, label=f"copied {label}")
    if before != after:
        raise T09HostError(f"{label} changed during evidence retention")
    return before


def _slot2_authority_relative_paths(root: Path) -> tuple[str, ...]:
    """Return the exact manifest-bound slot-2 authority surface and reject extras."""

    root = root.resolve(strict=True)
    eligibility = root / "replacement-launch-eligibility.json"
    source_root = root / "slot2-eligibility-source"
    source_manifest_path = source_root / "source-manifest.json"
    source_manifest = load_object(source_manifest_path, label="slot-2 authority manifest")
    contract = _provider_contract_from_document(source_manifest, label="slot-2 authority manifest")
    raw_files = source_manifest.get("files")
    if (
        source_manifest.get("schema_version") != "0.1.0"
        or source_manifest.get("plan_id") != contract.plan_id
        or source_manifest.get("host_run_id") != contract.host_run_id
        or not isinstance(raw_files, list)
        or source_manifest.get("file_count") != len(raw_files)
        or source_manifest.get("files_sha256")
        != hashlib.sha256(
            (
                json.dumps(
                    raw_files,
                    allow_nan=False,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                )
                + "\n"
            ).encode()
        ).hexdigest()
    ):
        raise T09HostError("slot-2 authority manifest contract drifted")
    declared: list[str] = []
    total = 0
    for raw in raw_files:
        if not isinstance(raw, dict):
            raise T09HostError("slot-2 authority file record is malformed")
        relative_raw = raw.get("path")
        size = raw.get("bytes")
        digest = raw.get("sha256")
        if not isinstance(relative_raw, str):
            raise T09HostError("slot-2 authority file path is malformed")
        relative = PurePosixPath(relative_raw)
        if relative.is_absolute() or not relative.parts or ".." in relative.parts:
            raise T09HostError("slot-2 authority file escaped its source root")
        path = source_root.joinpath(*relative.parts)
        metadata = path.stat(follow_symlinks=False)
        if (
            path.is_symlink()
            or not stat.S_ISREG(metadata.st_mode)
            or metadata.st_uid != os.getuid()
            or metadata.st_nlink != 1
            or stat.S_IMODE(metadata.st_mode) != 0o600
            or type(size) is not int
            or metadata.st_size != size
            or not isinstance(digest, str)
            or re.fullmatch(r"[a-f0-9]{64}", digest) is None
            or file_sha256(path) != digest
        ):
            raise T09HostError("slot-2 authority file identity drifted")
        declared.append(relative.as_posix())
        total += metadata.st_size
    observed: set[str] = set()
    for path in source_root.rglob("*"):
        metadata = path.lstat()
        if stat.S_ISDIR(metadata.st_mode):
            continue
        if not stat.S_ISREG(metadata.st_mode) or path.is_symlink():
            raise T09HostError("slot-2 authority source contains an unsafe extra member")
        observed.add(path.relative_to(source_root).as_posix())
    expected = {*declared, "source-manifest.json"}
    if (
        len(declared) != len(set(declared))
        or observed != expected
        or source_manifest.get("total_bytes") != total
    ):
        raise T09HostError("slot-2 authority source member set drifted")
    for path in (eligibility, source_manifest_path):
        metadata = path.stat(follow_symlinks=False)
        if (
            path.is_symlink()
            or not stat.S_ISREG(metadata.st_mode)
            or metadata.st_uid != os.getuid()
            or metadata.st_nlink != 1
            or stat.S_IMODE(metadata.st_mode) != 0o600
        ):
            raise T09HostError("slot-2 authority control file is unsafe")
    return (
        "replacement-launch-eligibility.json",
        "slot2-eligibility-source/source-manifest.json",
        *(f"slot2-eligibility-source/{relative}" for relative in sorted(declared)),
    )


def retain_slot2_authority(source: Path, destination: Path) -> tuple[str, ...]:
    """Project only the source-manifest-bound authority into the pilot root."""

    source = source.resolve(strict=True)
    relative_paths = _slot2_authority_relative_paths(source)
    destination.mkdir(mode=0o700, parents=True, exist_ok=False)
    for relative in relative_paths:
        incoming = source / relative
        outgoing = destination / relative
        outgoing.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        with incoming.open("rb") as source_handle, outgoing.open("xb") as target_handle:
            shutil.copyfileobj(source_handle, target_handle, 1_048_576)
            target_handle.flush()
            os.fsync(target_handle.fileno())
        outgoing.chmod(0o600)
    if _slot2_authority_relative_paths(destination) != relative_paths:
        raise T09HostError("slot-2 authority changed during minimal retention")
    return relative_paths


def slot2_authority_binding(root: Path) -> dict[str, object]:
    """Return distinct bindings for the transfer tree and scientific authority.

    The normalized transfer-tree manifest proves what crossed the provider/host
    boundary.  The nested pre-empirical source manifest is the authority named by
    the replacement-eligibility receipt.  They are deliberately separate types:
    equality between them is neither expected nor meaningful.
    """

    relative_paths = _slot2_authority_relative_paths(root)
    records = [
        {
            "path": relative,
            "bytes": (root / relative).stat().st_size,
            "sha256": file_sha256(root / relative),
        }
        for relative in relative_paths
    ]
    return {
        "relative_paths": list(relative_paths),
        "relative_paths_sha256": canonical_sha256(list(relative_paths)),
        "files": records,
        "files_sha256": canonical_sha256(records),
        "replacement_eligibility_sha256": file_sha256(root / "replacement-launch-eligibility.json"),
        "replacement_eligibility_preempirical_source_manifest_sha256": file_sha256(
            root / "slot2-eligibility-source/slot1-preempirical-source/source-manifest.json"
        ),
        "normalized_slot2_authority_tree_manifest_sha256": file_sha256(
            root / "slot2-eligibility-source/source-manifest.json"
        ),
    }


def retain_prior_qualification_failures(
    *,
    artifact_root: Path,
    prior_artifact_root: Path,
    failed_candidate_root: Path,
    previous_transition_receipt: Path,
    package_transition_receipt: Path,
    contract: T09ProviderContract,
) -> dict[str, object]:
    destination = _pilot_root(artifact_root, contract) / "prior-qualification-failures"
    destination.mkdir(parents=True, mode=0o700)
    context_manifest = _copy_retained_prefix(
        prior_artifact_root,
        destination / "qualification-0002",
        label="context-rejection qualification prefix",
    )
    candidate_manifest = _copy_retained_prefix(
        failed_candidate_root,
        destination / "qualification-0003",
        label="offline-preflight candidate prefix",
    )
    transition_copies: dict[str, str] = {}
    for label, source in (
        ("transition-0003", previous_transition_receipt),
        ("transition-0004", package_transition_receipt),
    ):
        target = destination / f"{label}.json"
        shutil.copy2(source, target)
        metadata = target.stat(follow_symlinks=False)
        if (
            target.is_symlink()
            or not stat.S_ISREG(metadata.st_mode)
            or metadata.st_nlink != 1
            or stat.S_IMODE(metadata.st_mode) != 0o600
            or file_sha256(target) != file_sha256(source)
        ):
            raise T09HostError("package transition receipt copy drifted")
        transition_copies[label] = file_sha256(target)
    receipt: dict[str, object] = {
        "schema_version": "0.1.0",
        "plan_id": contract.plan_id,
        "host_run_id": contract.host_run_id,
        "accepted_qualification_id": contract.active_image_qualification_id,
        "context_failure_manifest": context_manifest,
        "failed_candidate_manifest": candidate_manifest,
        "package_transition_receipts": transition_copies,
        "empirical_entry_crossed": False,
        "model_metadata_requests_before_acceptance": 0,
        "task_model_requests": 0,
        "task_browser_actions": 0,
        "additional_provider_launches": 0,
    }
    write_exclusive(destination / "retention-receipt.json", receipt)
    return receipt


def carry_forward_replacement_image(
    *,
    artifact_root: Path,
    failed_candidate_root: Path,
    prefix: list[str],
    contract: T09ProviderContract,
) -> dict[str, object]:
    failed = _failed_candidate_manifest(
        failed_candidate_root,
        require_image_present=True,
    )
    image_id = failed.get("replacement_image_id")
    if not isinstance(image_id, str) or image_id_if_present(prefix, image_id) != image_id:
        raise T09HostError("failed candidate image cannot be carried forward")
    source = failed_candidate_root / "pilot-v7/replacement-image-qualification"
    destination = _pilot_root(artifact_root, contract) / "replacement-image-qualification"
    _copy_retained_prefix(source, destination, label="failed candidate materialization")
    prior_receipt_path = destination / "receipt.json"
    prior_receipt = load_object(prior_receipt_path, label="carried candidate receipt")
    if (
        file_sha256(prior_receipt_path) != failed.get("materialization_receipt_sha256")
        or prior_receipt.get("image_id") != image_id
        or prior_receipt.get("build_count") != 1
    ):
        raise T09HostError("carried candidate materialization receipt drifted")
    prior_receipt_path.unlink()
    result: dict[str, object] = {
        **prior_receipt,
        "qualification_id": contract.active_image_qualification_id,
        "method": "single-built-candidate-carried-forward-after-host-control-repair",
        "candidate_qualification_id": FAILED_CANDIDATE_QUALIFICATION_ID,
        "accepted_qualification_id": contract.active_image_qualification_id,
        "candidate_materialization_receipt_sha256": failed["materialization_receipt_sha256"],
        "candidate_failure_manifest_sha256": canonical_sha256(failed),
        "build_count": 1,
        "additional_build_count": 0,
        "image_reused_by_exact_id": True,
        "empirical_entry_before_carry_forward": False,
    }
    write_exclusive(prior_receipt_path, result)
    return result


def materialize_replacement_image(
    *,
    repository: Path,
    package_commit: str,
    artifact_root: Path,
    prefix: list[str],
    contract: T09ProviderContract,
) -> dict[str, object]:
    replacement_image_tag = cast(str, contract.replacement_image_tag)
    if image_id_if_present(prefix, replacement_image_tag) is not None:
        raise T09HostError("replacement image tag already exists; exactly one build is allowed")

    materialization = _pilot_root(artifact_root, contract) / "replacement-image-qualification"
    logs = materialization / "logs"
    work = materialization / "work"
    snapshot = work / "snapshot"
    context = work / "build-context"
    work.mkdir(parents=True, mode=0o700)
    context.mkdir(mode=0o700)
    archive = work / "t07-source.tar"
    historical_paths = [
        "containers/sira-smoke/pragmatic/Containerfile.amd64",
        "containers/sira-smoke/sira-immutable-model-routing.patch",
        "containers/sira-smoke/container_entrypoint.py",
        "containers/sira-smoke/bounded/model_preflight.py",
        "containers/sira-smoke/bounded/browser_preflight.py",
        "containers/sira-smoke/pragmatic/runtime_preflight.py",
        "containers/sira-smoke/fixtures/static.html",
        "src/giclab",
    ]
    run_logged(
        [
            "git",
            "-C",
            str(repository),
            "archive",
            "--format=tar",
            f"--output={archive}",
            T07_EXECUTION_COMMIT,
            *historical_paths,
        ],
        evidence_root=logs,
        label="historical-source-archive",
        timeout=120,
        contract=contract,
    )
    _safe_extract_git_archive(archive, snapshot)
    copies = {
        "containers/sira-smoke/pragmatic/Containerfile.amd64": "Containerfile",
        "containers/sira-smoke/sira-immutable-model-routing.patch": (
            "sira-immutable-model-routing.patch"
        ),
        "containers/sira-smoke/container_entrypoint.py": "container_entrypoint.py",
        "containers/sira-smoke/bounded/model_preflight.py": "model_preflight.py",
        "containers/sira-smoke/bounded/browser_preflight.py": "browser_preflight.py",
        "containers/sira-smoke/pragmatic/runtime_preflight.py": "runtime_preflight.py",
        "containers/sira-smoke/fixtures/static.html": "static.html",
    }
    for source, destination in copies.items():
        shutil.copy2(snapshot / source, context / destination)
    shutil.copytree(snapshot / "src/giclab", context / "giclab")
    vendor = context / "vendor"
    vendor.mkdir(mode=0o700)
    upstream = context / "upstream"
    run_logged(
        ["git", "init", str(upstream)],
        evidence_root=logs,
        label="sira-init",
        timeout=30,
        contract=contract,
    )
    run_logged(
        [
            "git",
            "-C",
            str(upstream),
            "remote",
            "add",
            "origin",
            "https://github.com/sailing-lab/sira.git",
        ],
        evidence_root=logs,
        label="sira-remote",
        timeout=30,
        contract=contract,
    )
    run_logged(
        ["git", "-C", str(upstream), "fetch", "--depth", "1", "origin", SIRA_COMMIT],
        evidence_root=logs,
        label="sira-fetch",
        timeout=300,
        contract=contract,
    )
    run_logged(
        ["git", "-C", str(upstream), "checkout", "--detach", "FETCH_HEAD"],
        evidence_root=logs,
        label="sira-checkout",
        timeout=60,
        contract=contract,
    )
    if output(["git", "-C", str(upstream), "rev-parse", "HEAD"]) != SIRA_COMMIT:
        raise T09HostError("pinned SiRA commit did not materialize")
    if output(["git", "-C", str(upstream), "rev-parse", "HEAD^{tree}"]) != SIRA_TREE:
        raise T09HostError("pinned SiRA tree did not materialize")
    # Git object/ref/log metadata is not a scientific runtime input and contains
    # fetch-time state.  Retain the verified commit/tree identities in the receipt,
    # then exclude that nondeterministic metadata from the complete build context.
    shutil.rmtree(upstream / ".git")
    exclusion = _exclude_pinned_nonruntime_env_example(
        upstream,
        materialization=materialization,
        contract=contract,
    )
    wheel = vendor / "uv-0.11.7-py3-none-manylinux_2_17_x86_64.manylinux2014_x86_64.whl"
    run_logged(
        [
            "curl",
            "--fail",
            "--location",
            "--silent",
            "--show-error",
            "--retry",
            "0",
            "--max-time",
            "300",
            "--output",
            str(wheel),
            UV_URL,
        ],
        evidence_root=logs,
        label="uv-download",
        timeout=330,
        contract=contract,
    )
    exact_files = {
        wheel: UV_SHA256,
        context / "sira-immutable-model-routing.patch": T07_ROUTING_PATCH_SHA256,
        context / "giclab/harness/sira_gate_a_runtime.py": T07_RUNTIME_SHA256,
        context / "runtime_preflight.py": T07_RUNTIME_PREFLIGHT_SHA256,
    }
    for path, expected in exact_files.items():
        if file_sha256(path) != expected:
            raise T09HostError(f"historical build input hash drifted: {path.name}")
    # Normalize the build-context clock after every source identity has been verified.
    # This reduces creation-time drift without treating bit reproduction as acceptance.
    for path in sorted(context.rglob("*"), reverse=True):
        os.utime(path, (SOURCE_DATE_EPOCH, SOURCE_DATE_EPOCH), follow_symlinks=False)
    os.utime(context, (SOURCE_DATE_EPOCH, SOURCE_DATE_EPOCH), follow_symlinks=False)
    context_manifest = _build_context_manifest(context, contract=contract)
    context_manifest_path = materialization / "build-context-manifest.json"
    write_exclusive(context_manifest_path, context_manifest)
    docker_version = _capture_optional_command(
        [*prefix, "version", "--format", "{{json .}}"],
        evidence_root=materialization,
        label="docker-version",
    )
    buildkit_version = _capture_optional_command(
        [*prefix, "buildx", "version"],
        evidence_root=materialization,
        label="buildkit-version",
    )
    repository_runtime_commit = output(["git", "-C", str(repository), "rev-parse", "HEAD"])
    if repository_runtime_commit != package_commit:
        raise T09HostError("fallback image build package commit drifted")
    owned_image_labels = _fallback_image_labels(package_commit, contract=contract)
    build_argv = [
        *prefix,
        "build",
        "--pull=false",
        "--progress=plain",
        "--build-arg",
        f"RUNTIME_PREFLIGHT_SHA256={T07_RUNTIME_PREFLIGHT_SHA256}",
        "--build-arg",
        "PYTHON_RUNTIME_VERSION=3.11.14",
        "--build-arg",
        f"SOURCE_DATE_EPOCH={SOURCE_DATE_EPOCH}",
        *(
            item
            for key, value in sorted(owned_image_labels.items())
            for item in ("--label", f"{key}={value}")
        ),
        "--tag",
        replacement_image_tag,
        "--file",
        str(context / "Containerfile"),
        str(context),
    ]
    write_exclusive(
        materialization / "build-command.json",
        {
            "argv": build_argv,
            "argv_sha256": canonical_sha256(build_argv),
            "source_date_epoch": SOURCE_DATE_EPOCH,
            "network_fetches": {
                "sira_commit": SIRA_COMMIT,
                "uv_wheel_url": UV_URL,
                "uv_wheel_sha256": UV_SHA256,
            },
        },
    )
    write_exclusive(
        materialization / "fallback-build-intent.json",
        {
            "schema_version": "0.1.0",
            "plan_id": contract.plan_id,
            "host_run_id": contract.host_run_id,
            "qualification_id": contract.active_image_qualification_id,
            "package_commit": package_commit,
            "image_tag": replacement_image_tag,
            "materialization_policy": SLOT1_IMAGE_MATERIALIZATION_POLICY,
            "expected_tag_present_before_build": False,
            "authorized_build_count": 1,
            "resulting_image_id_known_before_build": False,
            "owned_image_labels": owned_image_labels,
            "build_argv_sha256": canonical_sha256(build_argv),
            "build_command_sha256": file_sha256(materialization / "build-command.json"),
        },
    )
    run_logged(
        build_argv,
        evidence_root=logs,
        label="docker-build",
        timeout=3_600,
        contract=contract,
    )
    built = image_id_if_present(prefix, replacement_image_tag)
    if built is None:
        raise T09HostError("replacement build did not create its exact image")
    run_logged(
        [*prefix, "image", "inspect", built],
        evidence_root=materialization,
        label="replacement-image-inspect",
        timeout=60,
        contract=contract,
    )
    result: dict[str, object] = {
        "schema_version": "0.1.0",
        "qualification_id": contract.active_image_qualification_id,
        "method": "single-replacement-build-from-pinned-reviewed-inputs",
        "image_id": built,
        "historical_image_id": HISTORICAL_IMAGE_ID,
        "image_digest_equality_required": False,
        "base_image_identity": BASE_IMAGE_IDENTITY,
        "historical_source_commit": T07_EXECUTION_COMMIT,
        "repository_runtime_commit": repository_runtime_commit,
        "sira_commit": SIRA_COMMIT,
        "sira_tree": SIRA_TREE,
        "python_version": "3.11.14",
        "containerfile_sha256": file_sha256(context / "Containerfile"),
        "build_context_manifest_sha256": file_sha256(context_manifest_path),
        "build_context_payload_sha256": context_manifest["manifest_payload_sha256"],
        "build_context_exclusions_sha256": file_sha256(
            materialization / "build-context-exclusions.json"
        ),
        "build_context_exclusion_classification": exclusion["classification"],
        "build_command_sha256": file_sha256(materialization / "build-command.json"),
        "image_inspect_sha256": file_sha256(materialization / "replacement-image-inspect.stdout"),
        "runtime_sha256": T07_RUNTIME_SHA256,
        "runtime_preflight_sha256": T07_RUNTIME_PREFLIGHT_SHA256,
        "routing_patch_sha256": T07_ROUTING_PATCH_SHA256,
        "uv_wheel_sha256": UV_SHA256,
        "sira_uv_lock_sha256": file_sha256(context / "upstream/uv.lock"),
        "entrypoint_sha256": file_sha256(context / "container_entrypoint.py"),
        "model_preflight_sha256": file_sha256(context / "model_preflight.py"),
        "browser_preflight_sha256": file_sha256(context / "browser_preflight.py"),
        "evaluator_code_sha256": file_sha256(context / "upstream/evaluation/fanout/evaluator.py"),
        "evaluator_run_sha256": file_sha256(context / "upstream/evaluation/fanout/run.py"),
        "workdir": "/opt/sira",
        "entrypoint_contract": "/opt/giclab/container_entrypoint.py",
        "runtime_environment_contract": "reviewed-Containerfile-exact-environment-v1",
        "source_date_epoch": SOURCE_DATE_EPOCH,
        "docker_version_receipt_sha256": file_sha256(materialization / "docker-version.json"),
        "docker_version_available": docker_version["returncode"] == 0,
        "buildkit_version_receipt_sha256": file_sha256(materialization / "buildkit-version.json"),
        "buildkit_version_available": buildkit_version["returncode"] == 0,
        "build_count": 1,
    }
    shutil.rmtree(work)
    return result


def materialize_retained_or_build_image(
    *,
    repository: Path,
    package_commit: str,
    artifact_root: Path,
    image_archive: Path,
    prefix: list[str],
    materialization_policy: str,
    contract: T09ProviderContract,
) -> dict[str, object]:
    """Materialize under the source-bound launch-slot policy."""

    if materialization_policy not in {
        SLOT1_IMAGE_MATERIALIZATION_POLICY,
        SLOT2_IMAGE_MATERIALIZATION_POLICY,
    }:
        raise T09HostError("image materialization policy is invalid")

    replacement_image_tag = cast(str, contract.replacement_image_tag)
    if (
        image_id_if_present(prefix, replacement_image_tag) is not None
        or image_id_if_present(prefix, RETAINED_IMAGE_ID) is not None
    ):
        raise T09HostError("V7 image identity already exists before materialization")
    materialization = _pilot_root(artifact_root, contract) / "replacement-image-qualification"
    logs = materialization / "logs"
    materialization.mkdir(parents=True, mode=0o700)
    archive_valid = False
    archive_reason = "unavailable"
    archive_descriptor = -1
    archive_parent_descriptor = -1
    archive_identity: tuple[int, int, int, int, int, int] | None = None
    try:
        archive_parent_descriptor, archive_name = _open_parent_directory_no_follow(image_archive)
        archive_descriptor = os.open(
            archive_name,
            os.O_RDONLY
            | getattr(os, "O_NONBLOCK", 0)
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_CLOEXEC", 0),
            dir_fd=archive_parent_descriptor,
        )
        metadata = os.fstat(archive_descriptor)
        archive_identity = (
            metadata.st_dev,
            metadata.st_ino,
            metadata.st_size,
            metadata.st_mtime_ns,
            metadata.st_ctime_ns,
            metadata.st_mode,
        )
        archive_valid = (
            stat.S_ISREG(metadata.st_mode)
            and metadata.st_uid == os.getuid()
            and metadata.st_nlink == 1
            and stat.S_IMODE(metadata.st_mode) == 0o600
            and metadata.st_size == RETAINED_IMAGE_ARCHIVE_BYTES
            and _sha256_descriptor(archive_descriptor) == RETAINED_IMAGE_ARCHIVE_SHA256
        )
        archive_reason = "verified" if archive_valid else "identity-mismatch"
    except (FileNotFoundError, OSError, T09HostError):
        archive_reason = "unavailable-or-unsafe"
    if not archive_valid:
        if archive_descriptor >= 0:
            os.close(archive_descriptor)
            archive_descriptor = -1
        if archive_parent_descriptor >= 0:
            os.close(archive_parent_descriptor)
            archive_parent_descriptor = -1
    try:
        write_exclusive(
            materialization / "retained-image-input.json",
            {
                "schema_version": "0.1.0",
                "archive_role": "retry3-qualified-candidate-image",
                "archive_path_retained": False,
                "expected_bytes": RETAINED_IMAGE_ARCHIVE_BYTES,
                "expected_sha256": RETAINED_IMAGE_ARCHIVE_SHA256,
                "expected_image_id": RETAINED_IMAGE_ID,
                "expected_image_id_present_before_materialization": False,
                "validation": archive_reason,
                "materialization_policy": materialization_policy,
            },
        )
    except BaseException:
        if archive_descriptor >= 0:
            os.close(archive_descriptor)
        if archive_parent_descriptor >= 0:
            os.close(archive_parent_descriptor)
        raise
    if archive_valid:
        assert archive_descriptor >= 0
        assert archive_identity is not None
        try:
            try:
                load = subprocess.run(
                    [
                        *prefix,
                        "load",
                        "--input",
                        held_descriptor_docker_path(prefix, archive_descriptor),
                    ],
                    env=safe_environment(),
                    stdin=subprocess.DEVNULL,
                    capture_output=True,
                    check=False,
                    pass_fds=(archive_descriptor,),
                    timeout=min(
                        MAX_IMAGE_EXPORT_SECONDS,
                        max(1.0, preflight_seconds_remaining(artifact_root)),
                    ),
                )
            except subprocess.TimeoutExpired as exc:
                load = subprocess.CompletedProcess(
                    args=exc.cmd,
                    returncode=124,
                    stdout=exc.stdout or b"",
                    stderr=exc.stderr or b"docker load timed out",
                )
            archive_after = os.fstat(archive_descriptor)
            archive_unchanged = (
                archive_identity
                == (
                    archive_after.st_dev,
                    archive_after.st_ino,
                    archive_after.st_size,
                    archive_after.st_mtime_ns,
                    archive_after.st_ctime_ns,
                    archive_after.st_mode,
                )
                and _sha256_descriptor(archive_descriptor) == RETAINED_IMAGE_ARCHIVE_SHA256
            )
        finally:
            os.close(archive_descriptor)
            archive_descriptor = -1
            os.close(archive_parent_descriptor)
            archive_parent_descriptor = -1
        write_bytes_exclusive(logs / "docker-image-import.stdout", load.stdout)
        write_bytes_exclusive(logs / "docker-image-import.stderr", load.stderr)
        write_exclusive(
            logs / "docker-image-import.json",
            {"argv_role": "docker-load-exact-retained-archive", "returncode": load.returncode},
        )
        imported = image_id_if_present(prefix, RETAINED_IMAGE_ID)
        if load.returncode == 0 and archive_unchanged and imported == RETAINED_IMAGE_ID:
            run_logged(
                [*prefix, "tag", imported, replacement_image_tag],
                evidence_root=logs,
                label="docker-image-retag",
                timeout=60,
                contract=contract,
            )
            run_logged(
                [*prefix, "image", "inspect", imported],
                evidence_root=materialization,
                label="replacement-image-inspect",
                timeout=60,
                contract=contract,
            )
            context_receipt = {
                "schema_version": "0.1.0",
                "classification": "retained-image-import-no-new-build-context",
                "archive_sha256": RETAINED_IMAGE_ARCHIVE_SHA256,
                "archive_bytes": RETAINED_IMAGE_ARCHIVE_BYTES,
                "image_id": imported,
            }
            write_exclusive(materialization / "build-context-manifest.json", context_receipt)
            write_exclusive(
                materialization / "build-context-exclusions.json",
                {**context_receipt, "exclusions": "not-applicable-no-new-build"},
            )
            result: dict[str, object] = {
                "schema_version": "0.1.0",
                "qualification_id": contract.active_image_qualification_id,
                "method": "exact-retained-image-archive-import",
                "image_id": imported,
                "historical_image_id": HISTORICAL_IMAGE_ID,
                "repository_runtime_commit": package_commit,
                "build_context_manifest_sha256": file_sha256(
                    materialization / "build-context-manifest.json"
                ),
                "build_context_payload_sha256": canonical_sha256(context_receipt),
                "build_context_exclusions_sha256": file_sha256(
                    materialization / "build-context-exclusions.json"
                ),
                "containerfile_sha256": None,
                "build_command_sha256": None,
                "image_inspect_sha256": file_sha256(
                    materialization / "replacement-image-inspect.stdout"
                ),
                "retained_image_archive_sha256": RETAINED_IMAGE_ARCHIVE_SHA256,
                "retained_image_archive_bytes": RETAINED_IMAGE_ARCHIVE_BYTES,
                "build_count": 0,
                "additional_build_count": 0,
                "image_import_count": 1,
                "image_materialization_policy": materialization_policy,
            }
            write_exclusive(materialization / "receipt.json", result)
            return result
        # A failed/incompatible load may have made the expected image visible
        # even when Docker returned a failure.  The pre-mutation intent gives us
        # authority over that one exact ID; remove it and prove both the ID and
        # the V7 tag absent before fallback or slot-2 rejection.
        rejected_candidate_visible = image_id_if_present(prefix, RETAINED_IMAGE_ID)
        rejected_tag_visible = image_id_if_present(prefix, replacement_image_tag)
        if rejected_candidate_visible is not None:
            removal = subprocess.run(
                [*prefix, "image", "rm", "--force", RETAINED_IMAGE_ID],
                env=safe_environment(),
                stdin=subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                check=False,
                timeout=60,
            )
            if removal.returncode != 0:
                raise T09HostError("rejected retained-image load could not be removed")
        if rejected_tag_visible is not None and rejected_tag_visible != RETAINED_IMAGE_ID:
            raise T09HostError("failed retained-image load created an unexpected V7 tag")
        if (
            image_id_if_present(prefix, RETAINED_IMAGE_ID) is not None
            or image_id_if_present(prefix, replacement_image_tag) is not None
        ):
            raise T09HostError("rejected retained-image load left Docker image residue")
        if materialization_policy == SLOT2_IMAGE_MATERIALIZATION_POLICY:
            raise T09HostError("slot-2 retained image import failed; fallback build is forbidden")
    if archive_descriptor >= 0:
        os.close(archive_descriptor)
    if archive_parent_descriptor >= 0:
        os.close(archive_parent_descriptor)
    if materialization_policy == SLOT2_IMAGE_MATERIALIZATION_POLICY:
        raise T09HostError("slot-2 retained image is unavailable; fallback build is forbidden")
    built = materialize_replacement_image(
        repository=repository,
        package_commit=package_commit,
        artifact_root=artifact_root,
        prefix=prefix,
        contract=contract,
    )
    built["image_import_count"] = 0
    built["additional_build_count"] = 0
    built["retained_image_archive_validation"] = archive_reason
    built["image_materialization_policy"] = materialization_policy
    receipt_path = (
        _pilot_root(artifact_root, contract) / "replacement-image-qualification/receipt.json"
    )
    write_exclusive(receipt_path, built)
    return built


def _validated_fallback_build_intent(
    materialization: Path,
    *,
    package_commit: str,
) -> dict[str, Any] | None:
    """Validate the pre-build mutation authority used by crash recovery."""

    intent_path = materialization / "fallback-build-intent.json"
    recovery_path = materialization / "fallback-build-cleanup-recovery.json"
    if not intent_path.exists():
        if os.path.lexists(intent_path) or os.path.lexists(recovery_path):
            raise T09HostError("fallback image mutation authority is unsafe or orphaned")
        return None
    intent_metadata = intent_path.lstat()
    command_path = materialization / "build-command.json"
    if (
        intent_path.is_symlink()
        or not stat.S_ISREG(intent_metadata.st_mode)
        or intent_metadata.st_nlink != 1
        or not command_path.is_file()
        or command_path.is_symlink()
    ):
        raise T09HostError("fallback image mutation authority is unsafe")
    intent = load_object(intent_path, label="fallback image build intent")
    command = load_object(command_path, label="fallback image build command")
    argv = command.get("argv")
    contract = _provider_contract_from_document(intent, label="fallback image build intent")
    labels = _fallback_image_labels(package_commit, contract=contract)
    qualification_id = contract.active_image_qualification_id
    image_tag = contract.replacement_image_tag
    materialization_policy = contract.image_materialization_policy
    if (
        set(intent)
        != {
            "schema_version",
            "plan_id",
            "host_run_id",
            "qualification_id",
            "package_commit",
            "image_tag",
            "materialization_policy",
            "expected_tag_present_before_build",
            "authorized_build_count",
            "resulting_image_id_known_before_build",
            "owned_image_labels",
            "build_argv_sha256",
            "build_command_sha256",
        }
        or intent.get("schema_version") != "0.1.0"
        or intent.get("plan_id") != contract.plan_id
        or intent.get("host_run_id") != contract.host_run_id
        or qualification_id is None
        or intent.get("qualification_id") != qualification_id
        or intent.get("package_commit") != package_commit
        or image_tag is None
        or intent.get("image_tag") != image_tag
        or materialization_policy is None
        or intent.get("materialization_policy") != materialization_policy
        or intent.get("expected_tag_present_before_build") is not False
        or intent.get("authorized_build_count") != 1
        or intent.get("resulting_image_id_known_before_build") is not False
        or intent.get("owned_image_labels") != labels
        or not isinstance(argv, list)
        or not all(isinstance(item, str) for item in argv)
        or command.get("argv_sha256") != canonical_sha256(argv)
        or intent.get("build_argv_sha256") != canonical_sha256(argv)
        or intent.get("build_command_sha256") != file_sha256(command_path)
        or command.get("source_date_epoch") != SOURCE_DATE_EPOCH
        or command.get("network_fetches")
        != {
            "sira_commit": SIRA_COMMIT,
            "uv_wheel_url": UV_URL,
            "uv_wheel_sha256": UV_SHA256,
        }
    ):
        raise T09HostError("fallback image build intent drifted")
    typed_argv = cast(list[str], argv)
    for key, value in labels.items():
        expected = f"{key}={value}"
        if not any(
            typed_argv[index : index + 2] == ["--label", expected]
            for index in range(len(typed_argv) - 1)
        ):
            raise T09HostError("fallback image build lost its ownership label")
    if not any(
        typed_argv[index : index + 2] == ["--tag", image_tag]
        for index in range(len(typed_argv) - 1)
    ):
        raise T09HostError("fallback image build lost its exact tag")
    return intent


def _fallback_build_cleanup_candidate(
    *,
    prefix: list[str],
    materialization: Path,
    package_commit: str,
    final_receipt_present: bool,
) -> str | None:
    """Resolve one label-bound fallback image after build/receipt interruption."""

    intent = _validated_fallback_build_intent(
        materialization,
        package_commit=package_commit,
    )
    recovery_path = materialization / "fallback-build-cleanup-recovery.json"
    if intent is None:
        return None
    if final_receipt_present:
        if os.path.lexists(recovery_path):
            raise T09HostError("fallback image has conflicting final and recovery receipts")
        return None
    contract = _provider_contract_from_document(intent, label="fallback image build intent")
    image_tag = contract.replacement_image_tag
    if image_tag is None:
        raise T09HostError("fallback image contract has no image tag")
    expected_labels = _fallback_image_labels(package_commit, contract=contract)
    intent_path = materialization / "fallback-build-intent.json"
    if recovery_path.is_file() and not recovery_path.is_symlink():
        recovery = load_object(recovery_path, label="fallback image cleanup recovery")
        candidate = recovery.get("image_id")
        if (
            set(recovery)
            != {
                "schema_version",
                "plan_id",
                "host_run_id",
                "package_commit",
                "image_tag",
                "image_id",
                "fallback_build_intent_sha256",
                "owned_image_labels",
                "final_materialization_receipt_absent",
            }
            or recovery.get("schema_version") != "0.1.0"
            or recovery.get("plan_id") != contract.plan_id
            or recovery.get("host_run_id") != contract.host_run_id
            or recovery.get("package_commit") != package_commit
            or recovery.get("image_tag") != image_tag
            or not isinstance(candidate, str)
            or re.fullmatch(r"sha256:[a-f0-9]{64}", candidate) is None
            or recovery.get("fallback_build_intent_sha256") != file_sha256(intent_path)
            or recovery.get("owned_image_labels") != expected_labels
            or recovery.get("final_materialization_receipt_absent") is not True
        ):
            raise T09HostError("fallback image cleanup recovery drifted")
        if image_id_if_present(prefix, candidate) is not None:
            observed_labels = _image_config_labels(prefix, candidate)
            if any(observed_labels.get(key) != value for key, value in expected_labels.items()):
                raise T09HostError("fallback image cleanup candidate labels drifted")
        return candidate
    if os.path.lexists(recovery_path):
        raise T09HostError("fallback image cleanup recovery is unsafe")
    candidate = image_id_if_present(prefix, image_tag)
    if candidate is None:
        return None
    observed_labels = _image_config_labels(prefix, candidate)
    if any(observed_labels.get(key) != value for key, value in expected_labels.items()):
        raise T09HostError("visible fallback image is not owned by this exact host run")
    write_exclusive(
        recovery_path,
        {
            "schema_version": "0.1.0",
            "plan_id": contract.plan_id,
            "host_run_id": contract.host_run_id,
            "package_commit": package_commit,
            "image_tag": image_tag,
            "image_id": candidate,
            "fallback_build_intent_sha256": file_sha256(intent_path),
            "owned_image_labels": expected_labels,
            "final_materialization_receipt_absent": True,
        },
    )
    return candidate


class OwnedContainerIdentity(NamedTuple):
    container_id: str
    name: str
    labels: dict[str, str]


def _validate_retained_container_name(name: str) -> None:
    """Validate a retained namespace without using its name as cleanup authority."""

    if re.fullmatch(r"[a-z0-9_.-]+", name) is None:
        raise T09HostError("Docker container name is malformed")
    matching_prefixes = tuple(
        contract
        for contract in PROVIDER_CONTRACTS.values()
        if name.startswith(contract.container_prefix)
    )
    if len(matching_prefixes) != 1:
        raise T09HostError("Docker container name is outside one exact owned namespace")


def _provider_contract_from_container_labels(
    labels: Mapping[str, str],
    *,
    name: str,
) -> T09ProviderContract:
    """Resolve cleanup authority from the exact plan label, then validate its name."""

    plan_id = labels.get("giclab.t09.plan")
    if not isinstance(plan_id, str):
        raise T09HostError("owned Docker labels lack an exact provider plan")
    try:
        contract = provider_contract_for_plan_id(plan_id)
    except T09ProviderContractError as exc:
        raise T09HostError("owned Docker plan label is unsupported") from exc
    if labels.get("giclab.t09.host_run") != contract.host_run_id or not name.startswith(
        contract.container_prefix
    ):
        raise T09HostError("Docker plan authority, host ownership, and name disagree")
    return contract


def _container_id_by_exact_name(prefix: list[str], name: str) -> str | None:
    _validate_retained_container_name(name)
    raw = output(
        [
            *prefix,
            "ps",
            "--all",
            "--filter",
            f"name=^/{name}$",
            "--format",
            "{{.ID}}",
        ]
    )
    identifiers = [item for item in raw.splitlines() if item]
    if not identifiers:
        return None
    if len(identifiers) != 1 or re.fullmatch(r"[a-f0-9]{12,64}", identifiers[0]) is None:
        raise T09HostError("exact Docker name resolved to an ambiguous identity")
    return identifiers[0]


def inspect_owned_container(
    prefix: list[str],
    name: str,
    *,
    expected_container_id: str | None = None,
    expected_role: str | None = None,
) -> OwnedContainerIdentity | None:
    _validate_retained_container_name(name)
    if expected_container_id is not None:
        if re.fullmatch(r"[a-f0-9]{64}", expected_container_id) is None:
            raise T09HostError("expected Docker container identity is malformed")
        raw = output(
            [
                *prefix,
                "ps",
                "--all",
                "--filter",
                f"id={expected_container_id}",
                "--format",
                "{{.ID}}",
            ]
        )
        identifiers = [item for item in raw.splitlines() if item]
        if not identifiers:
            replacement = _container_id_by_exact_name(prefix, name)
            if replacement is not None:
                raise T09HostError("Docker name was reused before exact-ID cleanup")
            return None
        if (
            len(identifiers) != 1
            or re.fullmatch(r"[a-f0-9]{12,64}", identifiers[0]) is None
            or not expected_container_id.startswith(identifiers[0])
        ):
            raise T09HostError("expected Docker identity resolved ambiguously")
        inspect_target = expected_container_id
    else:
        short_id = _container_id_by_exact_name(prefix, name)
        if short_id is None:
            return None
        inspect_target = short_id
    container_id = output([*prefix, "inspect", "--format", "{{.Id}}", inspect_target])
    retained_name = output(
        [*prefix, "inspect", "--format", "{{.Name}}", inspect_target]
    ).removeprefix("/")
    raw_labels = output([*prefix, "inspect", "--format", "{{json .Config.Labels}}", inspect_target])
    try:
        labels_value: object = json.loads(raw_labels)
    except json.JSONDecodeError as exc:
        raise T09HostError("owned Docker labels are malformed") from exc
    if (
        re.fullmatch(r"[a-f0-9]{64}", container_id) is None
        or retained_name != name
        or not isinstance(labels_value, dict)
        or not all(
            isinstance(key, str) and isinstance(value, str) for key, value in labels_value.items()
        )
    ):
        raise T09HostError("owned Docker identity drifted")
    labels = cast(dict[str, str], labels_value)
    _provider_contract_from_container_labels(labels, name=name)
    if not isinstance(labels.get("giclab.t09.role"), str) or (
        expected_role is not None and labels.get("giclab.t09.role") != expected_role
    ):
        raise T09HostError("Docker name collision is not owned by this exact host run")
    return OwnedContainerIdentity(container_id=container_id, name=name, labels=labels)


def inspect_owned_container_by_id(
    prefix: list[str],
    expected_container_id: str,
) -> OwnedContainerIdentity | None:
    """Resolve one cleanup-authoritative ID and derive its typed owned identity."""

    if re.fullmatch(r"[a-f0-9]{64}", expected_container_id) is None:
        raise T09HostError("expected Docker container identity is malformed")
    raw = output(
        [
            *prefix,
            "ps",
            "--all",
            "--filter",
            f"id={expected_container_id}",
            "--format",
            "{{.ID}}",
        ]
    )
    identifiers = [item for item in raw.splitlines() if item]
    if not identifiers:
        return None
    if (
        len(identifiers) != 1
        or re.fullmatch(r"[a-f0-9]{12,64}", identifiers[0]) is None
        or not expected_container_id.startswith(identifiers[0])
    ):
        raise T09HostError("expected Docker identity resolved ambiguously")
    container_id = output([*prefix, "inspect", "--format", "{{.Id}}", expected_container_id])
    name = output(
        [*prefix, "inspect", "--format", "{{.Name}}", expected_container_id]
    ).removeprefix("/")
    raw_labels = output(
        [*prefix, "inspect", "--format", "{{json .Config.Labels}}", expected_container_id]
    )
    try:
        labels_value: object = json.loads(raw_labels)
    except json.JSONDecodeError as exc:
        raise T09HostError("owned Docker labels are malformed") from exc
    if (
        container_id != expected_container_id
        or re.fullmatch(r"[a-z0-9_.-]+", name) is None
        or not isinstance(labels_value, dict)
        or not all(
            isinstance(key, str) and isinstance(value, str) for key, value in labels_value.items()
        )
    ):
        raise T09HostError("owned Docker identity drifted")
    labels = cast(dict[str, str], labels_value)
    _provider_contract_from_container_labels(labels, name=name)
    role = labels.get("giclab.t09.role")
    if not isinstance(role, str) or not role:
        raise T09HostError("Docker ID is not owned by this exact host run")
    return OwnedContainerIdentity(container_id=container_id, name=name, labels=labels)


def remove_container(
    prefix: list[str],
    name: str,
    *,
    expected_container_id: str,
    expected_role: str | None = None,
) -> bool:
    identity = inspect_owned_container(
        prefix,
        name,
        expected_container_id=expected_container_id,
        expected_role=expected_role,
    )
    if identity is None:
        return True
    if expected_container_id is not None and identity.container_id != expected_container_id:
        raise T09HostError("owned Docker identity changed before removal")
    subprocess.run(
        [*prefix, "rm", "--force", identity.container_id],
        env=safe_environment(),
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=False,
        timeout=30,
    )
    # ``docker run --rm`` can start daemon-side auto-removal just before this
    # exact-ID removal executes.  In that race ``docker rm --force`` reports a
    # failure even though the owned container is already disappearing.  The
    # authoritative cleanup result is exact absence, not the competing remove
    # request's exit status.  Reuse the full identity/name/label verifier while
    # boundedly waiting for the daemon to converge; a reused name or changed
    # identity still fails closed inside ``inspect_owned_container``.
    for delay_seconds in (0.0, 0.05, 0.1, 0.2, 0.4, 0.8):
        if delay_seconds:
            time.sleep(delay_seconds)
        remaining = inspect_owned_container(
            prefix,
            name,
            expected_container_id=expected_container_id,
            expected_role=expected_role,
        )
        if remaining is None:
            return True
        if remaining.container_id != expected_container_id:
            raise T09HostError("owned Docker identity changed during removal convergence")
    return False


def owned_containers(
    prefix: list[str],
    *,
    contract: T09ProviderContract,
) -> list[str]:
    raw = output(
        [
            *prefix,
            "ps",
            "--all",
            "--filter",
            f"label=giclab.t09.plan={contract.plan_id}",
            "--filter",
            f"label=giclab.t09.host_run={contract.host_run_id}",
            "--format",
            "{{.Names}}",
        ]
    )
    names = sorted(name for name in raw.splitlines() if name)
    if any(not name.startswith(contract.container_prefix) for name in names):
        raise T09HostError("owned Docker labels resolved outside the frozen name namespace")
    return names


def _owned_containers_for(
    prefix: list[str],
    contract: T09ProviderContract,
) -> list[str]:
    """Resolve owned containers only within the selected contract namespace."""

    return owned_containers(prefix, contract=contract)


def _owned_container_name_matches_role(
    name: str,
    role: str,
    *,
    contract: T09ProviderContract,
) -> bool:
    container_prefix = contract.container_prefix
    if role == "core-suppression-preflight":
        return name == f"{container_prefix}core-preflight"
    if role == "browser-lifecycle-preflight":
        return name == f"{container_prefix}browser-preflight"
    if role == "condition":
        return re.fullmatch(rf"{re.escape(container_prefix)}0[1-4]", name) is not None
    if role == "attempt-finalizer":
        return name.startswith(f"{container_prefix}utility-finalizer-")
    if role.startswith("utility-"):
        return name == f"{container_prefix}{role}"
    return False


def _validate_owned_container_command(
    path: Path,
    *,
    contract: T09ProviderContract,
) -> tuple[str, str]:
    document = load_object(path, label="owned Docker mutation intent")
    argv = document.get("argv", document.get("docker_create_argv"))
    name = document.get("container_name")
    role = document.get("owned_role")
    if (
        document.get("schema_version") != "0.1.0"
        or document.get("owned_by_plan") != contract.plan_id
        or document.get("owned_by_host_run") != contract.host_run_id
        or not isinstance(name, str)
        or not isinstance(role, str)
        or not _owned_container_name_matches_role(name, role, contract=contract)
        or not isinstance(argv, list)
        or not argv
        or not all(isinstance(token, str) for token in argv)
        or "--name" not in argv
        or argv.count("--name") != 1
        or argv[argv.index("--name") + 1] != name
    ):
        raise T09HostError("owned Docker mutation intent is malformed")
    labels = [argv[index + 1] for index, token in enumerate(argv[:-1]) if token == "--label"]
    if (
        labels.count(f"giclab.t09.plan={contract.plan_id}") != 1
        or labels.count(f"giclab.t09.host_run={contract.host_run_id}") != 1
        or labels.count(f"giclab.t09.role={role}") != 1
    ):
        raise T09HostError("owned Docker mutation intent labels drifted")
    return name, role


def owned_container_intents(
    artifact_root: Path,
    *,
    repository: Path,
    contract: T09ProviderContract | None = None,
) -> dict[str, str]:
    """Load the bounded, host-owned ledger of authorized Docker name/role mutations."""

    selected_contract = _runtime_provider_contract(artifact_root) if contract is None else contract
    candidates: list[Path] = []
    pilot_root = _pilot_root(artifact_root, selected_contract)
    if pilot_root.is_dir() and not pilot_root.is_symlink():
        for path in sorted(pilot_root.rglob("*container-command.json")):
            relative = path.relative_to(pilot_root)
            if relative.parts and relative.parts[0] not in {"runtime-budget", "slot2-authority"}:
                candidates.append(path)
    execution_path = _contract_paths_for(repository, selected_contract)["execution"]
    contract = load_execution_contract(
        execution_path,
        expected_sha256=file_sha256(execution_path),
    )
    for run_id in selected_contract.run_ids:
        attempt = contract.attempt(run_id)
        attempt_root = artifact_root / attempt.output_root
        raw_root = artifact_root / attempt.raw_output_root
        candidates.append(raw_root / CONDITION_SUPERVISOR_DIRNAME / "container-command.json")
        finalizer_root = attempt_root / "finalizer-invocations"
        if finalizer_root.is_dir() and not finalizer_root.is_symlink():
            invocations = sorted(finalizer_root.iterdir())
            if len(invocations) > 64 or any(
                path.is_symlink() or not path.is_dir() for path in invocations
            ):
                raise T09HostError("owned Docker finalizer ledger is malformed")
            for invocation in invocations:
                candidates.extend(sorted(invocation.glob("*container-command.json")))
    existing = sorted({path for path in candidates if os.path.lexists(path)})
    if len(existing) > 256:
        raise T09HostError("owned Docker mutation ledger exceeds its bounded cardinality")
    intents: dict[str, str] = {}
    for path in existing:
        metadata = path.lstat()
        if (
            path.is_symlink()
            or not stat.S_ISREG(metadata.st_mode)
            or metadata.st_uid != os.getuid()
            or metadata.st_nlink != 1
            or not 0 < metadata.st_size <= MAX_PRIVACY_JSON_BYTES
        ):
            raise T09HostError("owned Docker mutation intent has unsafe metadata")
        name, role = _validate_owned_container_command(path, contract=selected_contract)
        prior = intents.setdefault(name, role)
        if prior != role:
            raise T09HostError("owned Docker name has conflicting mutation intents")
    return intents


def owned_container_identities(
    prefix: list[str],
    *,
    authorized_intents: dict[str, str],
    contract: T09ProviderContract,
) -> list[OwnedContainerIdentity]:
    identities: list[OwnedContainerIdentity] = []
    for name in _owned_containers_for(prefix, contract):
        role = authorized_intents.get(name)
        if role is None:
            raise T09HostError("labeled Docker object lacks a host-owned mutation intent")
        identity = inspect_owned_container(prefix, name, expected_role=role)
        if identity is None:
            raise T09HostError("owned Docker object disappeared during identity binding")
        identities.append(identity)
    return identities


def tree_bytes(root: Path) -> int:
    total = 0
    if not root.exists():
        return 0
    for directory, _, names in os.walk(root):
        for name in names:
            path = Path(directory) / name
            if not path.is_symlink():
                try:
                    total += path.stat().st_size
                except FileNotFoundError:
                    continue
    return total


class AttemptTreeUsage(NamedTuple):
    bytes: int
    files: int


def full_attempt_tree_usage(attempt_root: Path) -> AttemptTreeUsage:
    """Measure one complete raw+derived attempt without following unsafe members."""

    resolved = attempt_root.resolve(strict=True)
    total = 0
    files = 0
    for path in sorted(resolved.rglob("*")):
        metadata = path.lstat()
        if stat.S_ISDIR(metadata.st_mode):
            continue
        if path.is_symlink() or not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
            raise T09HostError("full attempt tree contains an unsafe retained member")
        total += metadata.st_size
        files += 1
    return AttemptTreeUsage(bytes=total, files=files)


def enforce_full_attempt_output_cap(attempt_root: Path) -> AttemptTreeUsage:
    """Enforce the one declared cap across raw, derived, and supervisor evidence."""

    usage = full_attempt_tree_usage(attempt_root)
    if usage.bytes > MAX_ATTEMPT_OUTPUT_BYTES:
        raise T09HostError("full raw-plus-derived attempt exceeds its exact output cap")
    return usage


def enforce_attempt_supervisor_cap(attempt_root: Path) -> AttemptTreeUsage:
    """Bound seal/export bookkeeping outside raw, control, and derived roots."""

    resolved = attempt_root.resolve(strict=True)
    total = 0
    files = 0
    component_roots = {"raw", "finalized", "attempt-export-control", "essential-failure"}
    for path in sorted(resolved.rglob("*")):
        metadata = path.lstat()
        if stat.S_ISDIR(metadata.st_mode):
            continue
        relative = path.relative_to(resolved)
        if relative.parts and relative.parts[0] in component_roots:
            continue
        if path.is_symlink() or not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
            raise T09HostError("attempt supervisor evidence contains an unsafe retained member")
        total += metadata.st_size
        files += 1
    usage = AttemptTreeUsage(bytes=total, files=files)
    if usage.bytes > MAX_ATTEMPT_SUPERVISOR_BYTES:
        raise T09HostError("attempt supervisor evidence exceeds its reserved byte envelope")
    return usage


_CORE_FILENAME = re.compile(r"^core(?:\..+)?$", re.IGNORECASE)


def _elf_object_type(path: Path) -> str | None:
    """Read only the bounded ELF identification header."""

    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    descriptor = os.open(path, flags)
    try:
        metadata = os.fstat(descriptor)
        if not stat.S_ISREG(metadata.st_mode):
            raise T09HostError("core scan encountered an unsafe file identity")
        header = os.read(descriptor, 18)
    finally:
        os.close(descriptor)
    if len(header) < 18 or header[:4] != b"\x7fELF":
        return None
    byte_order = header[5]
    if byte_order == 1:
        object_type = int.from_bytes(header[16:18], "little")
    elif byte_order == 2:
        object_type = int.from_bytes(header[16:18], "big")
    else:
        return "ELF_UNKNOWN"
    return {
        1: "ET_REL",
        2: "ET_EXEC",
        3: "ET_DYN",
        4: "ET_CORE",
    }.get(object_type, f"ET_{object_type}")


def detect_core_artifacts(root: Path) -> list[dict[str, object]]:
    """Identify known core names and ELF ET_CORE using bounded metadata reads."""

    resolved = root.resolve(strict=True)
    if not resolved.is_dir() or resolved.is_symlink():
        raise T09HostError("core scan root is unsafe")
    scanned: list[tuple[dict[str, object], tuple[int, int] | None]] = []
    entry_count = 0
    for path in sorted(resolved.rglob("*")):
        entry_count += 1
        if entry_count > MAX_CORE_SCAN_ENTRIES:
            raise T09HostError("core scan entry limit exceeded")
        metadata = path.lstat()
        if stat.S_ISDIR(metadata.st_mode):
            continue
        indicators: list[str] = []
        if _CORE_FILENAME.fullmatch(path.name):
            indicators.append("known-core-filename")
        file_type = (
            "symlink"
            if stat.S_ISLNK(metadata.st_mode)
            else "regular"
            if stat.S_ISREG(metadata.st_mode)
            else "other"
        )
        elf_type = _elf_object_type(path) if file_type == "regular" else None
        if elf_type == "ET_CORE":
            indicators.append("elf-et-core")
        record: dict[str, object] = {
            "path": path.relative_to(resolved).as_posix(),
            "bytes": metadata.st_size,
            "mode": f"{stat.S_IMODE(metadata.st_mode):04o}",
            "owner_uid": metadata.st_uid,
            "owner_gid": metadata.st_gid,
            "filesystem_device": metadata.st_dev if file_type == "regular" else None,
            "filesystem_inode": metadata.st_ino if file_type == "regular" else None,
            "mtime_ns": metadata.st_mtime_ns,
            "file_type": file_type,
            "link_count": metadata.st_nlink,
            "classified_links_within_scan_root": 0,
            "destruction_verifiable": False,
            "elf_type": elf_type,
            "indicators": indicators,
            "artifact_classification": "prohibited-transient-security-artifact",
            "scientific_raw_evidence": False,
            "content_or_hash_retained": False,
        }
        identity = (metadata.st_dev, metadata.st_ino) if file_type == "regular" else None
        scanned.append((record, identity))
    core_identities = {
        identity
        for record, identity in scanned
        if identity is not None and cast(list[object], record["indicators"])
    }
    in_root_link_counts: dict[tuple[int, int], int] = {}
    for _record, identity in scanned:
        if identity in core_identities:
            assert identity is not None
            in_root_link_counts[identity] = in_root_link_counts.get(identity, 0) + 1
    records: list[dict[str, object]] = []
    for record, identity in scanned:
        indicators = cast(list[str], record["indicators"])
        if identity in core_identities and not indicators:
            indicators.append("hardlink-alias-of-core-inode")
        if not indicators:
            continue
        classified_links = in_root_link_counts.get(identity, 1) if identity is not None else 1
        link_count = record["link_count"]
        record["classified_links_within_scan_root"] = classified_links
        record["destruction_verifiable"] = (
            identity is not None and type(link_count) is int and link_count == classified_links
        )
        records.append(record)
    return records


def remove_core_artifacts(root: Path, records: list[dict[str, object]]) -> bool:
    """Remove classified paths and report whether every inode link was owned."""

    resolved = root.resolve(strict=True)
    targets: list[Path] = []
    seen_paths: set[str] = set()
    for record in records:
        relative = record.get("path")
        if (
            not isinstance(relative, str)
            or Path(relative).is_absolute()
            or ".." in Path(relative).parts
            or relative in seen_paths
        ):
            raise T09HostError("core cleanup received an unsafe relative path")
        seen_paths.add(relative)
        target = resolved / relative
        metadata = target.lstat()
        file_type = (
            "symlink"
            if stat.S_ISLNK(metadata.st_mode)
            else "regular"
            if stat.S_ISREG(metadata.st_mode)
            else "other"
        )
        if (
            metadata.st_size != record.get("bytes")
            or f"{stat.S_IMODE(metadata.st_mode):04o}" != record.get("mode")
            or metadata.st_uid != record.get("owner_uid")
            or metadata.st_gid != record.get("owner_gid")
            or (
                file_type == "regular"
                and (
                    metadata.st_dev != record.get("filesystem_device")
                    or metadata.st_ino != record.get("filesystem_inode")
                )
            )
            or metadata.st_mtime_ns != record.get("mtime_ns")
            or file_type != record.get("file_type")
            or metadata.st_nlink != record.get("link_count")
        ):
            raise T09HostError("core artifact changed before security cleanup")
        if (
            file_type == "regular"
            and "elf-et-core" in cast(list[object], record.get("indicators"))
            and _elf_object_type(target) != "ET_CORE"
        ):
            raise T09HostError("core ELF identity changed before security cleanup")
        targets.append(target)
    parents: set[Path] = set()
    for target in targets:
        target.unlink()
        parents.add(target.parent)
    for parent in parents:
        directory = os.open(parent, os.O_RDONLY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
    if detect_core_artifacts(resolved):
        raise T09HostError("core artifact destruction could not be verified")
    return all(record.get("destruction_verifiable") is True for record in records)


class CoreCleanupOutcome(NamedTuple):
    """Safe-metadata-only result of one best-effort owned-core destruction."""

    destruction_verified: bool
    error_type: str | None


def cleanup_core_artifacts(
    root: Path,
    records: list[dict[str, object]],
) -> CoreCleanupOutcome:
    """Never lose the rotation decision when unlink/fsync/rescan fails."""

    if not records:
        return CoreCleanupOutcome(destruction_verified=True, error_type=None)
    try:
        verified = remove_core_artifacts(root, records)
    except (OSError, T09HostError) as exc:
        return CoreCleanupOutcome(destruction_verified=False, error_type=type(exc).__name__)
    return CoreCleanupOutcome(destruction_verified=verified, error_type=None)


def _value_safe_core_records(
    records: list[dict[str, object]],
    *,
    credential_bytes: bytes = b"",
) -> list[dict[str, object]]:
    """Redact evidence-path values without weakening operational cleanup identity."""

    projected: list[dict[str, object]] = []
    for ordinal, raw in enumerate(records, start=1):
        record = dict(raw)
        relative = record.get("path")
        if not isinstance(relative, str):
            raise T09HostError("core evidence path is malformed")
        encoded = relative.encode("utf-8", errors="surrogateescape")
        if (
            (credential_bytes and credential_bytes in encoded)
            or _CREDENTIAL_TEXT.search(relative)
            or _JUPYTER_URL.search(relative)
            or _private_network_values(relative)
        ):
            record["path"] = f"<redacted-core-artifact-{ordinal:04d}>"
            record["path_redacted"] = True
            record["path_redaction_reason"] = "sensitive-evidence-path"
        projected.append(record)
    return projected


def _core_record_recovery_identity(record: dict[str, object]) -> tuple[object, ...]:
    """Return a content-free identity used only to reconcile repeated censuses."""

    device = record.get("filesystem_device")
    inode = record.get("filesystem_inode")
    path = record.get("path")
    if type(device) is int and type(inode) is int:
        # Keep distinct in-root aliases when their paths are safe.  If a path
        # had to be redacted, a counted multiset still prevents a surviving
        # subset of the same inode from being counted twice on recovery.
        return (
            "regular",
            device,
            inode,
            None if record.get("path_redacted") is True else path,
        )
    return (
        "non-regular",
        None if record.get("path_redacted") is True else path,
        record.get("file_type"),
        record.get("bytes"),
        record.get("mode"),
        record.get("owner_uid"),
        record.get("owner_gid"),
        record.get("mtime_ns"),
    )


def _new_core_records_since_historic_census(
    *,
    historic_safe_records: list[dict[str, object]],
    current_records: list[dict[str, object]],
    credential_bytes: bytes,
) -> tuple[list[dict[str, object]], list[dict[str, object]]]:
    """Return only genuinely new current records and their safe projection."""

    current_safe = _value_safe_core_records(
        current_records,
        credential_bytes=credential_bytes,
    )
    historic_counts: dict[tuple[object, ...], int] = {}
    for record in historic_safe_records:
        identity = _core_record_recovery_identity(record)
        historic_counts[identity] = historic_counts.get(identity, 0) + 1
    new_operational: list[dict[str, object]] = []
    new_safe: list[dict[str, object]] = []
    for operational, safe in zip(current_records, current_safe, strict=True):
        identity = _core_record_recovery_identity(safe)
        retained_count = historic_counts.get(identity, 0)
        if retained_count:
            historic_counts[identity] = retained_count - 1
            continue
        new_operational.append(operational)
        new_safe.append(safe)
    return new_operational, new_safe


def _core_paths_within_subtree(
    records: list[dict[str, object]],
    *,
    scan_root: Path,
    subtree: Path,
) -> frozenset[str]:
    """Project operational scan-root paths into one narrower evidence root."""

    prefix = subtree.resolve(strict=True).relative_to(scan_root.resolve(strict=True)).parts
    projected: set[str] = set()
    for record in records:
        relative = record.get("path")
        if not isinstance(relative, str):
            raise T09HostError("core scan record path is malformed")
        parts = PurePosixPath(relative).parts
        if tuple(parts[: len(prefix)]) == tuple(prefix) and len(parts) > len(prefix):
            projected.add(PurePosixPath(*parts[len(prefix) :]).as_posix())
    return frozenset(projected)


def _paths_within_subtree(
    relative_paths: Iterable[str],
    *,
    scan_root: Path,
    subtree: Path,
) -> frozenset[str]:
    """Project scan-root-relative paths into one exact child evidence root."""

    prefix = subtree.resolve(strict=True).relative_to(scan_root.resolve(strict=True)).parts
    projected: set[str] = set()
    for relative in relative_paths:
        parts = PurePosixPath(relative).parts
        if tuple(parts[: len(prefix)]) == tuple(prefix) and len(parts) > len(prefix):
            projected.add(PurePosixPath(*parts[len(prefix) :]).as_posix())
    return frozenset(projected)


def core_cleanup_projection(
    records: list[dict[str, object]],
    outcome: CoreCleanupOutcome,
    *,
    credential_bytes: bytes = b"",
) -> dict[str, object]:
    """Return the one typed evidence projection shared by every core producer."""

    return {
        "core_artifacts_detected": _value_safe_core_records(
            records,
            credential_bytes=credential_bytes,
        ),
        "core_artifact_count": len(records),
        "core_content_or_hash_retained": False,
        "core_transferred_outside_remote_host": False,
        "destruction_verified": outcome.destruction_verified,
        "cleanup_error_type": outcome.error_type,
        "credential_rotation_required_due_to_core_handling": (
            bool(records) and not outcome.destruction_verified
        ),
    }


def persist_core_detection_before_cleanup(
    *,
    receipt_path: Path,
    records: list[dict[str, object]],
    scope: str,
    credential_bytes: bytes = b"",
    scan_integrity_failure: bool = False,
) -> str:
    """Durably retain safe core facts before any unlink or container-layer removal."""

    document = {
        "schema_version": "0.1.0",
        "scope": scope,
        "core_artifacts_detected": _value_safe_core_records(
            records,
            credential_bytes=credential_bytes,
        ),
        "core_artifact_count": len(records),
        "core_scan_integrity_failure": scan_integrity_failure,
        "all_detected_artifacts_destruction_verifiable": bool(records)
        and all(record.get("destruction_verifiable") is True for record in records),
        "core_content_or_hash_retained": False,
        "core_transferred_outside_remote_host": False,
        "destructive_cleanup_not_yet_claimed": True,
    }
    write_exclusive_or_validate(
        receipt_path,
        document,
        label="pre-destruction core detection",
    )
    return file_sha256(receipt_path)


def mark_artifact_root_core_safety_stop(artifact_root: Path) -> None:
    """Monotonically bind any preflight/finalizer core incident to pilot state."""

    state_path = _pilot_root(artifact_root) / "pilot-state.json"
    state = load_object(state_path, label="core safety pilot state")
    execution_contract_sha256 = state.get("execution_contract_sha256")
    if not isinstance(execution_contract_sha256, str):
        raise T09HostError("core safety stop lacks its execution-contract binding")
    mark_core_safety_stop(
        state_path,
        execution_contract_sha256=execution_contract_sha256,
    )


def _zero_inheritance_projection(value: object, *, expected_depth: int) -> bool:
    if not isinstance(value, dict):
        return False
    if (
        value.get("depth") != expected_depth
        or value.get("core_soft_limit") != 0
        or value.get("core_hard_limit") != 0
    ):
        return False
    child = value.get("child")
    if expected_depth == 2:
        return child is None
    return _zero_inheritance_projection(child, expected_depth=expected_depth + 1)


def _validate_writable_root_core_scan(
    value: object,
    *,
    expected_roots: list[str],
    artifact_label_prefix: str,
) -> list[dict[str, object]]:
    """Validate a value-safe in-container census before its writable layer is removed."""

    if not isinstance(value, dict):
        raise T09HostError("in-container writable-root core scan is missing")
    records = value.get("core_artifacts")
    if (
        set(value)
        != {
            "schema_version",
            "scan_roots",
            "core_artifact_count",
            "core_artifacts",
            "core_content_or_hash_retained",
        }
        or value.get("schema_version") != "0.1.0"
        or value.get("scan_roots") != expected_roots
        or not isinstance(records, list)
        or value.get("core_artifact_count") != len(records)
        or value.get("core_content_or_hash_retained") is not False
    ):
        raise T09HostError("in-container writable-root core scan is malformed")
    for ordinal, raw in enumerate(records, start=1):
        if (
            not isinstance(raw, dict)
            or set(raw)
            != {
                "artifact",
                "writable_root",
                "bytes",
                "known_core_filename",
                "elf_et_core",
                "content_or_hash_retained",
            }
            or raw.get("artifact") != f"<{artifact_label_prefix}-artifact-{ordinal:04d}>"
            or raw.get("writable_root") not in expected_roots
            or type(raw.get("bytes")) is not int
            or cast(int, raw["bytes"]) < 0
            or not isinstance(raw.get("known_core_filename"), bool)
            or not isinstance(raw.get("elf_et_core"), bool)
            or not (raw["known_core_filename"] or raw["elf_et_core"])
            or raw.get("content_or_hash_retained") is not False
        ):
            raise T09HostError("in-container writable-root core record is malformed")
    return cast(list[dict[str, object]], records)


def core_suppression_preflight(
    *,
    repository: Path,
    artifact_root: Path,
    prefix: list[str],
    image_id: str,
    cleanup_journal: EarlyCleanupJournal,
    contract: T09ProviderContract,
) -> dict[str, object]:
    """Prove Docker, entrypoint-child, and abort behavior in the accepted image."""

    attempt = _pilot_root(artifact_root, contract) / "core-suppression-preflight"
    attempt.mkdir(parents=True, mode=0o700, exist_ok=False)
    source = repository / "containers/sira-smoke/pragmatic/t09_core_preflight.py"
    name = f"{contract.container_prefix}core-preflight"
    plan_label = f"giclab.t09.plan={contract.plan_id}"
    host_label = f"giclab.t09.host_run={contract.host_run_id}"
    create = [
        *prefix,
        "create",
        *CORE_ULIMIT_DOCKER_ARGS,
        "--name",
        name,
        "--label",
        plan_label,
        "--label",
        host_label,
        "--label",
        "giclab.t09.role=core-suppression-preflight",
        "--platform",
        "linux/amd64",
        "--network",
        "none",
        "--log-driver",
        "none",
        "--ipc",
        "private",
        "--read-only",
        "--cap-drop",
        "ALL",
        "--security-opt",
        "no-new-privileges=true",
        "--init",
        "--restart",
        "no",
        "--cpus",
        "2.0",
        "--memory",
        "4g",
        "--memory-swap",
        "4g",
        "--pids-limit",
        "512",
        "--shm-size",
        "1g",
        "--tmpfs",
        "/tmp:rw,noexec,nosuid,nodev,size=134217728,uid=1000,gid=1000,mode=0700",
        "--user",
        "1000:1000",
        "--env",
        "CUDA_VISIBLE_DEVICES=",
        "--mount",
        f"type=bind,src={attempt},dst=/giclab/attempt",
        "--mount",
        f"type=bind,src={source},dst=/opt/giclab/t09_core_preflight.py,readonly",
        "--mount",
        (
            "type=bind,src="
            f"{repository / 'containers/sira-smoke/container_entrypoint.py'},"
            "dst=/opt/giclab/container_entrypoint.py,readonly"
        ),
        "--entrypoint",
        "/opt/sira/.venv/bin/python",
        image_id,
        "/opt/giclab/container_entrypoint.py",
        "--core-preflight",
        "--",
        "/opt/sira/.venv/bin/python",
        "/opt/giclab/t09_core_preflight.py",
    ]
    removed = False
    create_mutation_attempted = False
    created_identity: OwnedContainerIdentity | None = None
    container_state: dict[str, object] | None = None
    lifecycle_error: BaseException | None = None
    cleanup_result: CleanupTargetState | None = None
    cleanup_detail: str | None = None
    internal_scan_path = attempt / "core-suppression-writable-root-core-scan.json"
    internal_scan: dict[str, Any] | None = None
    internal_scan_records: list[dict[str, object]] = []
    internal_scan_integrity_failure = False
    try:
        if _container_id_by_exact_name(prefix, name) is not None:
            raise T09HostError("core-preflight Docker name is already occupied")
        write_exclusive(
            attempt / "container-command.json",
            {
                "schema_version": "0.1.0",
                "container_name": name,
                "argv": create,
                "argv_sha256": canonical_sha256(create),
                "owned_by_plan": contract.plan_id,
                "owned_by_host_run": contract.host_run_id,
                "owned_role": "core-suppression-preflight",
            },
        )
        create_mutation_attempted = True
        run_logged(
            create,
            evidence_root=attempt,
            label="container-create",
            timeout=60,
            contract=contract,
        )
        created_identity = inspect_owned_container(
            prefix,
            name,
            expected_role="core-suppression-preflight",
        )
        if created_identity is None:
            raise T09HostError("core-preflight Docker identity disappeared after create")
        register_owned_container_cleanup(
            cleanup_journal,
            created_identity,
            role="core-suppression-preflight",
        )
        write_exclusive(
            attempt / "container-identity.json",
            {
                "schema_version": "0.1.0",
                "container_name": name,
                "container_id": created_identity.container_id,
                "owned_by_plan": contract.plan_id,
                "owned_by_host_run": contract.host_run_id,
                "owned_role": "core-suppression-preflight",
                "docker_create_argv_sha256": canonical_sha256(create),
            },
        )
        start_identity = inspect_owned_container(
            prefix,
            name,
            expected_container_id=created_identity.container_id,
            expected_role="core-suppression-preflight",
        )
        if start_identity != created_identity:
            raise T09HostError("core-preflight Docker identity changed before start")
        run_logged(
            [*prefix, "start", "--attach", created_identity.container_id],
            evidence_root=attempt,
            label="container-start",
            timeout=90,
            contract=contract,
        )
        container_state = container_state_receipt(prefix, created_identity.container_id)
    except BaseException as exc:
        lifecycle_error = exc
    finally:
        if internal_scan_path.is_file() and not internal_scan_path.is_symlink():
            try:
                internal_scan = load_object(
                    internal_scan_path,
                    label="core-suppression writable-root core scan",
                )
                internal_scan_records = _validate_writable_root_core_scan(
                    internal_scan,
                    expected_roots=["/giclab/attempt", "/tmp", "/dev/shm"],
                    artifact_label_prefix="core-preflight",
                )
            except (OSError, UnicodeError, json.JSONDecodeError, T09HostError):
                internal_scan_integrity_failure = True
            if internal_scan_records or internal_scan_integrity_failure:
                mark_artifact_root_core_safety_stop(artifact_root)
        if container_state is None and create_mutation_attempted:
            try:
                container_state = container_state_receipt(
                    prefix,
                    created_identity.container_id if created_identity is not None else name,
                )
            except (OSError, subprocess.SubprocessError, T09HostError) as exc:
                container_state = {
                    "status": "inspection-unavailable",
                    "running": None,
                    "inspection_error_type": type(exc).__name__,
                    "private_network_fields_retained": False,
                }
        if create_mutation_attempted:
            try:
                cleanup_identity = created_identity or inspect_owned_container(
                    prefix,
                    name,
                    expected_role="core-suppression-preflight",
                )
                if cleanup_identity is None:
                    removed = True
                    cleanup_result, cleanup_detail = verified_owned_container_cleanup_result(
                        initially_absent=True,
                        removal_verified=True,
                        removed_detail="core-preflight-container-removed",
                        absent_detail="core-preflight-container-already-absent",
                    )
                else:
                    removed = remove_container(
                        prefix,
                        name,
                        expected_container_id=cleanup_identity.container_id,
                        expected_role="core-suppression-preflight",
                    )
                    cleanup_result, cleanup_detail = verified_owned_container_cleanup_result(
                        initially_absent=False,
                        removal_verified=removed,
                        removed_detail="core-preflight-container-removed",
                        absent_detail="core-preflight-container-already-absent",
                    )
                    if cleanup_result is CleanupTargetState.FAILED and lifecycle_error is None:
                        lifecycle_error = T09HostError(
                            "core-preflight container absence could not be verified"
                        )
            except (OSError, subprocess.SubprocessError, T09HostError) as exc:
                cleanup_result = CleanupTargetState.FAILED
                cleanup_detail = type(exc).__name__
                if lifecycle_error is None:
                    lifecycle_error = exc
        if (
            created_identity is not None
            and cleanup_result is not None
            and cleanup_detail is not None
        ):
            try:
                record_owned_container_cleanup_result(
                    cleanup_journal,
                    created_identity,
                    result=cleanup_result,
                    detail_code=cleanup_detail,
                )
            except EarlyCleanupStateError as exc:
                if lifecycle_error is None:
                    lifecycle_error = exc
    receipt_path = attempt / "core-suppression-preflight.json"
    receipt = (
        load_object(receipt_path, label="core suppression preflight")
        if receipt_path.is_file()
        else {}
    )
    core_records = detect_core_artifacts(attempt)
    try:
        residue = _owned_containers_for(prefix, contract)
    except (OSError, subprocess.SubprocessError, T09HostError) as exc:
        residue = ["<owned-container-enumeration-unavailable>"]
        if lifecycle_error is None:
            lifecycle_error = exc
    internal_destruction_verified = not internal_scan_integrity_failure and removed and not residue
    if internal_scan_records or internal_scan_integrity_failure:
        write_exclusive(
            attempt / "core-suppression-internal-core-cleanup.json",
            {
                "schema_version": "0.1.0",
                "core_suppression_writable_root_core_scan_sha256": (
                    file_sha256(internal_scan_path) if internal_scan_path.is_file() else None
                ),
                "core_artifact_count": len(internal_scan_records),
                "core_scan_integrity_failure": internal_scan_integrity_failure,
                "container_removed": removed,
                "owned_container_residue": residue,
                "destruction_verified": internal_destruction_verified,
                "credential_rotation_required_due_to_core_handling": (
                    not internal_destruction_verified
                ),
                "core_content_or_hash_retained": False,
            },
        )
    if (
        receipt.get("core_limit_contract") != CORE_LIMIT_CONTRACT
        or receipt.get("core_soft_limit") != 0
        or receipt.get("core_hard_limit") != 0
        or not _zero_inheritance_projection(receipt.get("inheritance"), expected_depth=1)
        or receipt.get("synthetic_abort_nonzero") is not True
        or receipt.get("synthetic_abort_signal") != "SIGABRT"
        or receipt.get("writable_root_core_artifact_count") != len(internal_scan_records)
        or receipt.get("writable_root_core_scan") != internal_scan_path.name
        or internal_scan is None
        or internal_scan_integrity_failure
        or internal_scan_records
        or core_records
        or not removed
        or residue
    ):
        if core_records:
            mark_artifact_root_core_safety_stop(artifact_root)
            detection_sha256 = persist_core_detection_before_cleanup(
                receipt_path=attempt / "core-artifact-detection.json",
                records=core_records,
                scope="exact-container-core-suppression-preflight",
            )
            cleanup_outcome = cleanup_core_artifacts(attempt, core_records)
            write_exclusive(
                attempt / "core-artifact-cleanup.json",
                {
                    "schema_version": "0.1.0",
                    "scope": "exact-container-core-suppression-preflight",
                    **core_cleanup_projection(core_records, cleanup_outcome),
                    "core_detection_receipt_sha256": detection_sha256,
                    "core_scan_integrity_failure": False,
                    "empirical_entry_permitted": False,
                },
            )
        raise T09HostError("exact-container core suppression preflight failed")
    if lifecycle_error is not None:
        raise T09HostError("core suppression container lifecycle failed closed") from (
            lifecycle_error
        )
    result = {
        "schema_version": "0.1.0",
        "plan_id": contract.plan_id,
        "qualification_id": contract.active_image_qualification_id,
        "replacement_image_id": image_id,
        "core_limit_contract": CORE_LIMIT_CONTRACT,
        "docker_ulimit": "core=0:0",
        "core_soft_limit": 0,
        "core_hard_limit": 0,
        "child_and_grandchild_inherited_zero": True,
        "synthetic_abort_nonzero": True,
        "synthetic_abort_signal": "SIGABRT",
        "writable_root_core_scan_sha256": file_sha256(internal_scan_path),
        "core_filename_count": 0,
        "elf_et_core_count": 0,
        "container_removed": True,
        "owned_container_residue": [],
        "container_state": container_state,
    }
    write_exclusive(attempt / "host-core-suppression.json", result)
    return result


def validate_secret_metadata(path: Path) -> None:
    descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        metadata = os.fstat(descriptor)
        if (
            not stat.S_ISREG(metadata.st_mode)
            or metadata.st_uid != os.getuid()
            or metadata.st_nlink != 1
            or stat.S_IMODE(metadata.st_mode) != 0o600
            or not 16 <= metadata.st_size <= 16_384
        ):
            raise T09HostError("provider credential metadata is unsafe")
    finally:
        os.close(descriptor)


def validate_secret(path: Path) -> bytes:
    validate_secret_metadata(path)
    descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        value = os.read(descriptor, 16_385)
    finally:
        os.close(descriptor)
    if not 16 <= len(value) <= 16_384:
        raise T09HostError("provider credential is malformed")
    return value


def destroy_secret(path: Path) -> bool:
    try:
        descriptor = os.open(
            path,
            os.O_RDWR | getattr(os, "O_NOFOLLOW", 0),
        )
    except FileNotFoundError:
        return True
    try:
        metadata = os.fstat(descriptor)
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
            return False
        remaining = metadata.st_size
        os.lseek(descriptor, 0, os.SEEK_SET)
        zero = b"\0" * min(65_536, max(remaining, 1))
        while remaining:
            written = os.write(descriptor, zero[: min(remaining, len(zero))])
            if written <= 0:
                return False
            remaining -= written
        os.ftruncate(descriptor, 0)
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
    path.unlink()
    return not path.exists()


def secret_hits(
    root: Path,
    secret: bytes,
    *,
    excluded_relative_paths: frozenset[str] = frozenset(),
) -> list[str]:
    hits: list[str] = []
    for path in sorted(root.rglob("*")):
        relative = path.relative_to(root).as_posix()
        if relative in excluded_relative_paths:
            continue
        if secret and secret in relative.encode("utf-8", errors="surrogateescape"):
            hits.append(relative)
            continue
        if path.is_file() and not path.is_symlink() and path.stat().st_size <= MAX_PILOT_DISK_BYTES:
            with path.open("rb") as handle:
                overlap = b""
                while chunk := handle.read(1_048_576):
                    combined = overlap + chunk
                    if secret in combined:
                        hits.append(relative)
                        break
                    overlap = combined[-(len(secret) - 1) :] if len(secret) > 1 else b""
    return hits


def record_preflight_credential_scan(
    *,
    artifact_root: Path,
    secret_file: Path,
    execution_contract_sha256: str,
) -> dict[str, object]:
    """Scan after the sole metadata GET and permanently stop on any exact match."""

    credential = validate_secret(secret_file)
    hits = secret_hits(artifact_root, credential)
    exposure_detected = bool(hits)
    if exposure_detected:
        # Commit the monotonic safety stop before destroying the only
        # credential-bearing evidence.
        mark_actual_credential_exposure(
            _pilot_root(artifact_root) / "pilot-state.json",
            execution_contract_sha256=execution_contract_sha256,
        )
    removed: list[dict[str, object]] = []
    for relative in hits:
        target = artifact_root / relative
        try:
            metadata = target.lstat()
        except FileNotFoundError:
            continue
        if not stat.S_ISDIR(metadata.st_mode):
            removed.append(
                {
                    "path": "<redacted-exact-secret-bearing-artifact>",
                    "bytes": metadata.st_size,
                    "classification": "exact-secret-bearing-artifact-removed",
                }
            )
            target.unlink()
    remaining_raw = secret_hits(artifact_root, credential)
    remaining = ["<redacted-exact-secret-bearing-artifact>"] if remaining_raw else []
    credential = b""
    receipt: dict[str, object] = {
        "schema_version": "0.1.0",
        "scan_point": "immediately-after-sole-model-metadata-get-before-freeze",
        "actual_credential_exposure_detected": exposure_detected,
        "secret_bearing_artifacts_removed": removed,
        "remaining_exact_secret_matches": remaining,
        "exact_secret_scan_passed": not exposure_detected and not remaining,
        "empirical_entry_permitted": not exposure_detected and not remaining,
        "recorded_at": utc_now(),
    }
    write_exclusive(
        _pilot_root(artifact_root) / "model-metadata-credential-scan.json",
        receipt,
    )
    if exposure_detected or remaining:
        raise T09HostError(
            "model-metadata preflight exposed the exact credential; "
            "cleanup and termination are required"
        )
    return receipt


def contract_paths(repository: Path, contract: T09ProviderContract) -> dict[str, Path]:
    experiment = repository / "experiments/EXP-0001-sira-simulative-vs-reactive"
    return {
        "plan": repository / contract.provider_profile_path,
        "execution": repository / cast(str, contract.execution_contract_path),
        "commands": repository / cast(str, contract.command_manifest_path),
        "conditions": experiment / "run-plans/conditions",
        "dataset": experiment / "contracts/T09_PILOT_DATASET_CONTRACT.json",
        "evaluator": experiment / "contracts/T09_PILOT_EVALUATOR_CONTRACT.json",
        "runtime": repository
        / (
            "experiments/EXP-0001-sira-simulative-vs-reactive/contracts/proposals/"
            f"T09_PILOT_RUNTIME_IDENTITY_{contract.version}.json"
        ),
        "real_regression": experiment / "T09_PRAGMATIC_RETRY4_FINALIZER_REGRESSION.json",
    }


def _contract_paths_for(
    repository: Path,
    contract: T09ProviderContract,
) -> dict[str, Path]:
    """Resolve package paths only from the explicitly selected contract."""

    return contract_paths(repository, contract)


def early_cleanup_journal(args: argparse.Namespace) -> EarlyCleanupJournal:
    """Load the exact transferred cleanup authority without pilot-state dependence."""

    raw_path = getattr(args, "early_cleanup_journal", None)
    if not isinstance(raw_path, Path):
        raise T09HostError("early cleanup journal path is required")
    journal = EarlyCleanupJournal(raw_path.resolve(strict=True))
    try:
        state = journal.load()
    except EarlyCleanupStateError as exc:
        raise T09HostError("early cleanup journal is not a valid durable authority") from exc
    try:
        contract = provider_contract_for_plan_id(state.plan_id)
    except T09ProviderContractError as exc:
        raise T09HostError("early cleanup journal names an unsupported campaign") from exc
    if state.host_run_id != contract.host_run_id:
        raise T09HostError("early cleanup journal belongs to another campaign")
    return journal


def register_owned_container_cleanup(
    journal: EarlyCleanupJournal,
    identity: OwnedContainerIdentity,
    *,
    role: str,
) -> None:
    """Persist one exact owned container immediately after Docker returns its ID."""

    state = journal.load()
    try:
        contract = provider_contract_for_plan_id(state.plan_id)
    except T09ProviderContractError as exc:
        raise T09HostError("cleanup journal names an unsupported campaign") from exc
    if (
        state.host_run_id != contract.host_run_id
        or identity.labels.get("giclab.t09.plan") != contract.plan_id
        or identity.labels.get("giclab.t09.host_run") != contract.host_run_id
    ):
        raise T09HostError("owned container and cleanup journal cross campaign boundaries")
    target_id = f"owned-container-{identity.container_id}"
    journal.register_target(
        target_id=target_id,
        kind=CleanupTargetKind.OWNED_CONTAINER,
        locator=identity.container_id,
        ownership_sha256=cleanup_locator_identity(
            CleanupTargetKind.OWNED_CONTAINER,
            identity.container_id,
        ),
        public_alias=f"owned-container/{role}/{identity.name}",
    )
    journal.advance_lifecycle_at_least(CleanupLifecycleStage.CONTAINER_CREATION)


def record_owned_container_cleanup_result(
    journal: EarlyCleanupJournal,
    identity: OwnedContainerIdentity,
    *,
    result: CleanupTargetState,
    detail_code: str,
) -> None:
    """Persist normal exact-container terminalization without entering closeout."""

    journal.record_result(
        target_id=f"owned-container-{identity.container_id}",
        result=result,
        detail_code=detail_code,
        during_cleanup=False,
    )


def verified_owned_container_cleanup_result(
    *,
    initially_absent: bool,
    removal_verified: bool,
    removed_detail: str,
    absent_detail: str,
) -> tuple[CleanupTargetState, str]:
    """Project exact absence proof; a false removal result is never absence."""

    if initially_absent:
        return CleanupTargetState.ABSENT, absent_detail
    if removal_verified:
        return CleanupTargetState.REMOVED, removed_detail
    return CleanupTargetState.FAILED, "owned-container-removal-unverified"


_REMOTE_CLEANUP_TARGET_KINDS: Final = frozenset(
    {
        CleanupTargetKind.TEMPORARY_REMOTE_CREDENTIAL,
        CleanupTargetKind.OWNED_CONTAINER,
    }
)
_TERMINAL_CLEANUP_TARGET_STATES: Final = frozenset(
    {
        CleanupTargetState.ABSENT,
        CleanupTargetState.TERMINAL,
        CleanupTargetState.RESTORED,
        CleanupTargetState.REMOVED,
    }
)


def _unfinished_remote_cleanup_target_ids(journal: EarlyCleanupJournal) -> list[str]:
    return [
        target.target_id
        for target in journal.load().targets
        if target.kind in _REMOTE_CLEANUP_TARGET_KINDS
        and target.state not in _TERMINAL_CLEANUP_TARGET_STATES
    ]


def _write_remote_early_closeout_receipt(journal: EarlyCleanupJournal) -> Path:
    state = journal.load()
    return journal.write_basic_closeout_receipt(
        journal.root / f"REMOTE_CLOSEOUT-{state.sequence:08d}.json"
    )


def validate_real_evidence_regression(
    repository: Path,
    *,
    contract: T09ProviderContract,
    expected_finalizer_source_sha256: str | None = None,
) -> dict[str, Any]:
    """Validate the historical receipt without conflating it with the V7 finalizer.

    The receipt proves the immutable V4 archive and the exact finalizer that
    originally produced its semantic projection.  V7 historical-regression
    callers pass that original identity explicitly.  The current V7 finalizer
    is independently source-bound by the local qualification and is then
    executed twice against that archive in ``qualified_real_evidence_regression``.
    """

    paths = contract_paths(repository, contract)
    receipt = load_object(paths["real_regression"], label="real-evidence finalizer regression")
    semantic = receipt.get("semantic_projection")
    evaluator_closure = receipt.get("evaluator_closure")
    repeat_roots = receipt.get("deterministic_distinct_finalization_roots")
    if (
        receipt.get("schema_version") != "0.1.0"
        or receipt.get("receipt_id") != "T09-PRAGMATIC-RETRY4-REAL-EVIDENCE-REGRESSION-0001"
        or receipt.get("source_plan_id") != "PLAN-EXP0001-PILOT-V4"
        or receipt.get("source_run_id") != "RUN-T09-TASK-A-REACTIVE-0002"
        or receipt.get("source_archive_sha256")
        != "63ed19b35bcb4cb62c3796a80a48004937340eb3826f9657a1006e251772255d"
        or receipt.get("source_public_disposition_sha256")
        != "ecc0e135695e16f68d52b7aa85b70d42b1f1e945f7dd119fb7c7ff0e42fc8231"
        or receipt.get("finalizer_source_sha256")
        != (
            expected_finalizer_source_sha256
            if expected_finalizer_source_sha256 is not None
            else file_sha256(repository / FINALIZER_RELATIVE_PATH)
        )
        or receipt.get("dataset_sha256")
        != "359300b029c6891567816f351bf8786e9b018d7af8a1a44b7da9ba5ef4651288"
        or receipt.get("dataset_bytes") != 1_177_174
        or not isinstance(evaluator_closure, dict)
        or evaluator_closure.get("evaluator_contract_sha256") != file_sha256(paths["evaluator"])
        or evaluator_closure.get("dependency_package_manifest_sha256")
        != canonical_sha256(expected_evaluator_packages(repository, contract))
        or not isinstance(repeat_roots, list)
        or len(repeat_roots) != 2
        or any(
            not isinstance(item, dict)
            or item.get("semantic_projection_sha256") != canonical_sha256(semantic)
            for item in repeat_roots
        )
        or repeat_roots[0].get("root") == repeat_roots[1].get("root")
        or not isinstance(semantic, dict)
        or semantic.get("task_id") != "7dcbbbdc7f1120cd"
        or semantic.get("condition") != "SIRA-REACTIVE"
        or semantic.get("model_revision") != "gpt-4o-2024-11-20"
        or semantic.get("sira_commit") != SIRA_COMMIT
        or semantic.get("task_completed") is not True
        or semantic.get("answer_produced") is not True
        or semantic.get("evaluator_valid") is not True
        or semantic.get("score") != 0.0
        or semantic.get("provider_call_count") != 52
        or semantic.get("browser_action_count") != 13
        or receipt.get("accepted_scientific_and_evaluator_fields_equal") is not True
        or receipt.get("network_disabled") is not True
        or receipt.get("additional_model_requests") != 0
        or receipt.get("additional_browser_actions") != 0
        or receipt.get("source_raw_mutated") is not False
        or receipt.get("prior_attempt_excluded_from_v6_campaign") is not True
        or receipt.get("private_source_path_retained") is not False
    ):
        raise T09HostError("real-evidence finalizer regression receipt drifted")
    return receipt


def _retained_tree_manifest(root: Path, *, label: str) -> dict[str, object]:
    files: list[dict[str, object]] = []
    total = 0
    for path in sorted(root.rglob("*")):
        if path.is_symlink():
            raise T09HostError(f"{label} contains a symlink")
        metadata = path.stat(follow_symlinks=False)
        if path.is_dir():
            continue
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
            raise T09HostError(f"{label} contains an unsafe file")
        total += metadata.st_size
        if total > MAX_PILOT_DISK_BYTES:
            raise T09HostError(f"{label} exceeds the retained-evidence cap")
        files.append(
            {
                "path": path.relative_to(root).as_posix(),
                "bytes": metadata.st_size,
                "sha256": file_sha256(path),
            }
        )
    if not files:
        raise T09HostError(f"{label} is empty")
    return {
        "files": files,
        "file_count": len(files),
        "total_bytes": total,
        "files_sha256": canonical_sha256(files),
    }


def _prior_qualification_failure_manifest(root: Path) -> dict[str, object]:
    if root.name != "t09-pilot-v7-output-0002":
        raise T09HostError("prior qualification root identity drifted")
    state_path = root / "pilot-v7/pilot-state.json"
    state = load_object(state_path, label="prior qualification state")
    _require_provider_contract(
        state,
        expected=PACKAGE_TRANSITION_PROVIDER_CONTRACT,
        label="prior qualification state",
    )
    env_example = (
        root / "pilot-v7/replacement-image-qualification/work/build-context/upstream/.env.example"
    )
    if (
        state.get("plan_id") != PACKAGE_TRANSITION_PROVIDER_CONTRACT.plan_id
        or state.get("empirical_attempts_entered") != []
        or state.get("supervised_release_bindings") != {}
        or state.get("unreleased_supervised_release_reclassifications") != {}
        or state.get("condition_start_reservation") is not None
        or state.get("attempts_completed") != []
        or not env_example.is_file()
        or env_example.stat(follow_symlinks=False).st_size != PINNED_ENV_EXAMPLE_BYTES
        or file_sha256(env_example) != PINNED_ENV_EXAMPLE_SHA256
        or (root / "pilot-v7/frozen-run-manifest.json").exists()
        or (root / "pilot-v7/replacement-image-qualification/build-context-manifest.json").exists()
    ):
        raise T09HostError("prior qualification failure prefix is not the exact safe prefix")
    retained = _retained_tree_manifest(root, label="prior qualification prefix")
    return {
        "root_name": root.name,
        "qualification_id": CONTEXT_FAILURE_QUALIFICATION_ID,
        "classification": "preentry-pinned-names-only-env-example-rejected",
        "empirical_entry_crossed": False,
        "model_metadata_requests": 0,
        "task_model_requests": 0,
        "task_browser_actions": 0,
        "replacement_image_built": False,
        **retained,
    }


def _failed_candidate_manifest(
    root: Path,
    *,
    require_image_present: bool,
) -> dict[str, object]:
    if root.name != "t09-pilot-v7-output-0003":
        raise T09HostError("failed candidate root identity drifted")
    state = load_object(root / "pilot-v7/pilot-state.json", label="failed candidate state")
    qualification_root = root / "pilot-v7/replacement-image-qualification"
    receipt_path = qualification_root / "receipt.json"
    receipt = load_object(receipt_path, label="failed candidate materialization receipt")
    stderr_path = root / "pilot-v7/offline-runtime-preflight/offline-preflight.stderr"
    provider_entry = load_object(
        root / "pilot-v7/provider-entry.json", label="prior provider entry"
    )
    _require_provider_contract(
        state,
        expected=PACKAGE_TRANSITION_PROVIDER_CONTRACT,
        label="failed candidate state",
    )
    _require_provider_contract(
        provider_entry,
        expected=PACKAGE_TRANSITION_PROVIDER_CONTRACT,
        label="failed candidate provider entry",
    )
    image_id = receipt.get("image_id")
    if (
        state.get("plan_id") != PACKAGE_TRANSITION_PROVIDER_CONTRACT.plan_id
        or state.get("empirical_attempts_entered") != []
        or state.get("attempts_completed") != []
        or receipt.get("qualification_id") != FAILED_CANDIDATE_QUALIFICATION_ID
        or receipt.get("build_count") != 1
        or not isinstance(image_id, str)
        or re.fullmatch(r"sha256:[a-f0-9]{64}", image_id) is None
        or receipt.get("build_context_exclusions_sha256")
        != file_sha256(qualification_root / "build-context-exclusions.json")
        or file_sha256(stderr_path) != FAILED_CANDIDATE_OFFLINE_STDERR_SHA256
        or "ModuleNotFoundError: No module named 'yaml'"
        not in stderr_path.read_text(encoding="utf-8")
        or (root / "pilot-v7/frozen-run-manifest.json").exists()
        or (root / "pilot-v7/preflight.json").exists()
        or (root / "pilot-v7/model-metadata-preflight").exists()
        or (root / "pilot-v7/browser-preflight").exists()
    ):
        raise T09HostError("failed candidate prefix is not the exact safe offline failure")
    if require_image_present and (
        image_id_if_present(
            docker_prefix(),
            cast(str, PACKAGE_TRANSITION_PROVIDER_CONTRACT.replacement_image_tag),
        )
        != image_id
        or image_id_if_present(docker_prefix(), image_id) != image_id
    ):
        raise T09HostError("failed candidate image is unavailable or tag-drifted")
    retained = _retained_tree_manifest(root, label="failed candidate prefix")
    return {
        "root_name": root.name,
        "qualification_id": FAILED_CANDIDATE_QUALIFICATION_ID,
        "classification": "preentry-offline-control-interpreter-missing-pyyaml",
        "empirical_entry_crossed": False,
        "model_metadata_requests": 0,
        "task_model_requests": 0,
        "task_browser_actions": 0,
        "replacement_image_built": True,
        "replacement_image_id": image_id,
        "materialization_receipt_sha256": file_sha256(receipt_path),
        "offline_failure_stderr_sha256": file_sha256(stderr_path),
        "previous_package_transition_receipt_sha256": provider_entry.get(
            "package_transition_receipt_sha256"
        ),
        **retained,
    }


def _git_transition_fields(
    repository: Path,
    *,
    to_package_commit: str,
) -> dict[str, object]:
    ancestry = subprocess.run(
        [
            "git",
            "-C",
            str(repository),
            "merge-base",
            "--is-ancestor",
            PACKAGE_TRANSITION_FROM_COMMIT,
            to_package_commit,
        ],
        env=safe_environment(),
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=False,
        timeout=30,
    )
    if ancestry.returncode != 0:
        raise T09HostError("transition package is not a descendant of the launched package")
    changed_raw = output(
        [
            "git",
            "-C",
            str(repository),
            "diff",
            "--name-only",
            "--diff-filter=ACMRT",
            PACKAGE_TRANSITION_FROM_COMMIT,
            to_package_commit,
        ]
    )
    changed_paths = sorted(line for line in changed_raw.splitlines() if line)
    if (
        not changed_paths
        or not set(changed_paths).issubset(PACKAGE_TRANSITION_ALLOWED_PATHS)
        or "containers/sira-smoke/pragmatic/t09_remote_runner.py" not in changed_paths
        or "src/giclab/harness/t09_sira_pilot.py" not in changed_paths
    ):
        raise T09HostError("package transition changed a non-allowlisted or incomplete surface")
    deleted = output(
        [
            "git",
            "-C",
            str(repository),
            "diff",
            "--name-only",
            "--diff-filter=D",
            PACKAGE_TRANSITION_FROM_COMMIT,
            to_package_commit,
        ]
    )
    if deleted:
        raise T09HostError("package transition deleted a tracked file")
    diff = subprocess.run(
        [
            "git",
            "-C",
            str(repository),
            "diff",
            "--binary",
            PACKAGE_TRANSITION_FROM_COMMIT,
            to_package_commit,
        ],
        env=safe_environment(),
        stdin=subprocess.DEVNULL,
        capture_output=True,
        check=True,
        timeout=60,
    ).stdout
    return {
        "from_package_commit": PACKAGE_TRANSITION_FROM_COMMIT,
        "to_package_commit": to_package_commit,
        "from_package_is_ancestor": True,
        "to_package_tree": output(
            ["git", "-C", str(repository), "rev-parse", f"{to_package_commit}^{{tree}}"]
        ),
        "changed_paths": changed_paths,
        "changed_paths_sha256": canonical_sha256(changed_paths),
        "binary_diff_sha256": hashlib.sha256(diff).hexdigest(),
    }


def _validate_previous_package_transition_receipt(
    path: Path,
    *,
    repository: Path,
    entry_receipt: Path,
    entry_source_root: Path,
    prior_artifact_root: Path,
) -> dict[str, object]:
    provider_contract = _provider_contract_from_receipt(
        entry_receipt,
        label="previous provider entry receipt",
    )
    if provider_contract != PACKAGE_TRANSITION_PROVIDER_CONTRACT:
        raise T09HostError("previous package transition belongs to another campaign")
    try:
        load_provider_plan(repository, provider_contract)
    except T09ProviderContractError as exc:
        raise T09HostError("previous package transition plan bytes drifted") from exc
    plan_sha256 = provider_contract.expected_plan_sha256
    try:
        entry = validate_entry_receipt_source_bound(
            entry_receipt.resolve(strict=True),
            entry_source_root.resolve(strict=True),
            contract=provider_contract,
            package_commit=PACKAGE_TRANSITION_FROM_COMMIT,
            plan_sha256=plan_sha256,
        )
    except T09ProviderError as exc:
        raise T09HostError("previous transition entry receipt is not source-bound") from exc
    prior_failure = _prior_qualification_failure_manifest(prior_artifact_root.resolve(strict=True))
    expected: dict[str, object] = {
        "schema_version": "0.1.0",
        "receipt_type": "t09-pragmatic-preentry-package-transition",
        "plan_id": provider_contract.plan_id,
        "host_run_id": provider_contract.host_run_id,
        **_git_transition_fields(
            repository,
            to_package_commit=PREVIOUS_PACKAGE_TRANSITION_COMMIT,
        ),
        "plan_sha256": plan_sha256,
        "provider_entry_receipt_sha256": file_sha256(entry_receipt),
        "provider_entry_source_manifest_sha256": entry.get("source_manifest_sha256"),
        "owned_instance_identity_sha256": entry.get("owned_instance_identity_sha256"),
        "lambda_started_at_epoch": entry.get("lambda_started_at_epoch"),
        "prior_failure": prior_failure,
        "prior_failure_sha256": canonical_sha256(prior_failure),
        "prior_qualification_id": CONTEXT_FAILURE_QUALIFICATION_ID,
        "next_qualification_id": FAILED_CANDIDATE_QUALIFICATION_ID,
        "prior_replacement_image_absent": True,
        "next_replacement_image_absent": True,
        "empirical_entry_crossed": False,
        "scientific_contract_changed": False,
        "provider_launch_reused": True,
        "additional_provider_launches": 0,
    }
    observed = load_object(path.resolve(strict=True), label="previous package transition receipt")
    created = observed.pop("created_at_epoch", None)
    metadata = path.stat(follow_symlinks=False)
    lambda_started = expected.get("lambda_started_at_epoch")
    if (
        observed != expected
        or not isinstance(created, (int, float))
        or isinstance(created, bool)
        or not isinstance(lambda_started, (int, float))
        or isinstance(lambda_started, bool)
        or not float(lambda_started) <= float(created) <= time.time()
        or not stat.S_ISREG(metadata.st_mode)
        or metadata.st_nlink != 1
        or stat.S_IMODE(metadata.st_mode) != 0o600
    ):
        raise T09HostError("previous package transition receipt drifted")
    return {**expected, "created_at_epoch": created, "receipt_sha256": file_sha256(path)}


def _package_transition_projection(
    *,
    repository: Path,
    package_commit: str,
    entry_receipt: Path,
    entry_source_root: Path,
    prior_artifact_root: Path,
    failed_candidate_root: Path,
    previous_transition_receipt: Path,
    require_candidate_present: bool,
) -> dict[str, object]:
    verify_package(
        repository,
        package_commit,
        contract=PACKAGE_TRANSITION_PROVIDER_CONTRACT,
    )
    provider_contract = _provider_contract_from_receipt(
        entry_receipt,
        label="package transition provider entry receipt",
    )
    if provider_contract != PACKAGE_TRANSITION_PROVIDER_CONTRACT:
        raise T09HostError("package transition belongs to another campaign")
    try:
        load_provider_plan(repository, provider_contract)
    except T09ProviderContractError as exc:
        raise T09HostError("package transition plan bytes drifted") from exc
    plan_sha256 = provider_contract.expected_plan_sha256
    try:
        entry = validate_entry_receipt_source_bound(
            entry_receipt.resolve(strict=True),
            entry_source_root.resolve(strict=True),
            contract=provider_contract,
            package_commit=PACKAGE_TRANSITION_FROM_COMMIT,
            plan_sha256=plan_sha256,
        )
    except T09ProviderError as exc:
        raise T09HostError("package transition entry receipt is not source-bound") from exc
    ancestry = subprocess.run(
        [
            "git",
            "-C",
            str(repository),
            "merge-base",
            "--is-ancestor",
            PACKAGE_TRANSITION_FROM_COMMIT,
            package_commit,
        ],
        env=safe_environment(),
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=False,
        timeout=30,
    )
    if ancestry.returncode != 0:
        raise T09HostError("replacement package is not a clean descendant of the launched package")
    failure = _prior_qualification_failure_manifest(prior_artifact_root.resolve(strict=True))
    previous_transition = _validate_previous_package_transition_receipt(
        previous_transition_receipt,
        repository=repository,
        entry_receipt=entry_receipt,
        entry_source_root=entry_source_root,
        prior_artifact_root=prior_artifact_root,
    )
    failed_candidate = _failed_candidate_manifest(
        failed_candidate_root.resolve(strict=True),
        require_image_present=require_candidate_present,
    )
    if (
        failed_candidate.get("previous_package_transition_receipt_sha256")
        != previous_transition.get("receipt_sha256")
        or image_id_if_present(docker_prefix(), PRIOR_REPLACEMENT_IMAGE_TAG) is not None
    ):
        raise T09HostError("failed candidate does not continue the exact prior transition")
    return {
        "schema_version": "0.1.0",
        "receipt_type": "t09-pragmatic-preentry-package-transition",
        "plan_id": provider_contract.plan_id,
        "host_run_id": provider_contract.host_run_id,
        **_git_transition_fields(repository, to_package_commit=package_commit),
        "plan_sha256": plan_sha256,
        "provider_entry_receipt_sha256": file_sha256(entry_receipt),
        "provider_entry_source_manifest_sha256": entry.get("source_manifest_sha256"),
        "owned_instance_identity_sha256": entry.get("owned_instance_identity_sha256"),
        "lambda_started_at_epoch": entry.get("lambda_started_at_epoch"),
        "prior_failure": failure,
        "prior_failure_sha256": canonical_sha256(failure),
        "failed_candidate": failed_candidate,
        "failed_candidate_sha256": canonical_sha256(failed_candidate),
        "previous_package_transition_receipt_sha256": previous_transition["receipt_sha256"],
        "prior_qualification_id": FAILED_CANDIDATE_QUALIFICATION_ID,
        "next_qualification_id": PACKAGE_TRANSITION_QUALIFICATION_ID,
        "context_failure_replacement_image_absent": True,
        "failed_candidate_replacement_image_present": True,
        "replacement_image_id": failed_candidate["replacement_image_id"],
        "replacement_image_reused_without_rebuild": True,
        "additional_replacement_image_builds": 0,
        "empirical_entry_crossed": False,
        "scientific_contract_changed": False,
        "provider_launch_reused": True,
        "additional_provider_launches": 0,
    }


def write_package_transition_receipt(args: argparse.Namespace) -> None:
    projection = _package_transition_projection(
        repository=args.repository.resolve(strict=True),
        package_commit=args.package_commit,
        entry_receipt=args.dynamic_receipt.resolve(strict=True),
        entry_source_root=args.dynamic_source_root.resolve(strict=True),
        prior_artifact_root=args.prior_artifact_root.resolve(strict=True),
        failed_candidate_root=args.failed_candidate_root.resolve(strict=True),
        previous_transition_receipt=args.previous_package_transition_receipt.resolve(strict=True),
        require_candidate_present=True,
    )
    write_exclusive(
        args.output.resolve(strict=False),
        {**projection, "created_at_epoch": time.time()},
    )


def validate_package_transition_receipt(
    path: Path,
    *,
    repository: Path,
    package_commit: str,
    entry_receipt: Path,
    entry_source_root: Path,
    prior_artifact_root: Path,
    failed_candidate_root: Path,
    previous_transition_receipt: Path,
    require_fresh: bool,
    require_candidate_present: bool,
) -> dict[str, object]:
    observed = load_object(path.resolve(strict=True), label="package transition receipt")
    created = observed.pop("created_at_epoch", None)
    expected = _package_transition_projection(
        repository=repository.resolve(strict=True),
        package_commit=package_commit,
        entry_receipt=entry_receipt.resolve(strict=True),
        entry_source_root=entry_source_root.resolve(strict=True),
        prior_artifact_root=prior_artifact_root.resolve(strict=True),
        failed_candidate_root=failed_candidate_root.resolve(strict=True),
        previous_transition_receipt=previous_transition_receipt.resolve(strict=True),
        require_candidate_present=require_candidate_present,
    )
    metadata = path.stat(follow_symlinks=False)
    lambda_started = expected.get("lambda_started_at_epoch")
    if (
        observed != expected
        or not isinstance(created, (int, float))
        or isinstance(created, bool)
        or not isinstance(lambda_started, (int, float))
        or isinstance(lambda_started, bool)
        or not float(lambda_started) <= float(created) <= time.time()
        or (require_fresh and not 0 <= time.time() - float(created) <= 1_800)
        or not stat.S_ISREG(metadata.st_mode)
        or metadata.st_nlink != 1
        or stat.S_IMODE(metadata.st_mode) != 0o600
    ):
        raise T09HostError("package transition receipt drifted or is stale")
    return {**expected, "created_at_epoch": created, "receipt_sha256": file_sha256(path)}


def validate_dynamic_receipt(
    path: Path,
    *,
    expected_package_commit: str,
    repository_root: Path | None = None,
    source_root: Path | None = None,
) -> dict[str, object]:
    """Reconstruct the receipt from retained allowlisted provider projections."""

    if repository_root is None or source_root is None:
        raise T09HostError("provider entry source bundle is required")
    repository = repository_root.resolve(strict=True)
    source = source_root.resolve(strict=True)
    provider_contract = _provider_contract_from_receipt(
        path,
        label="provider entry receipt",
    )
    plan = repository / provider_contract.provider_profile_path
    provider_entry_package_commit = expected_package_commit
    package_transition: dict[str, object] | None = None
    try:
        value = validate_entry_receipt_source_bound(
            path.resolve(strict=True),
            source,
            contract=provider_contract,
            package_commit=expected_package_commit,
            plan_sha256=file_sha256(plan),
        )
    except T09ProviderError as current_error:
        observed_entry = load_object(path.resolve(strict=True), label="provider entry receipt")
        observed_package_commit = observed_entry.get("package_commit")
        observed_plan_sha256 = observed_entry.get("plan_sha256")
        if (
            observed_package_commit == expected_package_commit
            and observed_plan_sha256 == file_sha256(plan)
        ):
            raise T09HostError("provider entry receipt is not source-bound") from current_error
        generic_transition_valid = False
        if (
            isinstance(observed_package_commit, str)
            and re.fullmatch(r"[a-f0-9]{40}", observed_package_commit) is not None
            and observed_package_commit != RETRY4_ACTIVE_SLOT2_ENTRY_PACKAGE_COMMIT
            and isinstance(observed_plan_sha256, str)
            and _HEX64.fullmatch(observed_plan_sha256) is not None
        ):
            try:
                value = validate_entry_receipt_source_bound(
                    path.resolve(strict=True),
                    source,
                    contract=provider_contract,
                    package_commit=observed_package_commit,
                    plan_sha256=observed_plan_sha256,
                )
                package_transition = autonomous_preflight_package_transition(
                    repository,
                    contract=provider_contract,
                    from_package_commit=observed_package_commit,
                    to_package_commit=expected_package_commit,
                )
            except T09ProviderError:
                pass
            else:
                provider_entry_package_commit = observed_package_commit
                generic_transition_valid = True
        if not generic_transition_valid:
            if provider_contract is not V6_PROVIDER_CONTRACT:
                raise T09HostError(
                    "provider entry receipt has no transition for its selected version"
                ) from current_error
            try:
                value = validate_entry_receipt_source_bound(
                    path.resolve(strict=True),
                    source,
                    contract=provider_contract,
                    package_commit=RETRY4_ACTIVE_SLOT2_ENTRY_PACKAGE_COMMIT,
                    plan_sha256=file_sha256(plan),
                )
                package_transition = retry4_active_slot2_entry_transition(
                    repository, expected_package_commit
                )
            except T09ProviderError:
                raise T09HostError("provider entry receipt is not source-bound") from current_error
            provider_entry_package_commit = RETRY4_ACTIVE_SLOT2_ENTRY_PACKAGE_COMMIT
            if (
                value.get("launch_slot") != 2
                or value.get("launch_count") != 2
                or package_transition.get("from_package_commit")
                != RETRY4_ACTIVE_SLOT2_ENTRY_PACKAGE_COMMIT
                or package_transition.get("to_package_commit") != expected_package_commit
            ):
                raise T09HostError(
                    "active slot-2 provider package transition drifted"
                ) from current_error
    captured = value.get("captured_at_epoch")
    provider_lifecycle = load_campaign_lifecycle(repository, contract=provider_contract)
    entry_freshness_seconds = (
        provider_lifecycle.preflight_wall_seconds or provider_lifecycle.wall_seconds
    )
    if (
        not isinstance(captured, (int, float))
        or isinstance(captured, bool)
        or not 0 <= time.time() - float(captured) <= entry_freshness_seconds
    ):
        raise T09HostError("provider entry receipt is stale")
    encoded = json.dumps(value, sort_keys=True)
    if (
        _CREDENTIAL_TEXT.search(encoded)
        or _JUPYTER_URL.search(encoded)
        or _private_network_values(encoded)
        or _sensitive_json_paths(value)
    ):
        raise T09HostError("provider entry receipt retained a prohibited value")
    result = dict(value)
    result["provider_preflight_started_at_epoch"] = value.get("owned_lambda_started_at_epoch")
    result["receipt_sha256"] = file_sha256(path)
    result["provider_entry_package_commit"] = provider_entry_package_commit
    result["provider_package_transition"] = package_transition
    result["provider_package_transition_sha256"] = (
        canonical_sha256(package_transition) if package_transition is not None else None
    )
    return result


def validate_provider_closeout_receipt(
    path: Path,
    *,
    expected_lambda_started_at_epoch: float,
    expected_owned_instance_identity_sha256: str,
    expected_entry_receipt_sha256: str,
    expected_package_commit: str,
    repository_root: Path | None = None,
    source_root: Path | None = None,
    entry_receipt_path: Path | None = None,
    entry_source_root: Path | None = None,
) -> dict[str, object]:
    """Reconstruct closeout from exact-target provider projections and raw hashes."""

    if any(
        item is None
        for item in (repository_root, source_root, entry_receipt_path, entry_source_root)
    ):
        raise T09HostError("provider closeout source bundles are required")
    assert repository_root is not None
    assert source_root is not None
    assert entry_receipt_path is not None
    assert entry_source_root is not None
    repository = repository_root.resolve(strict=True)
    provider_contract = _provider_contract_from_receipt(
        entry_receipt_path,
        label="provider entry receipt",
    )
    try:
        value = validate_source_bound_closeout(
            path.resolve(strict=True),
            source_root.resolve(strict=True),
            contract=provider_contract,
            entry_receipt_path=entry_receipt_path.resolve(strict=True),
            entry_source_root=entry_source_root.resolve(strict=True),
            package_commit=expected_package_commit,
            plan_sha256=file_sha256(repository / provider_contract.provider_profile_path),
            lifecycle=load_campaign_lifecycle(repository, contract=provider_contract),
        )
    except T09ProviderError as exc:
        raise T09HostError("provider closeout receipt is not source-bound") from exc
    timeline = [
        value.get("lambda_started_at_epoch"),
        value.get("termination_started_at_epoch"),
        value.get("terminal_observed_at_epoch"),
        value.get("zero_instance_observed_at_epoch"),
        value.get("captured_at_epoch"),
    ]
    if any(not isinstance(item, (int, float)) or isinstance(item, bool) for item in timeline):
        raise T09HostError("provider closeout chronology is malformed")
    numeric_timeline = [float(cast(int | float, item)) for item in timeline]
    if (
        numeric_timeline != sorted(numeric_timeline)
        or abs(numeric_timeline[0] - expected_lambda_started_at_epoch) > 1.0
        or value.get("owned_instance_identity_sha256") != expected_owned_instance_identity_sha256
        or value.get("termination_target_identity_sha256")
        != expected_owned_instance_identity_sha256
        or value.get("entry_receipt_sha256") != expected_entry_receipt_sha256
        or not 0 <= time.time() - numeric_timeline[-1] <= 1_800
    ):
        raise T09HostError("provider closeout identity or chronology drifted")
    encoded = json.dumps(value, sort_keys=True)
    if (
        _CREDENTIAL_TEXT.search(encoded)
        or _JUPYTER_URL.search(encoded)
        or _private_network_values(encoded)
        or _sensitive_json_paths(value)
    ):
        raise T09HostError("provider closeout receipt retained a prohibited value")
    result = dict(value)
    result["receipt_sha256"] = file_sha256(path)
    return result


def sanitized_dynamic_receipt(_path: Path, value: dict[str, object]) -> dict[str, object]:
    """Return only the already-sanitized validator projection."""

    return dict(value)


def _contract_control_root_name(contract: T09ProviderContract) -> str:
    return contract.control_root_name


def _contract_archive_id(contract: T09ProviderContract) -> str:
    return contract.evidence_archive_id


def _contract_stage_id(contract: T09ProviderContract) -> str:
    return contract.evidence_stage_id


def _runtime_provider_contract(root: Path) -> T09ProviderContract:
    """Resolve exactly one lifecycle contract from its typed control root."""

    state_paths = sorted(
        {
            root / retained.control_root_name / "pilot-state.json"
            for retained in PROVIDER_CONTRACTS.values()
            if retained.execution_contract_path is not None
        }
    )
    present = [path for path in state_paths if os.path.lexists(path)]
    if len(present) != 1:
        raise T09HostError("pilot state must select exactly one autonomous contract root")
    selected = _provider_contract_from_document(
        load_object(present[0], label="pilot state"),
        label="pilot state",
    )
    if present[0].parent.name != selected.control_root_name:
        raise T09HostError("pilot state contract does not match its control root")
    return selected


def _pilot_root(root: Path, contract: T09ProviderContract | None = None) -> Path:
    selected = _runtime_provider_contract(root) if contract is None else contract
    return root / _contract_control_root_name(selected)


def _runtime_budget_state(
    root: Path,
    *,
    contract: T09ProviderContract | None = None,
) -> dict[str, Any]:
    if contract is not None:
        return load_object(_pilot_root(root, contract) / "pilot-state.json", label="pilot state")
    return load_object(_pilot_root(root) / "pilot-state.json", label="pilot state")


def _provider_contract_for_execution(
    execution_contract: PilotExecutionContract,
) -> T09ProviderContract:
    """Resolve the provider namespace bound by one loaded execution contract."""

    try:
        return provider_contract_for_plan_id(execution_contract.plan_id)
    except T09ProviderContractError as exc:
        raise T09HostError("execution contract names an unsupported provider plan") from exc


def _received_export_ack_path(root: Path, run_id: str) -> Path:
    contract = _runtime_provider_contract(root)
    if run_id not in contract.run_ids:
        raise T09HostError("export acknowledgement run identity is unknown")
    return _pilot_root(root, contract) / "received-export-acknowledgements" / f"{run_id}.json"


def _attempt_export_completion_path(root: Path, run_id: str) -> Path:
    contract = _runtime_provider_contract(root)
    if run_id not in contract.run_ids:
        raise T09HostError("attempt export completion run identity is unknown")
    return (
        _pilot_root(root, contract)
        / "attempt-export-completions"
        / f"{run_id}-export-completion.json"
    )


_ATTEMPT_EXPORT_COMPLETION_KEYS: Final = {
    "schema_version",
    "plan_id",
    "host_run_id",
    "run_id",
    "package_commit",
    "archive_bytes",
    "archive_sha256",
    "manifest_sha256",
    "frozen_run_manifest_sha256",
    "replacement_image_id",
    "provider_entry_receipt_sha256",
    "owned_instance_identity_sha256",
    "lambda_started_at_epoch",
    "export_completed_at_epoch",
}

_ATTEMPT_EXPORT_ACKNOWLEDGEMENT_KEYS: Final = {
    "schema_version",
    "plan_id",
    "host_run_id",
    "run_id",
    "package_commit",
    "archive_path",
    "archive_bytes",
    "archive_sha256",
    "manifest_sha256",
    "frozen_run_manifest_sha256",
    "replacement_image_id",
    "evidence_authority",
    "empirical_entry_crossed",
    "provider_entry_receipt_sha256",
    "owned_instance_identity_sha256",
    "lambda_started_at_epoch",
    "export_completion_receipt_sha256",
    "export_completed_at_epoch",
    "verified_at_epoch",
    "maximum_cross_host_clock_skew_seconds",
}


def _validate_attempt_export_completion(
    value: dict[str, Any],
    *,
    run_id: str,
    package_commit: str,
    archive_bytes: int,
    archive_sha256: str,
    manifest_sha256: str,
    frozen_run_manifest_sha256: str,
    replacement_image_id: str,
    provider_entry_receipt_sha256: str,
    owned_instance_identity_sha256: str,
    lambda_started_at_epoch: float,
    contract: T09ProviderContract,
) -> float:
    """Validate the durable host receipt written only after the export stream closes."""

    _require_contract_run_id(contract, run_id, label="attempt export completion")
    completed = value.get("export_completed_at_epoch")
    if (
        set(value) != _ATTEMPT_EXPORT_COMPLETION_KEYS
        or value.get("schema_version") != "0.1.0"
        or value.get("plan_id") != contract.plan_id
        or value.get("host_run_id") != contract.host_run_id
        or value.get("run_id") != run_id
        or value.get("package_commit") != package_commit
        or value.get("archive_bytes") != archive_bytes
        or value.get("archive_sha256") != archive_sha256
        or value.get("manifest_sha256") != manifest_sha256
        or value.get("frozen_run_manifest_sha256") != frozen_run_manifest_sha256
        or value.get("replacement_image_id") != replacement_image_id
        or value.get("provider_entry_receipt_sha256") != provider_entry_receipt_sha256
        or value.get("owned_instance_identity_sha256") != owned_instance_identity_sha256
        or value.get("lambda_started_at_epoch") != lambda_started_at_epoch
        or not isinstance(completed, (int, float))
        or isinstance(completed, bool)
        or float(completed) < lambda_started_at_epoch
        or float(completed) > time.time() + EVIDENCE_CHRONOLOGY_CLOCK_SKEW_SECONDS
    ):
        raise T09HostError("attempt export completion receipt drifted")
    return float(completed)


def _require_pretermination_evidence_chronology(
    *,
    lambda_started_at_epoch: float,
    export_completed_at_epoch: float,
    verified_at_epoch: float,
    termination_started_at_epoch: float,
    label: str,
) -> None:
    """Prove transfer completion and off-host verification preceded termination."""

    timeline = (
        lambda_started_at_epoch,
        export_completed_at_epoch,
        verified_at_epoch,
        termination_started_at_epoch,
    )
    if (
        not all(math.isfinite(value) for value in timeline)
        or lambda_started_at_epoch
        > export_completed_at_epoch + EVIDENCE_CHRONOLOGY_CLOCK_SKEW_SECONDS
        or export_completed_at_epoch > verified_at_epoch + EVIDENCE_CHRONOLOGY_CLOCK_SKEW_SECONDS
        or verified_at_epoch > termination_started_at_epoch
    ):
        raise T09HostError(f"{label} was not completed and verified before termination")


def _validate_attempt_export_acknowledgement(
    *,
    acknowledgement: dict[str, Any],
    acknowledgement_sha256: str,
    completion: dict[str, Any],
    completion_sha256: str,
    run_id: str,
    package_commit: str,
    evidence_authority: str,
    empirical_entry_crossed: bool,
    frozen_run_manifest_sha256: str,
    replacement_image_id: str,
    provider_entry_receipt_sha256: str,
    owned_instance_identity_sha256: str,
    lambda_started_at_epoch: float,
    archive: Path | None,
    contract: T09ProviderContract,
) -> dict[str, object]:
    """Validate one direct-export acknowledgement without inventing a remote copy.

    Raw authorities retain their bounded archive on the host and rehash it here.
    Essential authorities are intentionally stream-only; their exact archive
    identity is instead bound by the durable completion receipt and the
    independently generated verifier acknowledgement.
    """

    _require_contract_run_id(contract, run_id, label="attempt export acknowledgement")
    archive_bytes = acknowledgement.get("archive_bytes")
    archive_sha256 = acknowledgement.get("archive_sha256")
    manifest_sha256 = acknowledgement.get("manifest_sha256")
    verified_at = acknowledgement.get("verified_at_epoch")
    if (
        set(acknowledgement) != _ATTEMPT_EXPORT_ACKNOWLEDGEMENT_KEYS
        or acknowledgement.get("schema_version") != "0.1.0"
        or acknowledgement.get("plan_id") != contract.plan_id
        or acknowledgement.get("host_run_id") != contract.host_run_id
        or acknowledgement.get("run_id") != run_id
        or acknowledgement.get("package_commit") != package_commit
        or acknowledgement.get("archive_path") != f"{run_id}.tar.gz"
        or type(archive_bytes) is not int
        or not 0 < archive_bytes <= MAX_ATTEMPT_EXPORT_BYTES
        or not isinstance(archive_sha256, str)
        or _HEX64.fullmatch(archive_sha256) is None
        or not isinstance(manifest_sha256, str)
        or _HEX64.fullmatch(manifest_sha256) is None
        or acknowledgement.get("frozen_run_manifest_sha256") != frozen_run_manifest_sha256
        or acknowledgement.get("replacement_image_id") != replacement_image_id
        or acknowledgement.get("evidence_authority") != evidence_authority
        or acknowledgement.get("empirical_entry_crossed") is not empirical_entry_crossed
        or acknowledgement.get("provider_entry_receipt_sha256") != provider_entry_receipt_sha256
        or acknowledgement.get("owned_instance_identity_sha256") != owned_instance_identity_sha256
        or acknowledgement.get("lambda_started_at_epoch") != lambda_started_at_epoch
        or acknowledgement.get("export_completion_receipt_sha256") != completion_sha256
        or acknowledgement.get("maximum_cross_host_clock_skew_seconds")
        != EVIDENCE_CHRONOLOGY_CLOCK_SKEW_SECONDS
        or not isinstance(verified_at, (int, float))
        or isinstance(verified_at, bool)
        or not math.isfinite(float(verified_at))
        or float(verified_at) > time.time() + EVIDENCE_CHRONOLOGY_CLOCK_SKEW_SECONDS
    ):
        raise T09HostError(
            "prior attempt archive lacks its exact off-host verification acknowledgement"
        )
    if archive is not None and (
        not archive.is_file()
        or archive.is_symlink()
        or archive.stat().st_size != archive_bytes
        or file_sha256(archive) != archive_sha256
    ):
        raise T09HostError("retained raw attempt export archive drifted")
    completed_at = _validate_attempt_export_completion(
        completion,
        run_id=run_id,
        package_commit=package_commit,
        archive_bytes=archive_bytes,
        archive_sha256=archive_sha256,
        manifest_sha256=manifest_sha256,
        frozen_run_manifest_sha256=frozen_run_manifest_sha256,
        replacement_image_id=replacement_image_id,
        provider_entry_receipt_sha256=provider_entry_receipt_sha256,
        owned_instance_identity_sha256=owned_instance_identity_sha256,
        lambda_started_at_epoch=lambda_started_at_epoch,
        contract=contract,
    )
    if (
        acknowledgement.get("export_completed_at_epoch") != completed_at
        or completed_at > float(verified_at) + EVIDENCE_CHRONOLOGY_CLOCK_SKEW_SECONDS
    ):
        raise T09HostError("attempt export acknowledgement chronology drifted")
    return {
        "run_id": run_id,
        "evidence_authority": evidence_authority,
        "empirical_entry_crossed": empirical_entry_crossed,
        "archive_bytes": archive_bytes,
        "archive_sha256": archive_sha256,
        "manifest_sha256": manifest_sha256,
        "export_completion_receipt_sha256": completion_sha256,
        "acknowledgement_receipt_sha256": acknowledgement_sha256,
        "export_completed_at_epoch": completed_at,
        "verified_at_epoch": float(verified_at),
        "maximum_cross_host_clock_skew_seconds": EVIDENCE_CHRONOLOGY_CLOCK_SKEW_SECONDS,
    }


def _load_cleanup_evidence_object(path: Path, *, label: str) -> dict[str, Any]:
    """Load one cleanup control object only through its immutable file identity."""

    try:
        metadata = path.lstat()
    except FileNotFoundError as exc:
        raise CleanupExportEvidenceError(f"{label} is absent") from exc
    if (
        path.is_symlink()
        or not stat.S_ISREG(metadata.st_mode)
        or metadata.st_uid != os.getuid()
        or metadata.st_nlink != 1
        or stat.S_IMODE(metadata.st_mode) != 0o600
        or not 0 < metadata.st_size <= MAX_PRIVACY_JSON_BYTES
    ):
        raise CleanupExportEvidenceError(f"{label} metadata is unsafe")
    try:
        return load_object(path, label=label)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError, T09HostError) as exc:
        raise CleanupExportEvidenceError(f"{label} is malformed") from exc


def _cleanup_evidence_members(
    directory: Path,
    *,
    expected_names: frozenset[str],
    label: str,
) -> tuple[Path, ...]:
    """Return exact immutable members from one optional cleanup evidence directory."""

    if not os.path.lexists(directory):
        return ()
    metadata = directory.lstat()
    if (
        directory.is_symlink()
        or not stat.S_ISDIR(metadata.st_mode)
        or metadata.st_uid != os.getuid()
        or stat.S_IMODE(metadata.st_mode) != 0o700
    ):
        raise CleanupExportEvidenceError(f"{label} directory is unsafe")
    members = tuple(sorted(directory.iterdir(), key=lambda path: path.name))
    if any(path.name not in expected_names for path in members):
        raise CleanupExportEvidenceError(f"{label} contains an unknown member")
    for path in members:
        member = path.lstat()
        if (
            path.is_symlink()
            or not stat.S_ISREG(member.st_mode)
            or member.st_uid != os.getuid()
            or member.st_nlink != 1
            or stat.S_IMODE(member.st_mode) != 0o600
        ):
            raise CleanupExportEvidenceError(f"{label} member metadata is unsafe")
    return members


def _cleanup_attempt_specific_evidence(
    root: Path,
    *,
    repository: Path,
    contract: T09ProviderContract,
) -> tuple[int, int]:
    """Count exact condition-owned roots and start intents without inferring from prose."""

    command_path = _contract_paths_for(repository, contract)["commands"]
    command_metadata = command_path.stat(follow_symlinks=False)
    if command_path.is_symlink() or not stat.S_ISREG(command_metadata.st_mode):
        raise CleanupExportEvidenceError("cleanup command manifest set is unsafe")
    command_document = load_object(command_path, label="cleanup command manifest set")
    attempt_state_count = 0
    start_intent_count = 0
    resolved_root = root.resolve(strict=True)
    for run_id in contract.run_ids:
        condition_manifest = _manifest_for_contract(command_document, run_id, contract)
        attempt_root = root / manifest_output_root(condition_manifest)
        if not os.path.lexists(attempt_root):
            continue
        metadata = attempt_root.lstat()
        if attempt_root.is_symlink() or not stat.S_ISDIR(metadata.st_mode):
            raise CleanupExportEvidenceError("condition attempt root is unsafe")
        try:
            attempt_root.resolve(strict=True).relative_to(resolved_root)
        except (FileNotFoundError, ValueError) as exc:
            raise CleanupExportEvidenceError(
                "condition attempt root escaped artifact authority"
            ) from exc
        attempt_state_count += 1
        intent_path = (
            attempt_root / "raw" / CONDITION_SUPERVISOR_DIRNAME / "condition-start-intent.json"
        )
        if os.path.lexists(intent_path):
            _load_cleanup_evidence_object(intent_path, label="condition start intent")
            start_intent_count += 1
    return attempt_state_count, start_intent_count


def derive_cleanup_export_phase(
    root: Path,
    *,
    repository: Path,
    state: dict[str, Any],
    package_commit: str,
    cleanup_journal_state: EarlyCleanupState,
    retained_chronology: object | None,
    retained_pending: object | None,
) -> CleanupExportPhaseEvidence:
    """Derive cleanup export obligations from durable evidence before manifest loading."""

    contract = _provider_contract_from_document(state, label="cleanup pilot state")
    _require_supported_provider_runner(contract, label="cleanup export phase")
    control_root = _pilot_root(root, contract)
    entry = _load_cleanup_evidence_object(
        control_root / "provider-entry.json",
        label="cleanup provider entry",
    )
    _require_provider_contract(entry, expected=contract, label="cleanup provider entry")
    if (
        cleanup_journal_state.plan_id != contract.plan_id
        or cleanup_journal_state.host_run_id != contract.host_run_id
        or cleanup_journal_state.package_commit != package_commit
        or cleanup_journal_state.plan_sha256 != contract.expected_plan_sha256
    ):
        raise CleanupExportEvidenceError("cleanup journal and selected provider contract disagree")

    typed_list_fields = (
        "empirical_attempts_entered",
        "raw_attempts_complete",
        "attempts_completed",
        "nonempirical_infrastructure_attempts_consumed",
    )
    values = [state.get(field) for field in typed_list_fields]
    if not all(
        isinstance(value, list) and all(isinstance(item, str) for item in value) for value in values
    ):
        raise CleanupExportEvidenceError("cleanup attempt phase state is malformed")
    entered, raw_complete, completed, nonempirical = cast(
        tuple[list[str], list[str], list[str], list[str]],
        tuple(values),
    )
    reservation = state.get("condition_start_reservation")
    essential_seals = state.get("essential_failure_seals")
    raw_bindings = state.get("raw_attempt_bindings")
    finalizations = state.get("attempt_finalizations")
    finalization_history = state.get("attempt_finalization_history")
    release_bindings = state.get("supervised_release_bindings")
    reclassifications = state.get("unreleased_supervised_release_reclassifications")
    if (reservation is not None and not isinstance(reservation, dict)) or not all(
        isinstance(value, dict)
        for value in (
            essential_seals,
            raw_bindings,
            finalizations,
            finalization_history,
            release_bindings,
            reclassifications,
        )
    ):
        raise CleanupExportEvidenceError("cleanup attempt-specific state is malformed")
    assert isinstance(essential_seals, dict)
    assert isinstance(raw_bindings, dict)
    assert isinstance(finalizations, dict)
    assert isinstance(finalization_history, dict)
    assert isinstance(release_bindings, dict)
    assert isinstance(reclassifications, dict)

    attempt_state_count, start_intent_count = _cleanup_attempt_specific_evidence(
        root,
        repository=repository,
        contract=contract,
    )
    acknowledgement_names = frozenset(f"{run_id}.json" for run_id in contract.run_ids)
    completion_names = frozenset(f"{run_id}-export-completion.json" for run_id in contract.run_ids)
    archive_names = frozenset(f"{run_id}.tar.gz" for run_id in contract.run_ids)
    acknowledgement_members = _cleanup_evidence_members(
        control_root / "received-export-acknowledgements",
        expected_names=acknowledgement_names,
        label="received export acknowledgements",
    )
    completion_members = _cleanup_evidence_members(
        control_root / "attempt-export-completions",
        expected_names=completion_names,
        label="attempt export completions",
    )
    archive_members = _cleanup_evidence_members(
        control_root / "attempt-exports",
        expected_names=archive_names,
        label="attempt export archives",
    )
    if retained_chronology is None:
        chronology_count = 0
    else:
        chronology_count = len(
            _validate_export_chronology_projection(
                retained_chronology,
                attempt_order=contract.run_ids,
            )
        )

    frozen_path = control_root / "frozen-run-manifest.json"
    postfreeze_path = control_root / "postfreeze-validation.json"
    preflight_path = control_root / "preflight.json"
    manifest_present = os.path.lexists(frozen_path)
    postfreeze_present = os.path.lexists(postfreeze_path)
    preflight_present = os.path.lexists(preflight_path)
    required_acknowledgements = _consumed_export_prefix_length(state)
    attempt_specific_state_exists = bool(
        entered
        or raw_complete
        or completed
        or nonempirical
        or reservation is not None
        or essential_seals
        or raw_bindings
        or finalizations
        or finalization_history
        or release_bindings
        or reclassifications
        or attempt_state_count
        or start_intent_count
        or acknowledgement_members
        or completion_members
        or archive_members
        or chronology_count
        or retained_pending is not None
    )
    if postfreeze_present != manifest_present or (preflight_present and not postfreeze_present):
        raise CleanupExportEvidenceError("frozen manifest publication evidence is partial")
    if attempt_specific_state_exists and not manifest_present:
        raise CleanupExportEvidenceError(
            "attempt-specific cleanup evidence lacks a frozen manifest"
        )

    if not manifest_present:
        if (
            cleanup_journal_state.empirical_entry_status is not EmpiricalEntryStatus.NOT_ENTERED
            or required_acknowledgements != 0
        ):
            raise CleanupExportEvidenceError("pre-freeze cleanup evidence is contradictory")
        try:
            return CleanupExportPhaseEvidence(
                lifecycle_phase=CleanupExportLifecyclePhase.PREFREEZE_ZERO_ATTEMPT,
                provider_contract_version=contract.version,
                plan_id=contract.plan_id,
                host_run_id=contract.host_run_id,
                frozen_manifest_state="not-published-expected",
                frozen_manifest_sha256=None,
                empirical_attempt_count=len(entered),
                raw_attempt_complete_count=len(raw_complete),
                attempt_completed_count=len(completed),
                condition_start_reservation_count=int(reservation is not None),
                condition_start_intent_count=start_intent_count,
                attempt_specific_state_count=attempt_state_count,
                postfreeze_entry_receipt_count=0,
                required_export_acknowledgement_count=required_acknowledgements,
                observed_export_acknowledgement_count=len(acknowledgement_members),
                retained_export_chronology_count=chronology_count,
            )
        except EarlyCleanupStateError as exc:
            raise CleanupExportEvidenceError(
                "pre-freeze cleanup evidence is contradictory"
            ) from exc

    # The lifecycle decision above is complete.  Only now may cleanup load the
    # manifest and its publication receipt.
    try:
        frozen_manifest, frozen_sha256 = load_frozen_run_manifest(
            root,
            repository=repository,
            package_commit=package_commit,
            require_image=False,
        )
    except (OSError, UnicodeDecodeError, json.JSONDecodeError, T09HostError, T09PilotError) as exc:
        raise CleanupExportEvidenceError("published frozen manifest is invalid") from exc
    postfreeze = _load_cleanup_evidence_object(
        postfreeze_path,
        label="frozen manifest publication receipt",
    )
    _require_provider_contract(
        postfreeze,
        expected=contract,
        label="frozen manifest publication receipt",
    )
    published_at = postfreeze.get("frozen_manifest_published_at_epoch")
    if (
        postfreeze.get("package_commit") != package_commit
        or postfreeze.get("frozen_run_manifest_sha256") != frozen_sha256
        or postfreeze.get("frozen_manifest_published_before_empirical_clock") is not True
        or not isinstance(published_at, (int, float))
        or isinstance(published_at, bool)
        or not math.isfinite(float(published_at))
        or _provider_contract_from_document(frozen_manifest, label="cleanup frozen manifest")
        is not contract
    ):
        raise CleanupExportEvidenceError("frozen manifest publication receipt drifted")
    if preflight_present:
        preflight = _load_cleanup_evidence_object(
            preflight_path,
            label="post-freeze preflight receipt",
        )
        _require_provider_contract(preflight, expected=contract, label="post-freeze preflight")
        if (
            preflight.get("clean_package_commit") != package_commit
            or preflight.get("frozen_run_manifest_sha256") != frozen_sha256
            or preflight.get("postfreeze_validation_sha256") != file_sha256(postfreeze_path)
        ):
            raise CleanupExportEvidenceError("post-freeze preflight receipt drifted")
    elif attempt_specific_state_exists:
        raise CleanupExportEvidenceError("empirical cleanup lacks its post-freeze entry receipt")
    if entered and cleanup_journal_state.empirical_entry_status is not EmpiricalEntryStatus.ENTERED:
        raise CleanupExportEvidenceError("cleanup journal contradicts empirical entry")

    phase = (
        CleanupExportLifecyclePhase.EMPIRICAL_PREFIX
        if attempt_specific_state_exists
        else CleanupExportLifecyclePhase.POSTFREEZE_ZERO_ATTEMPT
    )
    try:
        return CleanupExportPhaseEvidence(
            lifecycle_phase=phase,
            provider_contract_version=contract.version,
            plan_id=contract.plan_id,
            host_run_id=contract.host_run_id,
            frozen_manifest_state="published-valid",
            frozen_manifest_sha256=frozen_sha256,
            empirical_attempt_count=len(entered),
            raw_attempt_complete_count=len(raw_complete),
            attempt_completed_count=len(completed),
            condition_start_reservation_count=int(reservation is not None),
            condition_start_intent_count=start_intent_count,
            attempt_specific_state_count=attempt_state_count,
            postfreeze_entry_receipt_count=1,
            required_export_acknowledgement_count=required_acknowledgements,
            observed_export_acknowledgement_count=len(acknowledgement_members),
            retained_export_chronology_count=chronology_count,
        )
    except EarlyCleanupStateError as exc:
        raise CleanupExportEvidenceError(
            "cleanup export lifecycle evidence is contradictory"
        ) from exc


def require_prior_export_acknowledgements(
    root: Path,
    *,
    next_attempt_index: int,
    package_commit: str,
    lifecycle_phase: CleanupExportPhaseEvidence | None = None,
) -> list[dict[str, object]]:
    """Block empirical progression until every prior archive was verified off-host."""

    control_root = _pilot_root(root)
    state = _runtime_budget_state(root)
    contract = _provider_contract_from_document(state, label="pilot state")
    entry = load_object(control_root / "provider-entry.json", label="provider entry")
    _require_provider_contract(
        entry,
        expected=contract,
        label="attempt export acknowledgement provider entry",
    )
    attempt_order = contract.run_ids
    raw_complete = state.get("raw_attempts_complete")
    entered = state.get("empirical_attempts_entered")
    completed = state.get("attempts_completed", [])
    nonempirical = state.get("nonempirical_infrastructure_attempts_consumed", [])
    essential_seals = state.get("essential_failure_seals")
    if (
        not isinstance(raw_complete, list)
        or not isinstance(entered, list)
        or not isinstance(completed, list)
        or not isinstance(nonempirical, list)
        or not isinstance(essential_seals, dict)
    ):
        raise T09HostError("attempt export acknowledgement state is malformed")
    if not 0 <= next_attempt_index <= len(attempt_order):
        raise T09HostError("attempt export acknowledgement prefix is invalid")
    frozen_manifest_path = control_root / "frozen-run-manifest.json"
    postfreeze_path = control_root / "postfreeze-validation.json"
    preflight_path = control_root / "preflight.json"
    publication_evidence_present = os.path.lexists(postfreeze_path) or os.path.lexists(
        preflight_path
    )
    if publication_evidence_present and not os.path.lexists(frozen_manifest_path):
        raise CleanupExportEvidenceError(
            "frozen manifest publication evidence exists without its manifest"
        )
    has_attempt_specific_evidence = bool(
        entered
        or raw_complete
        or completed
        or nonempirical
        or essential_seals
        or state.get("condition_start_reservation") is not None
        or next_attempt_index
    )
    if lifecycle_phase is not None:
        if (
            lifecycle_phase.provider_contract_version != contract.version
            or lifecycle_phase.plan_id != contract.plan_id
            or lifecycle_phase.host_run_id != contract.host_run_id
            or lifecycle_phase.empirical_attempt_count != len(entered)
            or lifecycle_phase.raw_attempt_complete_count != len(raw_complete)
            or lifecycle_phase.attempt_completed_count != len(completed)
        ):
            raise CleanupExportEvidenceError("cleanup export phase differs from pilot state")
        phase = lifecycle_phase.lifecycle_phase
    elif (
        not os.path.lexists(frozen_manifest_path)
        and not publication_evidence_present
        and not has_attempt_specific_evidence
    ):
        phase = CleanupExportLifecyclePhase.PREFREEZE_ZERO_ATTEMPT
    elif has_attempt_specific_evidence:
        phase = CleanupExportLifecyclePhase.EMPIRICAL_PREFIX
    else:
        phase = CleanupExportLifecyclePhase.POSTFREEZE_ZERO_ATTEMPT

    if phase is CleanupExportLifecyclePhase.PREFREEZE_ZERO_ATTEMPT:
        if (
            next_attempt_index != 0
            or has_attempt_specific_evidence
            or os.path.lexists(frozen_manifest_path)
        ):
            raise CleanupExportEvidenceError("pre-freeze acknowledgement phase is contradictory")
        return []
    if not os.path.lexists(frozen_manifest_path):
        raise CleanupExportEvidenceError("frozen manifest is mandatory for this export phase")
    frozen_manifest = _load_cleanup_evidence_object(
        frozen_manifest_path,
        label="frozen run manifest",
    )
    frozen_manifest_sha256 = file_sha256(frozen_manifest_path)
    _require_provider_contract(
        frozen_manifest,
        expected=contract,
        label="attempt export acknowledgement frozen manifest",
    )
    if lifecycle_phase is not None and (
        lifecycle_phase.frozen_manifest_state != "published-valid"
        or lifecycle_phase.frozen_manifest_sha256 != frozen_manifest_sha256
    ):
        raise CleanupExportEvidenceError("cleanup export phase lost its frozen manifest binding")
    if phase is CleanupExportLifecyclePhase.POSTFREEZE_ZERO_ATTEMPT:
        if next_attempt_index != 0 or has_attempt_specific_evidence:
            raise CleanupExportEvidenceError("post-freeze zero-attempt phase is contradictory")
        return []
    lambda_started = entry.get("lambda_started_at_epoch")
    replacement_image_id = frozen_manifest.get("replacement_image_id")
    provider_entry_sha256 = entry.get("receipt_sha256")
    owned_instance_sha256 = entry.get("owned_instance_identity_sha256")
    if (
        not isinstance(lambda_started, (int, float))
        or isinstance(lambda_started, bool)
        or not isinstance(replacement_image_id, str)
        or re.fullmatch(r"sha256:[a-f0-9]{64}", replacement_image_id) is None
        or not isinstance(provider_entry_sha256, str)
        or _HEX64.fullmatch(provider_entry_sha256) is None
        or not isinstance(owned_instance_sha256, str)
        or _HEX64.fullmatch(owned_instance_sha256) is None
    ):
        raise T09HostError("attempt export acknowledgement runtime identity is malformed")
    projections: list[dict[str, object]] = []
    for run_id in attempt_order[:next_attempt_index]:
        raw_authority = run_id in raw_complete
        essential_authority = isinstance(essential_seals.get(run_id), dict)
        if raw_authority == essential_authority:
            raise T09HostError("consumed attempt lacks one exact export evidence authority")
        evidence_authority = (
            "immutable-raw-attempt" if raw_authority else "essential-infrastructure-failure"
        )
        empirical_entry_crossed = run_id in entered
        if raw_authority and not empirical_entry_crossed:
            raise T09HostError("raw export authority lacks empirical entry")
        acknowledgement_path = _received_export_ack_path(root, run_id)
        if not acknowledgement_path.is_file():
            raise T09HostError(
                "prior attempt archive lacks its off-host verification acknowledgement"
            )
        acknowledgement = load_object(
            acknowledgement_path,
            label=f"{run_id} received export acknowledgement",
        )
        archive = control_root / "attempt-exports" / f"{run_id}.tar.gz" if raw_authority else None
        completion_path = _attempt_export_completion_path(root, run_id)
        completion = load_object(completion_path, label=f"{run_id} export completion")
        projections.append(
            _validate_attempt_export_acknowledgement(
                acknowledgement=acknowledgement,
                acknowledgement_sha256=file_sha256(acknowledgement_path),
                completion=completion,
                completion_sha256=file_sha256(completion_path),
                run_id=run_id,
                package_commit=package_commit,
                evidence_authority=evidence_authority,
                empirical_entry_crossed=empirical_entry_crossed,
                frozen_run_manifest_sha256=frozen_manifest_sha256,
                replacement_image_id=replacement_image_id,
                provider_entry_receipt_sha256=provider_entry_sha256,
                owned_instance_identity_sha256=owned_instance_sha256,
                lambda_started_at_epoch=float(lambda_started),
                archive=archive,
                contract=contract,
            )
        )
    return projections


def require_attempt_export_acknowledgement(
    root: Path,
    *,
    run_id: str,
    package_commit: str,
) -> None:
    """Require the current immutable raw export before downstream finalization."""

    try:
        attempt_index = _runtime_provider_contract(root).run_ids.index(run_id)
    except ValueError:
        raise T09HostError("export acknowledgement run identity is unknown") from None
    require_prior_export_acknowledgements(
        root,
        next_attempt_index=attempt_index + 1,
        package_commit=package_commit,
    )


def _active_lambda_accounting(root: Path, *, now: float) -> tuple[dict[str, Any], float, float]:
    state = _runtime_budget_state(root)
    owned_started = state.get("owned_lambda_started_at_epoch", state.get("lambda_started_at_epoch"))
    prior_duration = state.get("prior_campaign_lambda_duration_seconds", 0.0)
    prior_cost = state.get("prior_campaign_lambda_cost_usd", 0.0)
    if not all(
        isinstance(value, (int, float)) and not isinstance(value, bool)
        for value in (owned_started, prior_duration, prior_cost)
    ):
        raise T09HostError("active Lambda accounting is unavailable")
    owned_elapsed = now - float(cast(int | float, owned_started))
    active_duration = float(cast(int | float, prior_duration)) + owned_elapsed
    active_cost = float(cast(int | float, prior_cost)) + (
        owned_elapsed * LAMBDA_HOURLY_PRICE_USD / 3600.0
    )
    if min(owned_elapsed, active_duration, active_cost) < 0:
        raise T09HostError("active Lambda chronology is invalid")
    return state, active_duration, active_cost


def provider_seconds_remaining(root: Path, *, reserve_seconds: float = 0.0) -> float:
    """Return phase-correct provider headroom without mixing cost envelopes."""

    now = time.time()
    state, preflight_active_duration, preflight_active_cost = _active_lambda_accounting(
        root, now=now
    )
    owned_started = float(cast(int | float, state["owned_lambda_started_at_epoch"]))
    per_instance_remaining = MAX_PREFLIGHT_INSTANCE_ACTIVE_SECONDS - (now - owned_started)
    empirical_started = state.get("campaign_started_at_epoch")
    if (
        isinstance(empirical_started, (int, float))
        and not isinstance(empirical_started, bool)
        and float(empirical_started) <= now
    ):
        empirical_elapsed = now - float(empirical_started)
        remaining = min(
            per_instance_remaining,
            MAX_EMPIRICAL_LAMBDA_DURATION_SECONDS - empirical_elapsed,
            (MAX_EMPIRICAL_LAMBDA_COST_USD - empirical_elapsed * LAMBDA_HOURLY_PRICE_USD / 3600.0)
            * 3600.0
            / LAMBDA_HOURLY_PRICE_USD,
        )
    else:
        remaining = min(
            per_instance_remaining,
            MAX_CUMULATIVE_PREFLIGHT_ACTIVE_SECONDS - preflight_active_duration,
            (MAX_PREFLIGHT_LAMBDA_COST_USD - preflight_active_cost)
            * 3600.0
            / LAMBDA_HOURLY_PRICE_USD,
        )
    if remaining + 1e-9 < reserve_seconds:
        raise T09HostError("provider duration or cost ceiling has no required reserve")
    return max(0.0, remaining - reserve_seconds)


def preflight_seconds_remaining(root: Path) -> float:
    """Return the fresh per-launch qualification window and cumulative headroom."""

    state, _, _ = _active_lambda_accounting(root, now=time.time())
    started = state.get("provider_preflight_started_at_epoch")
    if not isinstance(started, (int, float)) or isinstance(started, bool):
        raise T09HostError("provider preflight time origin is unavailable")
    lifecycle = AutonomousPilotLifecycleLimits()
    return min(
        lifecycle.preflight_instance_remaining(
            launched_at_epoch=float(started),
            now_epoch=time.time(),
        ),
        provider_seconds_remaining(root),
    )


def scientific_seconds_remaining(root: Path, *, reserve_seconds: float = 0.0) -> float:
    """Return post-freeze empirical time plus cumulative active-provider headroom."""

    state, _, _ = _active_lambda_accounting(root, now=time.time())
    empirical_started = state.get("campaign_started_at_epoch")
    if not isinstance(empirical_started, (int, float)) or isinstance(empirical_started, bool):
        raise T09HostError("empirical campaign clock has not started")
    lifecycle = AutonomousPilotLifecycleLimits()
    empirical_remaining = lifecycle.empirical_remaining(
        empirical_started_at_epoch=float(empirical_started),
        now_epoch=time.time(),
    )
    active_remaining = provider_seconds_remaining(root)
    remaining = min(empirical_remaining, active_remaining)
    if remaining + 1e-9 < reserve_seconds:
        raise T09HostError("empirical or active-provider ceiling has no required reserve")
    return max(0.0, remaining - reserve_seconds)


def admit_next_attempt(root: Path) -> float:
    """Reserve one full condition plus export, handoff, and cleanup headroom."""

    state = _runtime_budget_state(root)
    if state.get("nonempirical_infrastructure_attempts_consumed") or state.get(
        "essential_failure_seals"
    ):
        raise T09HostError("a consumed infrastructure failure permanently closes admission")
    usable = scientific_seconds_remaining(
        root,
        reserve_seconds=NEXT_ATTEMPT_POSTCONDITION_RESERVE_SECONDS,
    )
    if usable < MAX_CONDITION_WALL_SECONDS:
        raise T09HostError(
            "remaining campaign time cannot cover the condition, evidence export, "
            "provider handoff, and cleanup envelope"
        )
    return usable


def admit_scheduled_first_attempt_before_empirical_origin(
    root: Path,
    *,
    scheduled_empirical_start: float,
) -> float:
    """Validate first-attempt headroom while the frozen origin is still future.

    The ordinary lifecycle helper intentionally rejects future origins.  Preflight
    has to finish and durably validate every receipt before that origin, so this
    projection treats the not-yet-started empirical wall as entirely available
    while still charging the provider's already-active clock.
    """

    state = _runtime_budget_state(root)
    now = time.time()
    if (
        state.get("campaign_started_at_epoch") != scheduled_empirical_start
        or state.get("pilot_started_at_epoch") != scheduled_empirical_start
        or state.get("first_pair_started_at_epoch") != scheduled_empirical_start
        or now > scheduled_empirical_start
        or state.get("nonempirical_infrastructure_attempts_consumed")
        or state.get("essential_failure_seals")
    ):
        raise T09HostError("scheduled first-attempt admission authority drifted")
    usable = min(MAX_TOTAL_WALL_SECONDS, provider_seconds_remaining(root))
    usable_after_reserves = usable - NEXT_ATTEMPT_POSTCONDITION_RESERVE_SECONDS
    if usable_after_reserves < MAX_CONDITION_WALL_SECONDS:
        raise T09HostError(
            "scheduled first attempt lacks its condition, evidence export, "
            "provider handoff, and cleanup envelope"
        )
    return usable_after_reserves


def provider_termination_due(root: Path) -> bool:
    """Return whether normal provider termination must already have begun."""

    state = _runtime_budget_state(root)
    started = state.get("campaign_started_at_epoch")
    if not isinstance(started, (int, float)) or isinstance(started, bool):
        preflight_started = state.get("provider_preflight_started_at_epoch")
        if not isinstance(preflight_started, (int, float)) or isinstance(preflight_started, bool):
            raise T09HostError("provider preflight time origin is unavailable")
        return time.time() - float(preflight_started) >= MAX_PREFLIGHT_INSTANCE_ACTIVE_SECONDS
    return time.time() - float(started) >= PROVIDER_TERMINATION_CUTOFF_SECONDS


def container_state_receipt(prefix: list[str], container_target: str) -> dict[str, object]:
    raw = output([*prefix, "inspect", "--format", "{{json .State}}", container_target])
    try:
        value: object = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise T09HostError("container state inspection is malformed") from exc
    if not isinstance(value, dict):
        raise T09HostError("container state inspection is not an object")
    state = cast(dict[str, Any], value)
    return {
        "status": state.get("Status"),
        "running": state.get("Running"),
        "paused": state.get("Paused"),
        "restarting": state.get("Restarting"),
        "oom_killed": state.get("OOMKilled"),
        "dead": state.get("Dead"),
        "exit_code": state.get("ExitCode"),
        "started_at": state.get("StartedAt"),
        "finished_at": state.get("FinishedAt"),
        "private_network_fields_retained": False,
    }


def manifests(
    document: dict[str, Any],
    *,
    expected_run_ids: tuple[str, ...],
) -> list[dict[str, Any]]:
    value = document.get("manifests")
    if not isinstance(value, list) or len(value) != 4:
        raise T09HostError("exactly four command manifests are required")
    result = [item for item in value if isinstance(item, dict)]
    if len(result) != 4 or tuple(item.get("run_id") for item in result) != expected_run_ids:
        raise T09HostError("command manifest order or identities drifted")
    pair_diffs = document.get("pair_diffs")
    if (
        not isinstance(pair_diffs, list)
        or len(pair_diffs) != 2
        or any(not isinstance(item, dict) or item.get("valid") is not True for item in pair_diffs)
    ):
        raise T09HostError("command pair diffs are not valid")
    return cast(list[dict[str, Any]], result)


def manifest_for_run(
    document: dict[str, Any],
    run_id: str,
    *,
    expected_run_ids: tuple[str, ...],
) -> dict[str, Any]:
    matches = [
        item
        for item in manifests(document, expected_run_ids=expected_run_ids)
        if item.get("run_id") == run_id
    ]
    if len(matches) != 1:
        raise T09HostError("run command manifest is missing or duplicated")
    return matches[0]


def _manifest_for_contract(
    document: dict[str, Any],
    run_id: str,
    contract: T09ProviderContract,
) -> dict[str, Any]:
    """Resolve one manifest from the explicitly selected attempt order."""

    return manifest_for_run(document, run_id, expected_run_ids=contract.run_ids)


def manifest_output_root(manifest: dict[str, Any]) -> str:
    owned = manifest.get("permitted_condition_owned")
    if not isinstance(owned, dict):
        raise T09HostError("command manifest lacks its condition-owned surface")
    output_root = owned.get("output_root")
    if not isinstance(output_root, str):
        raise T09HostError("command manifest lacks its condition-owned output root")
    relative = PurePosixPath(output_root)
    if relative.is_absolute() or ".." in relative.parts:
        raise T09HostError("condition-owned output root is unsafe")
    return output_root


def verify_package(
    repository: Path,
    package_commit: str,
    *,
    current_commit: str | None = None,
    contract: T09ProviderContract,
) -> dict[str, Any]:
    expected_head = package_commit if current_commit is None else current_commit
    if output(["git", "-C", str(repository), "rev-parse", "HEAD"]) != expected_head:
        raise T09HostError("repository commit does not match the authorized clean package")
    if output(["git", "-C", str(repository), "status", "--porcelain=v1"]):
        raise T09HostError("repository worktree is not clean")
    paths = _contract_paths_for(repository, contract)
    execution = load_object(paths["execution"], label="execution contract")
    load_execution_contract(
        paths["execution"],
        expected_sha256=file_sha256(paths["execution"]),
    )
    if (
        execution.get("authorized") is not False
        or execution.get("authorization_reference") is not None
        or execution.get("execution_eligibility") != "blocked-until-fresh-category-3-authorization"
        or execution.get("plan_id") != contract.plan_id
    ):
        raise T09HostError("execution contract identity or authorization drifted")
    runtime = execution.get("runtime")
    if (
        not isinstance(runtime, dict)
        or runtime.get("container_image_digest") is not None
        or runtime.get("container_image_policy")
        != ("retained-exact-archive-load-or-one-fallback-build-preentry-frozen-run-manifest-v1")
        or runtime.get("historical_container_image_digest") != HISTORICAL_IMAGE_ID
    ):
        raise T09HostError("replacement image policy drifted")
    bindings = execution.get("contract_bindings")
    if not isinstance(bindings, dict):
        raise T09HostError("execution contract bindings are malformed")
    for label, raw in bindings.items():
        if not isinstance(label, str) or not isinstance(raw, dict):
            raise T09HostError("execution contract binding is malformed")
        relative = raw.get("path")
        expected_sha256 = raw.get("sha256")
        if not isinstance(relative, str) or not isinstance(expected_sha256, str):
            raise T09HostError("execution contract binding lacks path or hash")
        relative_path = Path(relative)
        if relative_path.is_absolute() or ".." in relative_path.parts:
            raise T09HostError("execution contract binding path is unsafe")
        bound = repository / relative_path
        if not bound.is_file() or file_sha256(bound) != expected_sha256:
            raise T09HostError(f"execution contract binding drifted: {label}")
        expected_size = raw.get("size_bytes")
        if expected_size is not None and bound.stat().st_size != expected_size:
            raise T09HostError(f"execution contract byte-size binding drifted: {label}")
    runtime_identity = load_object(paths["runtime"], label="runtime identity")
    base_runtime = runtime_identity.get("base_runtime")
    scientific_runtime = runtime_identity.get("scientific_runtime")
    replacement_policy = runtime_identity.get("replacement_image_policy")
    if (
        not isinstance(base_runtime, dict)
        or base_runtime.get("python_version") != "3.11.14"
        or base_runtime.get("installed_package_manifest_sha256") != EXPECTED_PACKAGE_MANIFEST_SHA256
        or base_runtime.get("chromium_sha256") != EXPECTED_CHROMIUM_SHA256
        or not isinstance(scientific_runtime, dict)
        or scientific_runtime.get("runner_sha256") != EXPECTED_UPSTREAM_RUNNER_SHA256
        or not isinstance(replacement_policy, dict)
        or replacement_policy.get("historical_image_digest") != HISTORICAL_IMAGE_ID
        or replacement_policy.get("exact_historical_digest_equality_required") is not False
        or replacement_policy.get("runtime_binding")
        != "source-derived-mode-0600-O_EXCL-frozen-run-manifest"
    ):
        raise T09HostError("runtime semantic identity drifted")
    instrumentation = runtime_identity.get("repository_instrumentation")
    files = instrumentation.get("files") if isinstance(instrumentation, dict) else None
    if not isinstance(files, list) or not files:
        raise T09HostError("runtime instrumentation bindings are missing")
    for raw in files:
        if not isinstance(raw, dict):
            raise T09HostError("runtime instrumentation binding is malformed")
        relative = raw.get("path")
        expected_sha256 = raw.get("sha256")
        if (
            not isinstance(relative, str)
            or not isinstance(expected_sha256, str)
            or Path(relative).is_absolute()
            or ".." in Path(relative).parts
        ):
            raise T09HostError("runtime instrumentation file binding drifted")
        observed_sha256 = (
            git_file_sha256(repository, package_commit, relative)
            if current_commit is not None
            and relative
            in {
                FINALIZER_RELATIVE_PATH,
                FINALIZER_PROJECTION_RELATIVE_PATH,
                "containers/sira-smoke/pragmatic/t09_remote_runner.py",
            }
            else file_sha256(repository / relative)
        )
        if observed_sha256 != expected_sha256:
            raise T09HostError("runtime instrumentation file binding drifted")
    evaluator_contract = load_object(paths["evaluator"], label="evaluator contract")
    materialization = evaluator_contract.get("materialization")
    if not isinstance(materialization, dict):
        raise T09HostError("evaluator materialization contract is malformed")
    lock_relative = materialization.get("lock_path")
    lock_sha256 = materialization.get("lock_sha256")
    if (
        not isinstance(lock_relative, str)
        or Path(lock_relative).is_absolute()
        or ".." in Path(lock_relative).parts
        or not isinstance(lock_sha256, str)
        or not (repository / lock_relative).is_file()
        or file_sha256(repository / lock_relative) != lock_sha256
    ):
        raise T09HostError("evaluator dependency lock binding drifted")
    command_document = load_object(paths["commands"], label="command manifest set")
    if (
        command_document.get("plan_id") != contract.plan_id
        or command_document.get("execution_contract_sha256") != file_sha256(paths["execution"])
        or command_document.get("plan_sha256") != file_sha256(paths["plan"])
    ):
        raise T09HostError("command manifest package binding drifted")
    reviewed_ancestor = command_document.get("reviewed_implementation_ancestor")
    attempts = execution.get("attempts")
    bound_ancestors = (
        {item.get("giclab_commit") for item in attempts if isinstance(item, dict)}
        if isinstance(attempts, list)
        else set()
    )
    if (
        not isinstance(reviewed_ancestor, str)
        or len(reviewed_ancestor) != 40
        or any(character not in "0123456789abcdef" for character in reviewed_ancestor)
        or bound_ancestors != {reviewed_ancestor}
    ):
        raise T09HostError("reviewed implementation ancestor binding drifted")
    ancestor_check = subprocess.run(
        [
            "git",
            "-C",
            str(repository),
            "merge-base",
            "--is-ancestor",
            reviewed_ancestor,
            package_commit,
        ],
        env=safe_environment(),
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=False,
        timeout=30,
    )
    if ancestor_check.returncode != 0:
        raise T09HostError("reviewed implementation commit is not an ancestor of the package")
    for raw in files:
        assert isinstance(raw, dict)
        relative = raw["path"]
        expected_sha256 = raw["sha256"]
        historical = subprocess.run(
            ["git", "-C", str(repository), "show", f"{reviewed_ancestor}:{relative}"],
            env=safe_environment(),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            check=False,
            timeout=30,
        )
        if (
            historical.returncode != 0
            or hashlib.sha256(historical.stdout).hexdigest() != expected_sha256
        ):
            raise T09HostError("reviewed ancestor does not contain the selected runtime bytes")
    generator_relative = command_document.get("generator_path")
    generator_sha256 = command_document.get("generator_sha256")
    if (
        not isinstance(generator_relative, str)
        or Path(generator_relative).is_absolute()
        or ".." in Path(generator_relative).parts
        or not isinstance(generator_sha256, str)
        or not (repository / generator_relative).is_file()
        or file_sha256(repository / generator_relative) != generator_sha256
    ):
        raise T09HostError("command manifest generator binding drifted")
    for item in manifests(command_document, expected_run_ids=contract.run_ids):
        condition_path = repository / item["condition_plan_path"]
        if file_sha256(condition_path) != item.get("condition_plan_sha256"):
            raise T09HostError("condition plan hash changed")
        if item.get("execution_contract_sha256") != file_sha256(paths["execution"]):
            raise T09HostError("command execution-contract binding changed")
    return command_document


def _evaluator_package_records(
    *,
    overlay: Path,
    prefix: list[str],
    image_id: str,
    expected_packages: list[str],
    evidence_root: Path,
    label: str,
    cleanup_journal: EarlyCleanupJournal,
    contract: T09ProviderContract,
) -> list[str]:
    command = [
        *prefix,
        "run",
        "--rm",
        *CORE_ULIMIT_DOCKER_ARGS,
        "--network",
        "none",
        "--log-driver",
        "none",
        "--read-only",
        "--cap-drop",
        "ALL",
        "--security-opt",
        "no-new-privileges=true",
        "--user",
        "1000:1000",
        "--env",
        "HOME=/tmp",
        "--env",
        "UV_CACHE_DIR=/tmp/uv-cache",
        "--tmpfs",
        "/tmp:rw,noexec,nosuid,nodev,size=67108864,uid=1000,gid=1000,mode=0700",
        "--mount",
        f"type=bind,src={overlay},dst=/opt/evaluator,readonly",
        "--entrypoint",
        "/usr/local/bin/uv",
        image_id,
        "pip",
        "freeze",
        "--python",
        "/opt/evaluator/.venv/bin/python",
    ]
    result = run_owned_docker(
        command,
        prefix=prefix,
        label=label,
        evidence_root=evidence_root,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        timeout=120,
        cleanup_journal=cleanup_journal,
        contract=contract,
    )
    if result.returncode != 0 or len(result.stdout) > 1_048_576:
        raise T09HostError("exact evaluator package manifest failed")
    try:
        raw_text = result.stdout.decode("utf-8", errors="strict")
    except UnicodeDecodeError as exc:
        raise T09HostError("evaluator package manifest is not UTF-8") from exc
    return normalize_evaluator_package_records(raw_text, expected_packages=expected_packages)


def normalize_evaluator_package_records(
    raw_text: str,
    *,
    expected_packages: list[str],
) -> list[str]:
    """Normalize only the one reviewed direct URL and require exact package closure."""

    raw_packages = sorted(line.strip() for line in raw_text.splitlines() if line.strip())
    if (
        not raw_packages
        or len(raw_packages) != len(set(raw_packages))
        or any(
            len(line) > 1_024
            or any(ord(character) < 32 for character in line)
            or (
                re.fullmatch(
                    r"[A-Za-z0-9][A-Za-z0-9._-]*==[A-Za-z0-9][A-Za-z0-9.!+_-]*",
                    line,
                )
                is None
                and line != EVALUATOR_DIRECT_URL_RECORD
            )
            for line in raw_packages
        )
    ):
        raise T09HostError("evaluator package manifest is unsafe or ambiguous")
    packages = sorted(
        "en-core-web-sm==3.8.0" if line == EVALUATOR_DIRECT_URL_RECORD else line
        for line in raw_packages
    )
    if packages != expected_packages:
        raise T09HostError("realized evaluator package set differs from the reviewed contract")
    return packages


def expected_evaluator_packages(
    repository: Path,
    provider_contract: T09ProviderContract,
) -> list[str]:
    contract = load_object(
        _contract_paths_for(repository, provider_contract)["evaluator"], label="evaluator contract"
    )
    materialization = contract.get("materialization")
    inventory = (
        materialization.get("dependency_license_inventory")
        if isinstance(materialization, dict)
        else None
    )
    if not isinstance(inventory, list) or not inventory:
        raise T09HostError("evaluator dependency license inventory is unavailable")
    packages: list[str] = []
    for item in inventory:
        if not isinstance(item, str) or item.count("|") != 1:
            raise T09HostError("evaluator dependency inventory is malformed")
        package, license_identity = item.split("|", 1)
        if (
            re.fullmatch(
                r"[A-Za-z0-9][A-Za-z0-9._-]*==[A-Za-z0-9][A-Za-z0-9.!+_-]*",
                package,
            )
            is None
            or not license_identity
        ):
            raise T09HostError("evaluator dependency inventory identity is malformed")
        packages.append(package)
    result = sorted(packages)
    if len(result) != len(set(result)):
        raise T09HostError("evaluator dependency inventory contains duplicates")
    return result


def evaluator_overlay_inventory(overlay: Path) -> dict[str, object]:
    """Manifest every realized evaluator directory, file, and symlink without following it."""

    root = overlay.resolve(strict=True)
    root_metadata = root.stat(follow_symlinks=False)
    if (
        not stat.S_ISDIR(root_metadata.st_mode)
        or root.is_symlink()
        or root_metadata.st_uid != os.getuid()
        or stat.S_IMODE(root_metadata.st_mode) != 0o700
    ):
        raise T09HostError("evaluator overlay root metadata is unsafe")
    entries: list[dict[str, object]] = []
    total_regular_bytes = 0
    for current, raw_directories, raw_files in os.walk(root, topdown=True, followlinks=False):
        current_path = Path(current)
        raw_directories.sort()
        raw_files.sort()
        names = [*raw_directories, *raw_files]
        retained_directories: list[str] = []
        for name in names:
            path = current_path / name
            metadata = path.lstat()
            relative = path.relative_to(root).as_posix()
            if not relative or relative.startswith("../"):
                raise T09HostError("evaluator overlay path escaped its root")
            record: dict[str, object] = {
                "path": relative,
                "mode": f"{stat.S_IMODE(metadata.st_mode):04o}",
            }
            if stat.S_ISDIR(metadata.st_mode):
                record["type"] = "directory"
                retained_directories.append(name)
            elif stat.S_ISREG(metadata.st_mode):
                if metadata.st_nlink != 1:
                    raise T09HostError("evaluator overlay contains a linked regular file")
                record.update(
                    {
                        "type": "file",
                        "bytes": metadata.st_size,
                        "sha256": file_sha256(path),
                    }
                )
                total_regular_bytes += metadata.st_size
            elif stat.S_ISLNK(metadata.st_mode):
                target = os.readlink(path)
                if not target or len(os.fsencode(target)) > 4_096 or "\0" in target:
                    raise T09HostError("evaluator overlay symlink target is unsafe")
                record.update({"type": "symlink", "target": target})
            else:
                raise T09HostError("evaluator overlay contains a special file")
            entries.append(record)
            if (
                len(entries) > MAX_EVALUATOR_OVERLAY_ENTRIES
                or total_regular_bytes > MAX_EVALUATOR_OVERLAY_BYTES
            ):
                raise T09HostError("evaluator overlay exceeds its frozen manifest cap")
        raw_directories[:] = retained_directories
    return {
        "root_mode": "0700",
        "entries": entries,
        "entry_count": len(entries),
        "total_regular_bytes": total_regular_bytes,
        "entries_sha256": canonical_sha256(entries),
    }


def local_dependency_tree_inventory(root: Path, *, label: str) -> dict[str, object]:
    """Hash a control-machine dependency tree without following links."""

    resolved = root.resolve(strict=True)
    root_metadata = resolved.stat(follow_symlinks=False)
    if (
        resolved.is_symlink()
        or not stat.S_ISDIR(root_metadata.st_mode)
        or root_metadata.st_uid != os.getuid()
        or root_metadata.st_mode & 0o022
    ):
        raise T09HostError(f"{label} root metadata is unsafe")
    entries: list[dict[str, object]] = []
    total_regular_bytes = 0
    for current, raw_directories, raw_files in os.walk(
        resolved,
        topdown=True,
        followlinks=False,
    ):
        current_path = Path(current)
        raw_directories.sort()
        raw_files.sort()
        retained_directories: list[str] = []
        for name in [*raw_directories, *raw_files]:
            path = current_path / name
            metadata = path.lstat()
            relative = path.relative_to(resolved).as_posix()
            record: dict[str, object] = {
                "path": relative,
                "mode": f"{stat.S_IMODE(metadata.st_mode):04o}",
            }
            if stat.S_ISDIR(metadata.st_mode):
                if metadata.st_mode & 0o022:
                    raise T09HostError(f"{label} directory is writable")
                record["type"] = "directory"
                retained_directories.append(name)
            elif stat.S_ISREG(metadata.st_mode):
                if metadata.st_nlink != 1 or metadata.st_mode & 0o022:
                    raise T09HostError(f"{label} file metadata is unsafe")
                record.update(
                    {
                        "type": "file",
                        "bytes": metadata.st_size,
                        "sha256": file_sha256(path),
                    }
                )
                total_regular_bytes += metadata.st_size
            else:
                raise T09HostError(f"{label} contains a link or special file")
            entries.append(record)
            if (
                len(entries) > MAX_EVALUATOR_OVERLAY_ENTRIES
                or total_regular_bytes > MAX_EVALUATOR_OVERLAY_BYTES
            ):
                raise T09HostError(f"{label} exceeds its manifest bound")
        raw_directories[:] = retained_directories
    return {
        "root_mode": f"{stat.S_IMODE(root_metadata.st_mode):04o}",
        "entries": entries,
        "entry_count": len(entries),
        "total_regular_bytes": total_regular_bytes,
        "entries_sha256": canonical_sha256(entries),
    }


def local_interpreter_launcher_identity(path: Path) -> dict[str, object]:
    """Recompute the qualified venv launcher and resolved executable identity."""

    if not path.is_absolute():
        raise T09HostError("qualified local interpreter launcher is not absolute")
    launcher = Path(os.path.abspath(path))
    launcher_metadata = launcher.lstat()
    if launcher_metadata.st_uid != os.getuid() or launcher_metadata.st_nlink != 1:
        raise T09HostError("qualified local interpreter launcher metadata is unsafe")
    if stat.S_ISLNK(launcher_metadata.st_mode):
        launcher_type = "symlink"
        link_target: str | None = os.readlink(launcher)
        if not link_target or len(os.fsencode(link_target)) > 4_096 or "\0" in link_target:
            raise T09HostError("qualified local interpreter link target is unsafe")
    elif stat.S_ISREG(launcher_metadata.st_mode):
        launcher_type = "regular"
        link_target = None
        if launcher_metadata.st_mode & 0o022:
            raise T09HostError("qualified local interpreter launcher is writable")
    else:
        raise T09HostError("qualified local interpreter launcher is unsafe")
    resolved_target = launcher.resolve(strict=True)
    target_metadata = resolved_target.stat(follow_symlinks=False)
    if (
        resolved_target.is_symlink()
        or not stat.S_ISREG(target_metadata.st_mode)
        or target_metadata.st_uid != os.getuid()
        or target_metadata.st_nlink != 1
        or target_metadata.st_mode & 0o022
    ):
        raise T09HostError("qualified local interpreter target metadata is unsafe")
    return {
        "interpreter": launcher.as_posix(),
        "interpreter_sha256": file_sha256(launcher),
        "interpreter_launcher_type": launcher_type,
        "interpreter_launcher_mode": f"{stat.S_IMODE(launcher_metadata.st_mode):04o}",
        "interpreter_launcher_link_target": link_target,
        "interpreter_resolved_target": resolved_target.as_posix(),
        "interpreter_resolved_target_sha256": file_sha256(resolved_target),
    }


def _valid_retained_dependency_tree(value: object) -> bool:
    """Return whether a retained local dependency-tree manifest is canonical."""

    if not isinstance(value, dict) or set(value) != {
        "root_mode",
        "entries",
        "entry_count",
        "total_regular_bytes",
        "entries_sha256",
    }:
        return False
    entries = value.get("entries")
    if (
        not isinstance(entries, list)
        or not 0 < len(entries) <= MAX_EVALUATOR_OVERLAY_ENTRIES
        or value.get("entry_count") != len(entries)
        or value.get("entries_sha256") != canonical_sha256(entries)
        or not isinstance(value.get("root_mode"), str)
        or re.fullmatch(r"0[0-7]{3}", cast(str, value["root_mode"])) is None
    ):
        return False
    paths: set[str] = set()
    total = 0
    for raw in entries:
        if not isinstance(raw, dict):
            return False
        relative = raw.get("path")
        mode = raw.get("mode")
        kind = raw.get("type")
        if (
            not isinstance(relative, str)
            or not relative
            or PurePosixPath(relative).is_absolute()
            or ".." in PurePosixPath(relative).parts
            or relative in paths
            or not isinstance(mode, str)
            or re.fullmatch(r"0[0-7]{3}", mode) is None
            or kind not in {"directory", "file"}
        ):
            return False
        paths.add(relative)
        if kind == "directory":
            if set(raw) != {"path", "mode", "type"}:
                return False
            continue
        size = raw.get("bytes")
        digest = raw.get("sha256")
        if (
            set(raw) != {"path", "mode", "type", "bytes", "sha256"}
            or type(size) is not int
            or size < 0
            or not isinstance(digest, str)
            or _HEX64.fullmatch(digest) is None
        ):
            return False
        total += size
        if total > MAX_EVALUATOR_OVERLAY_BYTES:
            return False
    return value.get("total_regular_bytes") == total


def _validate_evaluator_overlay_inventory(
    *,
    overlay: Path,
    retained: dict[str, Any],
) -> None:
    observed = evaluator_overlay_inventory(overlay)
    for field in (
        "root_mode",
        "entries",
        "entry_count",
        "total_regular_bytes",
        "entries_sha256",
    ):
        if observed.get(field) != retained.get(field):
            raise T09HostError("realized evaluator overlay changed after qualification")


def evaluator_overlay(
    *,
    repository: Path,
    artifact_root: Path,
    overlay: Path,
    prefix: list[str],
    image_id: str,
    cleanup_journal: EarlyCleanupJournal,
    contract: T09ProviderContract,
) -> dict[str, object]:
    overlay.mkdir(mode=0o700, parents=True, exist_ok=False)
    command = [
        *prefix,
        "run",
        "--rm",
        *CORE_ULIMIT_DOCKER_ARGS,
        "--network",
        "bridge",
        "--log-driver",
        "none",
        "--user",
        "1000:1000",
        "--env",
        "UV_PROJECT_ENVIRONMENT=/opt/evaluator/.venv",
        "--env",
        "UV_CACHE_DIR=/opt/evaluator/cache",
        "--env",
        "CUDA_VISIBLE_DEVICES=",
        "--mount",
        f"type=bind,src={repository},dst=/opt/giclab-project,readonly",
        "--mount",
        f"type=bind,src={overlay},dst=/opt/evaluator",
        "--entrypoint",
        "/usr/local/bin/uv",
        image_id,
        "sync",
        "--frozen",
        "--only-group",
        "evaluator",
        "--no-install-project",
        "--project",
        "/opt/giclab-project",
        "--python",
        "/opt/sira/.venv/bin/python",
    ]
    materialization_evidence = _pilot_root(artifact_root) / "evaluator-overlay-materialization"
    materialization_evidence.mkdir(parents=True, mode=0o700, exist_ok=False)
    result = run_owned_docker(
        command,
        prefix=prefix,
        label="evaluator-overlay-sync",
        evidence_root=materialization_evidence,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        timeout=1_800,
        cleanup_journal=cleanup_journal,
        contract=contract,
    )
    if result.returncode != 0:
        raise T09HostError("exact evaluator overlay materialization failed")
    cache = overlay / "cache"
    if cache.exists():
        if cache.is_symlink() or not cache.is_dir():
            raise T09HostError("evaluator dependency cache has unsafe metadata")
        shutil.rmtree(cache)
    expected_packages = expected_evaluator_packages(repository, contract)
    packages = _evaluator_package_records(
        overlay=overlay,
        prefix=prefix,
        image_id=image_id,
        expected_packages=expected_packages,
        evidence_root=materialization_evidence,
        label="evaluator-package-freeze",
        cleanup_journal=cleanup_journal,
        contract=contract,
    )
    inventory = evaluator_overlay_inventory(overlay)
    manifest: dict[str, object] = {
        "schema_version": "0.1.0",
        "plan_id": contract.plan_id,
        "qualification_id": contract.active_image_qualification_id,
        "replacement_image_id": image_id,
        **inventory,
        "packages": packages,
        "packages_sha256": canonical_sha256(packages),
        "reviewed_expected_packages_sha256": canonical_sha256(expected_packages),
        "lock_sha256": file_sha256(repository / "uv.lock"),
        "network_materialization_only": True,
        "runtime_mount_read_only": True,
    }
    manifest_path = _pilot_root(artifact_root) / "evaluator-overlay-manifest.json"
    write_exclusive(manifest_path, manifest)
    return {
        "materialized": True,
        "network_mode": "bridge-dependency-materialization-only",
        "provider_or_model_request": False,
        "image_id": image_id,
        "lock_sha256": file_sha256(repository / "uv.lock"),
        "overlay_manifest_sha256": file_sha256(manifest_path),
        "overlay_entries_sha256": inventory["entries_sha256"],
        "overlay_package_manifest_sha256": manifest["packages_sha256"],
        "overlay_entry_count": inventory["entry_count"],
        "overlay_total_regular_bytes": inventory["total_regular_bytes"],
    }


def validate_evaluator_overlay_binding(
    *,
    artifact_root: Path,
    repository: Path,
    overlay: Path,
    prefix: list[str],
    image_id: str,
    frozen_manifest: dict[str, Any],
    verify_packages: bool,
    cleanup_journal: EarlyCleanupJournal,
    contract: T09ProviderContract,
) -> dict[str, object]:
    manifest_path = _pilot_root(artifact_root) / "evaluator-overlay-manifest.json"
    retained = load_object(manifest_path, label="evaluator overlay manifest")
    if (
        frozen_manifest.get("evaluator_overlay_manifest_sha256") != file_sha256(manifest_path)
        or retained.get("schema_version") != "0.1.0"
        or retained.get("plan_id") != contract.plan_id
        or retained.get("qualification_id") != contract.active_image_qualification_id
        or retained.get("replacement_image_id") != image_id
        or retained.get("entries_sha256") != frozen_manifest.get("evaluator_overlay_entries_sha256")
        or retained.get("packages_sha256")
        != frozen_manifest.get("evaluator_overlay_packages_sha256")
        or retained.get("reviewed_expected_packages_sha256")
        != canonical_sha256(expected_evaluator_packages(repository, contract))
        or retained.get("runtime_mount_read_only") is not True
    ):
        raise T09HostError("frozen evaluator overlay binding drifted")
    _validate_evaluator_overlay_inventory(overlay=overlay, retained=retained)
    if verify_packages:
        revalidation_base = _pilot_root(artifact_root) / "evaluator-overlay-revalidations"
        revalidation_base.mkdir(mode=0o700, parents=True, exist_ok=True)
        existing = sorted(path for path in revalidation_base.iterdir() if path.is_dir())
        expected_names = [f"revalidation-{index:04d}" for index in range(1, len(existing) + 1)]
        if [path.name for path in existing] != expected_names or len(existing) >= 64:
            raise T09HostError("evaluator overlay revalidation history is malformed or full")
        revalidation_root = revalidation_base / f"revalidation-{len(existing) + 1:04d}"
        revalidation_root.mkdir(mode=0o700, exist_ok=False)
        packages = _evaluator_package_records(
            overlay=overlay,
            prefix=prefix,
            image_id=image_id,
            expected_packages=expected_evaluator_packages(repository, contract),
            evidence_root=revalidation_root,
            label="evaluator-package-revalidation",
            cleanup_journal=cleanup_journal,
            contract=contract,
        )
        if packages != retained.get("packages") or canonical_sha256(packages) != retained.get(
            "packages_sha256"
        ):
            raise T09HostError("realized evaluator package set changed after qualification")
    return {
        "overlay_manifest_sha256": file_sha256(manifest_path),
        "overlay_entries_sha256": retained["entries_sha256"],
        "overlay_packages_sha256": retained["packages_sha256"],
        "packages_recomputed": verify_packages,
    }


def gpu_snapshot() -> dict[str, object]:
    try:
        result = subprocess.run(
            [
                "nvidia-smi",
                "--query-gpu=name,driver_version,utilization.gpu,memory.used,memory.total",
                "--format=csv,noheader,nounits",
            ],
            env=safe_environment(),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            check=False,
            timeout=30,
        )
    except (OSError, subprocess.TimeoutExpired):
        result = None
    rows = (
        result.stdout.decode("utf-8", errors="replace").strip().splitlines()
        if result is not None and result.returncode == 0
        else []
    )
    return {
        "captured_at": utc_now(),
        "host_gpu_visibility": "visible" if rows else "unavailable",
        "host_gpu_rows_without_unique_identifiers": rows,
        "pilot_container_gpu_device_request": "none",
        "pilot_container_cuda_visible_devices": "disabled-empty",
        "pilot_process_gpu_use": False,
        "gpu_acceleration_claim": False,
    }


def browser_lifecycle_preflight(
    *,
    artifact_root: Path,
    prefix: list[str],
    image_id: str,
    cleanup_journal: EarlyCleanupJournal,
    contract: T09ProviderContract,
) -> dict[str, object]:
    attempt = _pilot_root(artifact_root, contract) / "browser-preflight"
    attempt.mkdir(parents=True, mode=0o700)
    name = f"{contract.container_prefix}browser-preflight"
    plan_label = f"giclab.t09.plan={contract.plan_id}"
    host_label = f"giclab.t09.host_run={contract.host_run_id}"
    create = [
        *prefix,
        "create",
        *CORE_ULIMIT_DOCKER_ARGS,
        "--name",
        name,
        "--label",
        plan_label,
        "--label",
        host_label,
        "--label",
        "giclab.t09.role=browser-lifecycle-preflight",
        "--platform",
        "linux/amd64",
        "--network",
        "none",
        "--log-driver",
        "none",
        "--read-only",
        "--init",
        "--cap-drop",
        "ALL",
        "--security-opt",
        "no-new-privileges=true",
        "--shm-size",
        "1g",
        "--tmpfs",
        "/tmp:rw,noexec,nosuid,nodev,size=134217728,uid=1000,gid=1000,mode=0700",
        "--user",
        "1000:1000",
        "--env",
        "CUDA_VISIBLE_DEVICES=",
        "--mount",
        f"type=bind,src={attempt},dst=/giclab/attempt",
        "--mount",
        (
            "type=bind,src="
            f"{Path(__file__).resolve(strict=True).parents[1] / 'bounded/browser_preflight.py'},"
            "dst=/opt/giclab/browser_preflight.py,readonly"
        ),
        "--entrypoint",
        "/opt/sira/.venv/bin/python",
        image_id,
        "/opt/giclab/browser_preflight.py",
    ]
    started = False
    removed = False
    create_mutation_attempted = False
    created_identity: OwnedContainerIdentity | None = None
    state_receipt: dict[str, object] | None = None
    record: dict[str, Any] | None = None
    lifecycle_error: BaseException | None = None
    cleanup_result: CleanupTargetState | None = None
    cleanup_detail: str | None = None
    try:
        if _container_id_by_exact_name(prefix, name) is not None:
            raise T09HostError("browser-preflight Docker name is already occupied")
        write_exclusive(
            attempt / "container-command.json",
            {
                "schema_version": "0.1.0",
                "container_name": name,
                "argv": create,
                "argv_sha256": canonical_sha256(create),
                "owned_by_plan": contract.plan_id,
                "owned_by_host_run": contract.host_run_id,
                "owned_role": "browser-lifecycle-preflight",
            },
        )
        create_mutation_attempted = True
        run_logged(
            create,
            evidence_root=attempt,
            label="container-create",
            timeout=60,
            contract=contract,
        )
        created_identity = inspect_owned_container(
            prefix,
            name,
            expected_role="browser-lifecycle-preflight",
        )
        if created_identity is None:
            raise T09HostError("browser-preflight Docker identity disappeared after create")
        register_owned_container_cleanup(
            cleanup_journal,
            created_identity,
            role="browser-lifecycle-preflight",
        )
        write_exclusive(
            attempt / "container-identity.json",
            {
                "schema_version": "0.1.0",
                "container_name": name,
                "container_id": created_identity.container_id,
                "owned_by_plan": contract.plan_id,
                "owned_by_host_run": contract.host_run_id,
                "owned_role": "browser-lifecycle-preflight",
                "docker_create_argv_sha256": canonical_sha256(create),
            },
        )
        start_identity = inspect_owned_container(
            prefix,
            name,
            expected_container_id=created_identity.container_id,
            expected_role="browser-lifecycle-preflight",
        )
        if start_identity != created_identity:
            raise T09HostError("browser-preflight Docker identity changed before start")
        run_logged(
            [*prefix, "start", created_identity.container_id],
            evidence_root=attempt,
            label="container-start",
            timeout=60,
            contract=contract,
        )
        started = True
        deadline = time.monotonic() + 90
        record_path = attempt / "browser-preflight.json"
        while time.monotonic() < deadline and not record_path.is_file():
            time.sleep(0.25)
        if not record_path.is_file():
            raise T09HostError("browser lifecycle preflight did not produce evidence")
        record = load_object(record_path, label="browser preflight")
        browser_core_scan_path = attempt / "browser-writable-root-core-scan.json"
        browser_core_scan = (
            load_object(browser_core_scan_path, label="browser writable-root core scan")
            if browser_core_scan_path.is_file()
            else None
        )
        browser_core_count = (
            browser_core_scan.get("core_artifact_count")
            if isinstance(browser_core_scan, dict)
            else None
        )
        if (
            type(browser_core_count) is not int
            or browser_core_count < 0
            or record.get("writable_root_core_artifact_count") != browser_core_count
        ):
            mark_artifact_root_core_safety_stop(artifact_root)
            raise T09HostError("browser writable-root core evidence is malformed")
        if browser_core_count:
            mark_artifact_root_core_safety_stop(artifact_root)
            raise T09HostError("browser fixture detected a prohibited core artifact")
        run_logged(
            [*prefix, "wait", created_identity.container_id],
            evidence_root=attempt,
            label="container-wait",
            timeout=30,
            contract=contract,
        )
        if (
            record.get("network_mode") != "none"
            or record.get("source") != "local-static-file"
            or record.get("screenshot_captures") != 1
            or record.get("playwright_version") != "1.39.0"
            or record.get("chromium_revision") != "1084"
            or record.get("chromium_executable_sha256") != EXPECTED_CHROMIUM_SHA256
            or record.get("installed_package_manifest_sha256") != EXPECTED_PACKAGE_MANIFEST_SHA256
            or record.get("core_soft_limit") != 0
            or record.get("core_hard_limit") != 0
            or record.get("browser_running_before_container_stop") is not False
            or record.get("browser_closed_by_fixture") is not True
            or record.get("chromium_process_count_after_close") != 0
        ):
            raise T09HostError("browser lifecycle preflight identity drifted")
    except BaseException as exc:
        lifecycle_error = exc
    finally:
        if started:
            with contextlib.suppress(OSError, subprocess.SubprocessError):
                subprocess.run(
                    [
                        *prefix,
                        "stop",
                        "--time",
                        "10",
                        created_identity.container_id if created_identity is not None else name,
                    ],
                    env=safe_environment(),
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    check=False,
                    timeout=30,
                )
        try:
            state_receipt = container_state_receipt(
                prefix,
                created_identity.container_id if created_identity is not None else name,
            )
        except (OSError, subprocess.SubprocessError, T09HostError) as exc:
            state_receipt = {
                "status": "inspection-unavailable",
                "running": None,
                "inspection_error_type": type(exc).__name__,
                "private_network_fields_retained": False,
            }
            if lifecycle_error is None:
                lifecycle_error = exc
        if create_mutation_attempted:
            try:
                cleanup_identity = created_identity or inspect_owned_container(
                    prefix,
                    name,
                    expected_role="browser-lifecycle-preflight",
                )
                if cleanup_identity is None:
                    removed = True
                    cleanup_result, cleanup_detail = verified_owned_container_cleanup_result(
                        initially_absent=True,
                        removal_verified=True,
                        removed_detail="browser-preflight-container-removed",
                        absent_detail="browser-preflight-container-already-absent",
                    )
                else:
                    removed = remove_container(
                        prefix,
                        name,
                        expected_container_id=cleanup_identity.container_id,
                        expected_role="browser-lifecycle-preflight",
                    )
                    cleanup_result, cleanup_detail = verified_owned_container_cleanup_result(
                        initially_absent=False,
                        removal_verified=removed,
                        removed_detail="browser-preflight-container-removed",
                        absent_detail="browser-preflight-container-already-absent",
                    )
                    if cleanup_result is CleanupTargetState.FAILED and lifecycle_error is None:
                        lifecycle_error = T09HostError(
                            "browser-preflight container absence could not be verified"
                        )
            except (OSError, subprocess.SubprocessError, T09HostError) as exc:
                cleanup_result = CleanupTargetState.FAILED
                cleanup_detail = type(exc).__name__
                if lifecycle_error is None:
                    lifecycle_error = exc
        if (
            created_identity is not None
            and cleanup_result is not None
            and cleanup_detail is not None
        ):
            try:
                record_owned_container_cleanup_result(
                    cleanup_journal,
                    created_identity,
                    result=cleanup_result,
                    detail_code=cleanup_detail,
                )
            except EarlyCleanupStateError as exc:
                if lifecycle_error is None:
                    lifecycle_error = exc
    try:
        residue = _owned_containers_for(prefix, contract)
    except (OSError, subprocess.SubprocessError, T09HostError) as exc:
        residue = ["<owned-container-enumeration-unavailable>"]
        if lifecycle_error is None:
            lifecycle_error = exc
    browser_core_scan_path = attempt / "browser-writable-root-core-scan.json"
    browser_core_scan = (
        load_object(browser_core_scan_path, label="browser writable-root core scan")
        if browser_core_scan_path.is_file()
        else None
    )
    browser_core_count = (
        browser_core_scan.get("core_artifact_count")
        if isinstance(browser_core_scan, dict)
        else None
    )
    if type(browser_core_count) is int and browser_core_count > 0:
        mark_artifact_root_core_safety_stop(artifact_root)
        browser_core_destruction_verified = removed and not residue
        write_exclusive(
            attempt / "browser-internal-core-cleanup.json",
            {
                "schema_version": "0.1.0",
                "scope": "browser-container-writable-roots",
                "browser_writable_root_core_scan_sha256": file_sha256(browser_core_scan_path),
                "core_artifact_count": browser_core_count,
                "container_removed": removed,
                "owned_container_residue": residue,
                "destruction_verified": browser_core_destruction_verified,
                "credential_rotation_required_due_to_core_handling": (
                    not browser_core_destruction_verified
                ),
                "core_content_or_hash_retained": False,
                "campaign_continuation_permitted": False,
            },
        )
        lifecycle_error = T09HostError("browser fixture detected a prohibited core artifact")
    core_records = detect_core_artifacts(attempt)
    if core_records:
        mark_artifact_root_core_safety_stop(artifact_root)
        detection_sha256 = persist_core_detection_before_cleanup(
            receipt_path=attempt / "core-artifact-detection.json",
            records=core_records,
            scope="no-network-browser-teardown-preflight",
        )
        cleanup_outcome = cleanup_core_artifacts(attempt, core_records)
        write_exclusive(
            attempt / "core-artifact-cleanup.json",
            {
                "schema_version": "0.1.0",
                "scope": "no-network-browser-teardown-preflight",
                **core_cleanup_projection(core_records, cleanup_outcome),
                "core_detection_receipt_sha256": detection_sha256,
                "core_scan_integrity_failure": False,
                "empirical_entry_permitted": False,
            },
        )
        raise T09HostError("browser teardown created a prohibited core artifact")
    if lifecycle_error is not None:
        raise T09HostError("browser lifecycle preflight failed and cleanup was attempted") from (
            lifecycle_error
        )
    assert record is not None
    result = {
        "started": started,
        "local_static_page": True,
        "network_mode": "none",
        "screenshot_captured": (attempt / "browser-preflight.png").is_file(),
        "browser_cleanup_by_fixture": True,
        "browser_cleanup_by_container_stop": False,
        "container_removed": removed,
        "owned_container_residue": residue,
        "task_browser_action": False,
        "docker_ulimit": "core=0:0",
        "core_soft_limit": 0,
        "core_hard_limit": 0,
        "core_filename_count": 0,
        "elf_et_core_count": 0,
        "image_id": image_id,
        "chromium_executable_sha256": EXPECTED_CHROMIUM_SHA256,
        "installed_package_manifest_sha256": EXPECTED_PACKAGE_MANIFEST_SHA256,
        "container_state": state_receipt,
    }
    if (
        not all(
            (
                result["started"],
                result["screenshot_captured"],
                result["container_removed"],
                not residue,
            )
        )
        or state_receipt is None
        or state_receipt.get("status") != "exited"
        or state_receipt.get("running") is not False
        or state_receipt.get("paused") is not False
        or state_receipt.get("restarting") is not False
        or state_receipt.get("oom_killed") is not False
        or state_receipt.get("dead") is not False
        or state_receipt.get("exit_code") != 0
        or not isinstance(browser_core_scan, dict)
        or browser_core_scan.get("scan_roots") != ["/giclab/attempt", "/tmp", "/dev/shm"]
        or browser_core_scan.get("core_artifact_count") != 0
        or browser_core_scan.get("core_artifacts") != []
        or browser_core_scan.get("core_content_or_hash_retained") is not False
    ):
        raise T09HostError("browser startup or cleanup preflight failed")
    write_exclusive(attempt / "host-browser-lifecycle.json", result)
    return result


def complete_preflight_core_gate(
    *,
    artifact_root: Path,
    secret_file: Path,
    scope: str,
) -> dict[str, object]:
    """Prove every preflight-owned output is core-free at one freeze boundary."""

    if scope not in {"before-model-metadata", "after-model-metadata"}:
        raise T09HostError("complete preflight core-gate scope is invalid")
    destination = _pilot_root(artifact_root) / "preflight-core-integrity" / f"{scope}.json"
    try:
        records = detect_core_artifacts(artifact_root)
    except (OSError, T09HostError) as exc:
        mark_artifact_root_core_safety_stop(artifact_root)
        detection_sha256 = persist_core_detection_before_cleanup(
            receipt_path=(
                _pilot_root(artifact_root)
                / "preflight-core-integrity"
                / f"{scope}-core-detection.json"
            ),
            records=[],
            scope=f"complete-preflight-{scope}",
            scan_integrity_failure=True,
        )
        receipt = {
            "schema_version": "0.1.0",
            "scope": scope,
            "core_artifacts_detected": [],
            "core_artifact_count": 0,
            "core_content_or_hash_retained": False,
            "core_transferred_outside_remote_host": False,
            "core_scan_integrity_failure": True,
            "core_detection_receipt_sha256": detection_sha256,
            "destruction_verified": False,
            "cleanup_error_type": type(exc).__name__,
            "credential_rotation_required_due_to_core_handling": True,
            "empirical_entry_permitted": False,
        }
        write_exclusive(destination, receipt)
        raise T09HostError("complete preflight core scan was unreconstructable") from exc
    if records:
        # Detection is a permanent campaign stop even when destruction is
        # verified. Persist it before unlinking the prohibited artifact.
        mark_artifact_root_core_safety_stop(artifact_root)
    credential_bytes = validate_secret(secret_file) if records else b""
    detection_sha256 = persist_core_detection_before_cleanup(
        receipt_path=(
            _pilot_root(artifact_root) / "preflight-core-integrity" / f"{scope}-core-detection.json"
        ),
        records=records,
        scope=f"complete-preflight-{scope}",
        credential_bytes=credential_bytes,
    )
    outcome = cleanup_core_artifacts(artifact_root, records)
    receipt = {
        "schema_version": "0.1.0",
        "scope": scope,
        **core_cleanup_projection(
            records,
            outcome,
            credential_bytes=credential_bytes,
        ),
        "core_scan_integrity_failure": False,
        "core_detection_receipt_sha256": detection_sha256,
        "empirical_entry_permitted": not records,
    }
    credential_bytes = b""
    write_exclusive(destination, receipt)
    if records:
        raise T09HostError("a preflight child produced a prohibited core artifact")
    return receipt


